window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0068", [{"word":"membrane structure","ipa_uk":"/ˈmembrən ˈstrʌktʃə(r)/","ipa_us":"/ˈmembrən ˈstrʌktʃər/","definition_zh":"膜结构；生物膜的结构；由薄膜与支撑体系构成的构造方式","definition_en":"the arrangement of a thin sheet or membrane together with its supports, especially the layered organization of a biological membrane","core_image":"一张半透明的薄膜被细密支架绷开，膜面上嵌着一颗颗小颗粒，像绷紧的帐篷布上钉着一排纽扣","scene":"The membrane structure of a mitochondrion folds into cristae, packing a large surface into a small space.","sceneCN":"这里 membrane structure 指「生物膜的结构」（第 2 个义项：脂双层、膜蛋白与糖被按层次排布而成的构造）；内膜反复折叠成嵴，把大面积塞进小体积。图中可辨识物件：双层膜带、圆形膜蛋白、向内折的嵴、基质中的颗粒。","pos":[{"tag":"n.","zh":"膜结构；生物膜的结构（可数，复数为 membrane structures）"}],"collocations":[{"phrase":"cell membrane structure","zh":"细胞膜结构"},{"phrase":"membrane structure and function","zh":"膜的结构与功能"},{"phrase":"lipid bilayer structure","zh":"脂双层结构"},{"phrase":"membrane protein structure","zh":"膜蛋白结构"},{"phrase":"tensile membrane structure","zh":"张拉膜结构"},{"phrase":"membrane structure model","zh":"膜结构模型"}],"forms":[{"label":"复数","form":"membrane structures"},{"label":"形容词（膜的）","form":"membranous（膜的；膜状的）"},{"label":"形容词（结构的）","form":"structural（结构的）"},{"label":"相关名词","form":"membrane（膜）；structure（结构）"}],"derivatives":[{"word":"membrane","pos":"n.","zh":"膜；薄膜"},{"word":"membranous","pos":"adj.","zh":"膜的；膜状的"},{"word":"structure","pos":"n./v.","zh":"结构；构造 / 组织；构建"},{"word":"structural","pos":"adj.","zh":"结构的；构造的"},{"word":"restructure","pos":"v.","zh":"重组；重构"}],"senses":[{"no":"01","title":"A thin sheet held by a frame","titleCN":"膜结构：薄膜与支撑的组合","definition":"a construction made of a thin flexible sheet held open by a frame or a tension system","definitionCN":"由薄而柔的膜材被框架或张拉体系撑起而构成的构造","example":"The stadium roof is a membrane structure stretched over steel masts.","exampleCN":"体育场的屋顶是绷在钢桅杆上的膜结构。","why":"membrane names a thin skin and structure names the way parts are put together, so the pair reads literally as 'the building-together of a skin'.","whyCN":"membrane 指一层薄皮，structure 指部件如何搭起来，因此这个组合字面上就是「一层皮的搭法」。"},{"no":"02","title":"The layered plan of a biological membrane","titleCN":"生物膜的结构：分层排布","definition":"the layered organization of a biological membrane, with lipids, proteins and sugars in a settled arrangement","definitionCN":"生物膜的层次化组成方式：脂质、蛋白质与糖按一定格局排布","example":"The membrane structure of a cell is described as a fluid mosaic.","exampleCN":"细胞膜的结构被描述为流动镶嵌模型。","why":"once membrane named the cell boundary, its internal layering became a research object, and the compound settled on this sense.","whyCN":"当 membrane 用来指细胞边界，它的内部分层就成了研究对象，这个组合便固定在这一义项上。"},{"no":"03","title":"The three tiers seen under a microscope","titleCN":"膜的三层结构：脂双层、蛋白、糖被","definition":"the three-tier plan of a membrane: a lipid bilayer core, embedded proteins, and a sugar coat outside","definitionCN":"膜的三层安排：脂双层为芯、膜蛋白镶嵌其中、外侧覆盖糖被","example":"Electron micrographs first showed the three-tier membrane structure.","exampleCN":"电镜照片最早显示出膜的三层结构。","why":"the phrase is reused for the specific tiering once staining produced the dark-light-dark band pattern.","whyCN":"当染色能产生「暗—亮—暗」条带后，这个说法就被用来指那种具体的分层。"},{"no":"04","title":"A mobile order, not a rigid frame","titleCN":"流动的膜结构：可侧向移动的秩序","definition":"the property of membrane structure that its molecules slide sideways instead of staying fixed","definitionCN":"膜结构的一个特征：分子可以侧向滑动，而不是被固定住","example":"The fluid membrane structure lets proteins drift into new clusters.","exampleCN":"流动的膜结构让蛋白质能漂移成新的聚集体。","why":"because the sheet is a liquid rather than a solid, structure here means a mobile order rather than a stiff skeleton.","whyCN":"因为这层膜是液体而非固体，这里的 structure 指一种可动的秩序，而不是刚性骨架。"},{"no":"05","title":"Structure read as a rule of admission","titleCN":"结构读成准入规则：选择透过性","definition":"the way a membrane's arrangement decides which substances may pass through it","definitionCN":"膜的构造方式决定哪些物质能够通过","example":"Its selective membrane structure admits potassium but blocks sodium.","exampleCN":"它选择性通透的膜结构允许钾通过，却挡住钠。","why":"permeability follows directly from the plan of the sheet: a channel is a hole of fixed size, so the arrangement itself becomes a rule.","whyCN":"通透性直接来自膜的排布：通道就是尺寸固定的孔，因此排布本身就成了一条规则。"},{"no":"06","title":"Sheets used to wall a cell into rooms","titleCN":"分区结构：用内膜把细胞隔成区室","definition":"the use of internal membranes to divide a cell into separate compartments","definitionCN":"用内部膜把细胞分隔成若干区室的构造方式","example":"Membrane structure keeps digestive enzymes away from the rest of the cell.","exampleCN":"膜结构把消化酶与细胞其余部分隔开。","why":"when sheets are stacked into organelles, the same phrase names the partitioning plan rather than a single sheet.","whyCN":"当膜被叠成细胞器时，同一说法指的便是分区方案，而不再是一层膜本身。"},{"no":"07","title":"Engineering fabric and filter assemblies","titleCN":"工程膜结构：张拉膜与膜组件","definition":"in engineering, a load-bearing fabric or a filter assembly built from thin membrane elements","definitionCN":"工程上由薄膜构件承力或过滤的构造，如张拉膜屋顶与膜过滤组件","example":"The water plant replaced its old membrane structure with finer hollow fibres.","exampleCN":"水厂用更细的中空纤维替换了旧的膜组件。","why":"engineering borrowed membrane for any thin separating sheet and structure for the frame that carries it, so the compound transfers unchanged.","whyCN":"工程学借 membrane 指任何薄的隔离片，借 structure 指承载它的框架，于是这个组合被原样搬用。"},{"no":"08","title":"Any form carried by a surface","titleCN":"抽象义：由界面承托形态的构造","definition":"any arrangement whose shape is set by a boundary surface rather than by solid volume","definitionCN":"形态由界面而不是实体体积决定的任何构造","example":"A soap bubble is a membrane structure held by surface tension alone.","exampleCN":"肥皂泡是仅靠表面张力维持的膜结构。","why":"the common thread across the senses is a surface that carries the form, so the phrase extends to anything shaped by a skin.","whyCN":"各义项的共通点是一层承托形态的表面，因此这个说法可以延伸到任何被「皮」塑形的东西。"}],"etymology":{"intro":{"en":"Membrane comes from Latin membrana 'skin, parchment' and structure from Latin structura 'a building, an arrangement', built on struere 'to heap up, to build'. The dates below are approximate.","cn":"membrane 出自拉丁 membrana「皮、羊皮纸」，structure 出自拉丁 structura「建筑、安排」，后者基于 struere「堆起、建造」。以下年代均为约数。"},"items":[{"era":"LATIN MEMBRANA","en":"Latin membrana named a thin skin covering a body part and also a sheet of parchment. Its link to membrum 'limb' is generally accepted but not demonstrated, so the deeper origin is not certain.","cn":"拉丁 membrana 指覆盖身体某部分的薄皮，也指一张羊皮纸。它与 membrum「肢体」的联系被普遍接受，但并未得到证明，因此更深来源不确定。"},{"era":"LATIN STRUERE","en":"The verb struere meant 'to heap up, build, arrange'; structura named the result, a building or an arrangement of parts.","cn":"动词 struere 意为「堆起、建造、安排」；structura 指其结果，即建筑物或各部分的安排。"},{"era":"ENGLISH ARRIVAL","en":"Both words entered English in the fourteenth century, membrane through Old French, structure directly from Latin. The first citations are approximate.","cn":"两个词都在 14 世纪进入英语：membrane 经古法语传入，structure 直接来自拉丁语。最早书证年代为约数。"},{"era":"CELL THEORY","en":"Nineteenth-century cell theory made membrane the name of the cell boundary; once that boundary was studied as a layered object, membrane structure became a fixed term.","cn":"19 世纪细胞学说使 membrane 成为细胞边界的名称；当这道边界被当作分层对象研究后，membrane structure 就成了固定术语。"},{"era":"BILAYER AND MOSAIC","en":"The lipid bilayer was proposed in 1925 and the fluid mosaic model in 1972; both fixed the biological sense of the compound.","cn":"脂双层于 1925 年提出，流动镶嵌模型于 1972 年提出；两者共同固定了这个组合在生物学上的含义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper origin): no exact first citation records when the two words were joined into a fixed phrase; the origin of membrana before Latin is also unsettled, and any Indo-European form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词源）：两词何时组合成固定短语，无确切最早书证；membrana 在拉丁语之前的来源亦无定论，凡给出的印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin stock that are easily swapped; group two holds words that name the same biological object from a different angle.","cn":"第一组是同出拉丁词源、容易被替换的词；第二组是从不同角度命名同一生物对象的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"membrane","ipa":"/ˈmembrən/","tag":"the sheet itself","definition":"The thin sheet alone. It names the material, while membrane structure names how that material is laid out and held.","definitionCN":"只指那层薄片本身；它命名材料，而 membrane structure 命名材料如何排布与支撑。"},{"word":"membranous","ipa":"/ˈmembrənəs/","tag":"adjective, not a structure","definition":"Means 'like a membrane, thin and pliable'. It describes a quality and never the arrangement of parts.","definitionCN":"意为「膜一样的、薄而柔的」；描述一种性质，绝不指部件的排布。"},{"word":"structural","ipa":"/ˈstrʌktʃərəl/","tag":"about structure in general","definition":"Relates to structure in any field, such as structural steel or structural damage; it does not by itself imply a membrane.","definitionCN":"泛指任何领域的结构，如结构钢、结构损伤；本身并不含膜的意味。"},{"word":"substructure","ipa":"/ˈsʌbstrʌktʃə(r)/","tag":"the part underneath","definition":"The lower load-bearing part of a building, built with sub- 'under'. The word marks depth, not thinness.","definitionCN":"指建筑物的下部承重部分，由 sub-「在下」构成；这个词标记的是深度，不是薄度。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cell membrane","ipa":"/sel ˈmembrən/","tag":"the object, not its plan","definition":"The boundary of a cell as a thing. Membrane structure asks how that thing is built.","definitionCN":"指细胞边界这一事物；membrane structure 追问这个事物是如何构成的。"},{"word":"lipid bilayer","ipa":"/ˈlɪpɪd baɪˈleɪə(r)/","tag":"one layer plan","definition":"The two-molecule-thick lipid sheet that forms the core of most membranes; it is one component of the structure, not the whole plan.","definitionCN":"指构成多数膜核心的两分子厚脂质层；它是结构的一个部件，而不是整体方案。"},{"word":"envelope","ipa":"/ɪnˈveləp/","tag":"an outer wrapper","definition":"An outer covering, as of a virus or a cell nucleus. It stresses the wrapping role rather than the internal layering.","definitionCN":"指病毒或细胞核的外包被，强调包裹作用，而不是内部分层。"},{"word":"scaffold","ipa":"/ˈskæfəʊld/","tag":"the supporting frame","definition":"The frame that holds material in place. It names only the support half of a membrane structure.","definitionCN":"指把材料撑住的框架；只命名膜结构中的支撑那一半。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"membrane 'skin' + structure 'how parts are built': a built-up skin.","cn":"membrane「皮」+ structure「部件怎么搭」：一层搭起来的皮。"},{"en":"The family runs membrane, membranous, structure, structural, restructure.","cn":"同族词包括 membrane、membranous、structure、structural、restructure。"},{"en":"Fixed phrases mark the senses: cell membrane structure, membrane protein, lipid bilayer, tensile membrane structure.","cn":"固定搭配标出义项：细胞膜结构、膜蛋白、脂双层、张拉膜结构。"},{"en":"Biology reads it as three tiers: lipid bilayer, embedded proteins, sugar coat.","cn":"生物学把它读成三层：脂双层、镶嵌蛋白、糖被。"},{"en":"Engineering keeps the same words for tensile roofs and filter modules.","cn":"工程学用同样的词指张拉屋顶与过滤组件。"}],"abstract":[{"en":"Picture a tent: cloth, poles and ropes, nothing solid inside.","cn":"想象一顶帐篷：布、杆与绳，里面没有实体。"},{"en":"Picture a soap bubble whose round shape is made by its own surface.","cn":"想象一个肥皂泡，圆形的形状由它自己的表面造成。"},{"en":"Picture rooms divided by hanging cloth instead of brick walls.","cn":"想象房间不是用砖墙，而是用垂下的布分隔。"}]},"examples":[{"en":"The roof is a tensile membrane structure that needs no columns.","cn":"这座屋顶是无需立柱的张拉膜结构。"},{"en":"Cryo-electron microscopy resolved the membrane structure at atomic detail.","cn":"冷冻电镜把膜结构解析到原子细节。"},{"en":"Damage to the membrane structure stops the cell from holding its shape.","cn":"膜结构受损后，细胞无法再维持形状。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「膜（membrane）被结构（structure）撑起来」——一层薄皮加支撑体系 → 膜结构、生物膜的结构","word":"membrane structure"},"root":"拉丁 membrana「皮、羊皮纸」（与 membrum「肢体」的关系一般认为成立但未证实）+ 拉丁 structura「建筑、安排」，源自 struere「堆起、建造」；英语 membrane structure。","sensesIntro":{"en":"Eight senses follow one movement: a thin skin is held open, and that held-open skin is then read as a roof, a cell boundary, a tiered wall, a liquid order, a filter, or a mere surface that carries shape.","cn":"八个义项沿同一个动作展开：一层薄皮被撑开，而这层被撑开的皮可读成屋顶、细胞边界、分层墙、流动秩序、过滤器，或仅仅是一层承托形态的表面。"},"semanticMap":{"core":{"en":"CORE IMAGE: a thin skin stretched open by a frame and studded with parts.","cn":"核心意象：一层被框架绷开的薄皮，上面钉着部件。"},"chain":["THIN SHEET","SUPPORT FRAME","TWO LAYERS","EMBEDDED PARTS","MOBILE ORDER","WALLED ROOMS"],"branches":[{"senses":"S1 · S7","en":"BUILT SKIN: whether it is a stadium roof or a filter module, a sheet plus a frame is the literal reading.","cn":"搭起的皮：无论是体育场屋顶还是过滤组件，字面读法都是一层片加一副框架。"},{"senses":"S2 · S3","en":"LAYERED PLAN: the biological membrane is specified as tiers, first as a general plan and then as three visible bands.","cn":"分层方案：生物膜被具体化为层次，先是一般方案，再是三条可见的带。"},{"senses":"S4","en":"MOBILE ORDER: the sheet is liquid, so structure means an order that can drift.","cn":"可动秩序：这层片是液体，因此 structure 指可以漂移的秩序。"},{"senses":"S5","en":"RULE OF ADMISSION: the arrangement of channels becomes the rule for what enters.","cn":"准入规则：通道的排布成为什么能进入的规则。"},{"senses":"S6 · S8","en":"FORM BY SURFACE: from walled compartments to a soap bubble, a surface carries the shape.","cn":"以面成形：从隔出的区室到肥皂泡，形态都由一层表面承托。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin noun of thin covering to a Latin noun of building; its parts are two free words rather than a root plus a suffix.","cn":"这个短语把表示薄覆盖物的拉丁名词与表示建造的拉丁名词并置；两部分都是独立单词，而非词根加后缀。"},"latinIntro":{"en":"Latin membrana gives membrane and membranous; Latin struere gives structure, structural, restructure, infrastructure and obstruct, all through structura.","cn":"拉丁 membrana 衍生 membrane 与 membranous；拉丁 struere 经 structura 衍生 structure、structural、restructure、infrastructure 与 obstruct。"},"items":[{"word":"membrane","structure":"membrana (Latin noun, first declension)","meaning":"a thin skin or sheet","meaningCN":"薄皮；薄膜","example":"The membrane around the egg is only one cell thick.","exampleCN":"卵外的膜只有一层细胞厚。"},{"word":"membranous","structure":"membrane + -ous (full of, like)","meaning":"thin and pliable like a membrane","meaningCN":"像膜一样薄而柔的","example":"A membranous sac lined the cavity.","exampleCN":"一个膜状的囊衬在腔内。"},{"word":"structure","structure":"structura (Latin noun, first declension)","meaning":"a building; the arrangement of parts","meaningCN":"建筑物；各部分的安排","example":"The bone has a honeycomb structure.","exampleCN":"这块骨具有蜂窝状结构。"},{"word":"structural","structure":"structure + -al (relating to)","meaning":"belonging to the arrangement of parts","meaningCN":"与结构相关的","example":"The bridge failed for structural reasons.","exampleCN":"这座桥因结构原因失效。"},{"word":"restructure","structure":"re- (again) + structure","meaning":"to arrange the parts again","meaningCN":"重组；重构","example":"The company restructured its research division.","exampleCN":"公司重组了研究部门。"},{"word":"infrastructure","structure":"infra- (below) + structura","meaning":"the underlying framework of a system","meaningCN":"基础设施；底层框架","example":"Roads and pipes form the city's infrastructure.","exampleCN":"道路与管道构成城市的基础设施。"},{"word":"obstruct","structure":"ob- (against) + struere (to build)","meaning":"to build something in the way; to block","meaningCN":"挡在前面地筑起；阻塞","example":"A fallen beam obstructed the doorway.","exampleCN":"倒下的梁堵住了门口。"},{"word":"instruct","structure":"in- (into) + struere (to build)","meaning":"to build knowledge into someone; to teach","meaningCN":"把知识筑进某人；教导","example":"The manual instructs users to rinse the filter.","exampleCN":"手册指导使用者冲洗滤芯。"}],"latinEntries":[{"word":"membrana","structure":"membrana, membranae (f., first declension)","meaning":"thin skin; parchment","meaningCN":"薄皮；羊皮纸"},{"word":"membrum","structure":"membrum, membri (n., second declension)","meaning":"limb, part of the body","meaningCN":"肢体；身体的一部分"},{"word":"struere","structure":"struere (verb, third conjugation)","meaning":"to heap up, build, arrange","meaningCN":"堆起；建造；安排"},{"word":"structura","structure":"structura, structurae (f., first declension)","meaning":"a building; a mode of construction","meaningCN":"建筑物；构造方式"}]}},{"word":"mitochondrion","ipa_uk":"/ˌmaɪtəˈkɒndriən/","ipa_us":"/ˌmaɪtəˈkɑːndriən/","definition_zh":"线粒体；真核细胞中进行有氧呼吸与能量转化的细胞器","definition_en":"a membrane-bound organelle of eukaryotic cells that produces most of the cell's ATP by aerobic respiration and carries its own DNA","core_image":"一个椭圆形小囊，内膜反复向内折成层层皱褶，皱褶表面密布小颗粒，像塞满褶皱的暖手炉","scene":"Each mitochondrion in the flight muscle is packed with cristae, because this tissue burns fuel faster than any other.","sceneCN":"这里 mitochondrion 指「线粒体」这一细胞器整体（第 1 个义项：具双层膜、能进行有氧呼吸并产生 ATP 的细胞器）；飞行肌里它数量极多，因为耗能最快。图中可辨识物件：双层膜、向内折的嵴、基质颗粒、椭圆形轮廓。","pos":[{"tag":"n.","zh":"线粒体（可数，复数 mitochondria，源自希腊中性 -on 变 -a）"}],"collocations":[{"phrase":"mitochondrial membrane","zh":"线粒体膜"},{"phrase":"mitochondrial DNA","zh":"线粒体 DNA"},{"phrase":"mitochondrial cristae","zh":"线粒体嵴"},{"phrase":"mitochondrial matrix","zh":"线粒体基质"},{"phrase":"mitochondrial disease","zh":"线粒体病"},{"phrase":"mitochondrial inheritance","zh":"线粒体遗传"}],"forms":[{"label":"复数（希腊式）","form":"mitochondria"},{"label":"单数所有格","form":"mitochondrion's"},{"label":"形容词形式","form":"mitochondrial（线粒体的）"},{"label":"组合形式","form":"mito-（用于 mitogen、mitosis 等，另有来源说明见 similar）"}],"derivatives":[{"word":"mitochondrial","pos":"adj.","zh":"线粒体的"},{"word":"mitochondrion","pos":"n.","zh":"线粒体（单数）"},{"word":"mitochondria","pos":"n.","zh":"线粒体（复数）"},{"word":"mitochondrially","pos":"adv.","zh":"在线粒体层面地"},{"word":"mitochondriate","pos":"adj.","zh":"具线粒体的（原生生物学术语）"}],"senses":[{"no":"01","title":"The organelle itself","titleCN":"线粒体：细胞器本体","definition":"a double-membraned organelle of eukaryotic cells that carries out aerobic respiration","definitionCN":"真核细胞中具双层膜、进行有氧呼吸的细胞器","example":"A muscle fibre may hold thousands of mitochondria.","exampleCN":"一条肌纤维可容纳数千个线粒体。","why":"Greek mitos 'thread' and chondrion 'granule' were joined for a body seen as thread-like granules; the compound names the object, not its job.","whyCN":"希腊语 mitos「线」与 chondrion「小颗粒」被合成起来，指在染色下呈线状颗粒的小体；这个合成词命名的是对象，不是功能。"},{"no":"02","title":"Two membranes, folds and matrix","titleCN":"线粒体的构造：双层膜、嵴、基质","definition":"the internal architecture of the organelle: an outer membrane, an inner membrane folded into cristae, and the matrix inside","definitionCN":"该细胞器的内部构造：外膜、向内折成嵴的内膜，以及内部的基质","example":"The cristae multiply the inner surface where the electron transport chain sits.","exampleCN":"嵴成倍扩大了电子传递链所在的内膜面积。","why":"the thread-granule image gains structure: the granule is a sac, and its inner skin is thrown into folds.","whyCN":"「线状颗粒」这一意象获得了结构：颗粒是一个囊，其内皮被折成皱褶。"},{"no":"03","title":"The cell's aerobic power plant","titleCN":"线粒体的功能：有氧呼吸与产能","definition":"the organelle's role as the main site of aerobic respiration and ATP production","definitionCN":"该细胞器作为有氧呼吸与 ATP 生产主要场所的角色","example":"Without mitochondria the cell would rely on glycolysis alone.","exampleCN":"没有线粒体，细胞就只能依靠糖酵解。","why":"the granule was soon found to consume oxygen and release energy, so its name came to stand for the cell's power supply.","whyCN":"这种颗粒很快被发现消耗氧并释放能量，于是它的名字逐渐代指细胞的动力供应。"},{"no":"04","title":"The inner membrane as a battery","titleCN":"内膜与电子传递：把质子梯度变成电","definition":"the inner membrane, where the electron transport chain builds a proton gradient that drives ATP synthase","definitionCN":"内膜上电子传递链建立质子梯度、驱动 ATP 合酶的部位","example":"The inner mitochondrial membrane holds the pumps that acidify the intermembrane space.","exampleCN":"线粒体内膜上装着把膜间隙变酸的质子泵。","why":"the folded skin is read as a device: its folds stack the machinery that turns electrons into a gradient.","whyCN":"折起的皮被读成一台装置：皱褶把「把电子变成梯度」的机器叠放起来。"},{"no":"05","title":"The matrix where the cycle turns","titleCN":"基质：三羧酸循环的场所","definition":"the gel inside the inner membrane, where the citric acid cycle and mitochondrial DNA reside","definitionCN":"内膜内部的胶状物质，三羧酸循环与线粒体 DNA 所在之处","example":"Enzymes of the citric acid cycle float in the mitochondrial matrix.","exampleCN":"三羧酸循环的酶漂浮在线粒体基质中。","why":"the inside of the granule is given its own contents, so the organelle is also a chamber with a chemical address.","whyCN":"颗粒内部被赋予了自己的内容物，于是这个细胞器也是一个带化学「地址」的腔室。"},{"no":"06","title":"Its own DNA and maternal line","titleCN":"自有 DNA 与母系遗传","definition":"the small circular genome inside the organelle, inherited through the mother in most animals","definitionCN":"细胞器内部的小型环状基因组，在多数动物中经母系传递","example":"Mitochondrial DNA mutates fast and is passed only through the egg.","exampleCN":"线粒体 DNA 突变较快，且只经由卵细胞传递。","why":"the granule turned out to carry its own instructions, so it is read as a semi-independent tenant rather than a pure tool.","whyCN":"这种颗粒被发现自带指令，于是被读成半独立的住客，而不是纯粹的工具。"},{"no":"07","title":"Fission, fusion and a moving network","titleCN":"分裂与融合：动态网络","definition":"the organelle as a population that constantly divides and fuses, forming a network rather than fixed beads","definitionCN":"该细胞器作为不断分裂与融合的群体，形成网络而非固定的珠粒","example":"Live imaging shows mitochondria fusing and splitting within seconds.","exampleCN":"活细胞成像显示线粒体在数秒内融合与分裂。","why":"once filmed alive, the separate granules prove to be one shifting net, so the noun also names a dynamic system.","whyCN":"活体拍摄后，看似分离的颗粒显现为一张流动的网，因此这个名词也命名一个动态系统。"},{"no":"08","title":"Gatekeeper of programmed death","titleCN":"凋亡调控：生死开关","definition":"the organelle's role in releasing signals that commit a cell to programmed death","definitionCN":"该细胞器释放信号、决定细胞进入程序性死亡的角色","example":"Cytochrome release from mitochondria triggers the death cascade.","exampleCN":"线粒体释放细胞色素 c 会触发死亡级联。","why":"because it holds the energy and the signals, the organelle is read as a switch between living on and shutting down.","whyCN":"因为它同时掌握能量与信号，这个细胞器被读成「继续活」与「关机」之间的开关。"}],"etymology":{"intro":{"en":"Mitochondrion is a nineteenth-century scientific compound from Greek mitos 'thread' and chondrion, a diminutive of chondros 'grain, cartilage'. It is not a classical Latin word.","cn":"mitochondrion 是 19 世纪的科学合成词，来自希腊语 mitos「线」与 chondrion（chondros「颗粒、软骨」的指小形式）。它不是古典拉丁词。"},"items":[{"era":"GREEK MITOS","en":"Greek mitos named a warp thread and, by extension, anything thread-like. The older pre-Greek origin of the word is not established.","cn":"希腊语 mitos 指织机的经线，引申指任何线状物。该词在希腊语之前的更早来源并无定论。"},{"era":"GREEK CHONDROS","en":"chondros meant 'grain' and also 'cartilage'; its diminutive chondrion named a small granule. Both senses are classical.","cn":"chondros 意为「颗粒」，也指「软骨」；其指小形式 chondrion 指小颗粒。两个义项均为古典用法。"},{"era":"COINAGE 1898","en":"Carl Benda coined mitochondrium in 1898 for granules seen in stained cells. The plural mitochondria follows the Greek neuter pattern -on to -a.","cn":"Carl Benda 于 1898 年为染色细胞中见到的颗粒创造了 mitochondrium；复数 mitochondria 遵循希腊中性名词 -on 变 -a 的规则。"},{"era":"WHY THREAD-GRANULE","en":"Source uncertain: joining mitos to chondrion is generally explained as describing thread-like granules in muscle preparations, but Benda's own stated reason is not documented.","cn":"来源不确定：把 mitos 与 chondrion 组合起来，一般解释为描述肌肉标本中的线状颗粒，但 Benda 本人陈述的理由并无文献记录。"},{"era":"ENGLISH ADOPTION","en":"English took the word in the early twentieth century through German cytology; the first English citation is approximate.","cn":"英语于 20 世纪初经德国细胞学传入；最早的英语书证年代为约数。"},{"era":"NEW LATIN FORM","en":"New Latin mitochondrium is only a Latinized spelling of the Greek compound; it is not an inherited Latin word, so no classical Latin root should be claimed for it.","cn":"新拉丁语 mitochondrium 只是这个希腊合成词的拉丁化拼写，并非传承的拉丁词，因此不应为它主张古典拉丁词根。"}]},"similar":{"note":{"en":"Group one holds look-alikes built from the same Greek pieces but naming different things; group two holds other cell structures often confused with it.","cn":"第一组是同出希腊构词成分、却指不同事物的形近词；第二组是易与之混淆的其他细胞结构。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mitochondrial","ipa":"/ˌmaɪtəˈkɒndriəl/","tag":"adjective, not the object","definition":"The adjective meaning 'of or in a mitochondrion'. It cannot stand alone for the organelle itself.","definitionCN":"形容词，意为「线粒体的、线粒体内的」，不能单独指这个细胞器本身。"},{"word":"mitosis","ipa":"/maɪˈtəʊsɪs/","tag":"cell division, same mitos","definition":"Shares Greek mitos 'thread' because of the thread-like chromosomes, but names cell division, not an organelle.","definitionCN":"同出希腊 mitos「线」，因染色体呈线状而得名，但指细胞分裂，不是细胞器。"},{"word":"chondrocyte","ipa":"/ˈkɒndrəsaɪt/","tag":"cartilage cell, same chondros","definition":"Built on chondros 'cartilage' plus kytos 'cell'; it names a cartilage cell and has nothing to do with energy production.","definitionCN":"由 chondros「软骨」加 kytos「细胞」构成，指软骨细胞，与产能无关。"},{"word":"mitogen","ipa":"/ˈmaɪtədʒən/","tag":"a growth signal","definition":"From mitos 'thread' (via mitosis) plus -gen 'producer': a substance that triggers cell division, not a granule.","definitionCN":"由 mitos「线」经 mitosis 加 -gen「产生者」构成：触发细胞分裂的物质，不是颗粒。"}]},{"heading":"NEAR MEANING","entries":[{"word":"organelle","ipa":"/ɔːˈɡænel/","tag":"the general class","definition":"Any specialised compartment of a cell. A mitochondrion is one member of that class.","definitionCN":"指细胞内任何特化的区室；线粒体是这一类中的一个成员。"},{"word":"chloroplast","ipa":"/ˈklɔːrəplɑːst/","tag":"the plant counterpart","definition":"The plastid that runs photosynthesis. It also has its own DNA, but it captures energy instead of releasing it from fuel.","definitionCN":"进行光合作用的质体；它同样有自身 DNA，但它捕获能量，而不是从燃料中释放能量。"},{"word":"plastid","ipa":"/ˈplɑːstɪd/","tag":"the broader family","definition":"The plant-cell family of double-membraned organelles to which chloroplasts belong; mitochondria are a separate lineage.","definitionCN":"植物细胞中具双层膜的细胞器家族，叶绿体属于其中；线粒体是另一支系。"},{"word":"crista","ipa":"/ˈkrɪstə/","tag":"the fold, not the whole","definition":"One inward fold of the inner membrane. Cristae are parts of a mitochondrion, not the organelle.","definitionCN":"指内膜的一道向内皱褶；嵴是线粒体的一部分，而不是细胞器本身。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mitos 'thread' + chondrion 'granule': thread-like granules, the literal name Benda gave the organelle.","cn":"mitos「线」+ chondrion「颗粒」：线状颗粒，这正是 Benda 给该细胞器的字面命名。"},{"en":"The family runs mitochondrion, mitochondria, mitochondrial, mitochondrially.","cn":"同族词包括 mitochondrion、mitochondria、mitochondrial、mitochondrially。"},{"en":"Fixed phrases mark the parts: outer membrane, inner membrane, cristae, matrix, mitochondrial DNA.","cn":"固定搭配标出各部分：外膜、内膜、嵴、基质、线粒体 DNA。"},{"en":"Biology checks the numbers: prokaryote 70S versus eukaryote 80S ribosomes, and hundreds of mitochondria per liver cell.","cn":"生物学用数字核对：原核 70S 与真核 80S 核糖体，以及每个肝细胞数百个线粒体。"},{"en":"The plural -a is the Greek neuter rule, the same one behind phenomenon and phenomena.","cn":"复数 -a 是希腊中性规则，与 phenomenon 变 phenomena 同一条。"}],"abstract":[{"en":"Picture a small stove inside a room, its flues folded again and again to give off more heat.","cn":"想象房间里的小炉子，烟道反复折回以放出更多热。"},{"en":"Picture a bean-shaped sack whose inner lining is crumpled like paper packed into a jar.","cn":"想象一个豆形囊，内衬被揉皱得像塞进罐子的纸。"},{"en":"Picture a tenant who keeps a copy of the house key and can lock the door from inside.","cn":"想象一个租客自己留着一把钥匙，能从里面把门锁上。"}]},"examples":[{"en":"Sperm cells carry mitochondria in the midpiece to power the tail.","cn":"精子在中段携带线粒体，为尾部提供能量。"},{"en":"A mutation in mitochondrial DNA can impair hearing and muscle control.","cn":"线粒体 DNA 的突变可损害听力与肌肉控制。"},{"en":"The cristae of heart mitochondria are denser than those of skin cells.","cn":"心肌线粒体的嵴比皮肤细胞的更密。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「买（mito）一个会喘气的小颗粒（chondrion）」——细胞里不停烧燃料产能的颗粒 → 线粒体","word":"mitochondrion"},"root":"希腊 mitos「线」+ chondrion「小颗粒」（chondros「颗粒、软骨」的指小形式）→ 新拉丁 mitochondrium（1898）→ 英语 mitochondrion；复数 mitochondria。","sensesIntro":{"en":"Eight senses follow one movement: a thread-like granule is opened up, and that opening is read as a sac, a fold, a power plant, a battery, a chamber, a tenant with its own DNA, a moving net, and finally a death switch.","cn":"八个义项沿同一个动作展开：「线状颗粒」被拆开，而这一拆开依次被读成囊、皱褶、发电厂、电池、腔室、自带 DNA 的住客、流动的网，最后是生死开关。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small granule whose inner skin is folded into a stack of plates.","cn":"核心意象：一颗小颗粒，内皮被折成一叠板。"},"chain":["SMALL GRANULE","DOUBLE SAC","FOLDED LINING","PROTON GRADIENT","INNER CHAMBER","OWN GENOME"],"branches":[{"senses":"S1","en":"THE OBJECT NAMED: the compound starts as a label for a visible body in stained cells.","cn":"被命名的对象：这个合成词起初只是染色细胞中一个可见小体的标签。"},{"senses":"S2","en":"ARCHITECTURE: the granule is resolved into two membranes, folds and a matrix.","cn":"构造：颗粒被解析成两层膜、皱褶与基质。"},{"senses":"S3 · S4","en":"ENERGY: the folded lining is a power plant, and its folds are the battery plates.","cn":"能量：折起的内衬是发电厂，皱褶就是电池极板。"},{"senses":"S5 · S6","en":"CONTENTS: the inner chamber holds a chemical cycle and a private genome.","cn":"内容物：内腔装着一条化学循环与一份私有的基因组。"},{"senses":"S7 · S8","en":"LIFE AND DEATH: the population fuses and divides, and can also issue the order to die.","cn":"生与死：这一群体既融合分裂，也能发出死亡的指令。"}]},"affixes":{"intro":{"en":"Mitochondrion is a Greek compound behind a Latinized ending; the pieces are two bound combining forms, not a prefix plus root.","cn":"mitochondrion 是拉丁化词尾包裹的希腊合成词；其构件是两个粘着组合形式，而不是前缀加词根。"},"latinIntro":{"en":"There is no inherited Latin source. New Latin mitochondrium merely re-spells the Greek compound, and mitochondrial is the English adjective built with Latin -alis.","cn":"没有传承的拉丁来源。新拉丁语 mitochondrium 只是把这个希腊合成词改写为拉丁拼法，mitochondrial 则是用拉丁 -alis 构成的英语形容词。"},"items":[{"word":"mitochondrion","structure":"mitos + chondrion (Greek compound)","meaning":"a thread-like granule; the organelle","meaningCN":"线状颗粒；线粒体","example":"One mitochondrion was followed for ten minutes under the microscope.","exampleCN":"在显微镜下对单个线粒体追踪了十分钟。"},{"word":"mitochondria","structure":"mitochondrion + Greek -a (neuter plural)","meaning":"the plural of the organelle","meaningCN":"线粒体的复数","example":"The cell's mitochondria form a connected network.","exampleCN":"细胞的线粒体构成一个连通网络。"},{"word":"mitochondrial","structure":"mitochondrion + -al (relating to)","meaning":"of or belonging to mitochondria","meaningCN":"线粒体的","example":"Mitochondrial proteins are imported from the cytoplasm.","exampleCN":"线粒体蛋白由细胞质输入。"},{"word":"mitochondrially","structure":"mitochondrial + -ly (adverb)","meaning":"at the level of mitochondria","meaningCN":"在线粒体层面地","example":"The enzyme is mitochondrially located.","exampleCN":"这种酶定位于线粒体。"},{"word":"mitochondriate","structure":"mitochondrion + -ate (having)","meaning":"possessing mitochondria","meaningCN":"具线粒体的","example":"Amitochondriate protists lack the organelle entirely.","exampleCN":"无线粒体的原生生物完全没有这一细胞器。"},{"word":"mitochondriogenesis","structure":"mitochondrion + Greek genesis (origin)","meaning":"the formation of new mitochondria","meaningCN":"线粒体的生成","example":"Mitochondriogenesis requires both genomes.","exampleCN":"线粒体生成需要两套基因组。"},{"word":"mitochondriopathy","structure":"mitochondrion + Greek pathos (suffering)","meaning":"disease of the mitochondria","meaningCN":"线粒体病","example":"The child was diagnosed with a mitochondriopathy.","exampleCN":"该儿童被诊断出线粒体病。"},{"word":"mitochondrial DNA","structure":"mitochondrion + DNA (deoxyribonucleic acid)","meaning":"the small genome inside the organelle","meaningCN":"线粒体内的环状基因组","example":"Mitochondrial DNA is inherited from the mother.","exampleCN":"线粒体 DNA 由母方遗传。"}],"latinEntries":[]}},{"word":"mitochondrial","ipa_uk":"/ˌmaɪtəˈkɒndriəl/","ipa_us":"/ˌmaɪtəˈkɑːndriəl/","definition_zh":"线粒体的；与线粒体有关的；由线粒体编码、介导或定位的","definition_en":"relating to a mitochondrion, or produced, encoded, controlled or located within mitochondria","core_image":"一个细胞器被虚线框住，框线上贴着写有「属于它」的标签，框内的部件都染上同一种颜色","scene":"Mitochondrial DNA passes from mother to child, so it traces a single maternal line.","sceneCN":"这里 mitochondrial 指「线粒体自有的（由线粒体基因组编码的）」（第 3 个义项：由线粒体 DNA 编码或存在于其中的）；因此线粒体 DNA 只沿母系传递。图中可辨识物件：虚线框、标签、环状 DNA、母系箭头。","pos":[{"tag":"adj.","zh":"线粒体的；与线粒体相关的（通常不作定语以外的名词用）"}],"collocations":[{"phrase":"mitochondrial DNA","zh":"线粒体 DNA"},{"phrase":"mitochondrial membrane potential","zh":"线粒体膜电位"},{"phrase":"mitochondrial dysfunction","zh":"线粒体功能障碍"},{"phrase":"mitochondrial disease","zh":"线粒体病"},{"phrase":"mitochondrial matrix","zh":"线粒体基质"},{"phrase":"mitochondrial biogenesis","zh":"线粒体生成"},{"phrase":"mitochondrial inheritance","zh":"线粒体遗传"}],"forms":[{"label":"比较级（极少用）","form":"more mitochondrial"},{"label":"最高级（极少用）","form":"most mitochondrial"},{"label":"副词形式","form":"mitochondrially（在线粒体层面地）"},{"label":"名词原形","form":"mitochondrion（线粒体）"}],"derivatives":[{"word":"mitochondrion","pos":"n.","zh":"线粒体（单数）"},{"word":"mitochondria","pos":"n.","zh":"线粒体（复数）"},{"word":"mitochondrially","pos":"adv.","zh":"在线粒体层面地"},{"word":"mitochondriopathy","pos":"n.","zh":"线粒体病"},{"word":"mitochondriogenesis","pos":"n.","zh":"线粒体生成"}],"senses":[{"no":"01","title":"Belonging to the organelle","titleCN":"线粒体的：归属关系","definition":"relating to or belonging to a mitochondrion","definitionCN":"属于线粒体或与线粒体有关的","example":"Mitochondrial proteins are made partly in the cytosol and partly inside the organelle.","exampleCN":"线粒体蛋白一部分在细胞质中制造，一部分在细胞器内制造。","why":"the suffix -al turns the organelle's name into a label of belonging, so the adjective begins as a simple possessive.","whyCN":"后缀 -al 把细胞器的名称变成表示归属的标签，因此这个形容词的起点只是一个简单的所属关系。"},{"no":"02","title":"Located inside the organelle","titleCN":"线粒体内的：位置限定","definition":"situated or occurring inside mitochondria","definitionCN":"位于线粒体内部或在线粒体内发生的","example":"Mitochondrial calcium uptake shapes the organelle's response to stress.","exampleCN":"线粒体对钙的摄取塑造了该细胞器对压力的反应。","why":"once a thing has a boundary, the adjective can also mark where an event happens, not only whom it belongs to.","whyCN":"一旦某物有了边界，这个形容词也能标记事件发生的位置，而不只是所属关系。"},{"no":"03","title":"Encoded by the organelle's own genome","titleCN":"线粒体编码的：自身基因组来源","definition":"encoded by the small genome carried inside mitochondria rather than by the nucleus","definitionCN":"由线粒体内部携带的小基因组编码，而不是由细胞核编码","example":"Only thirteen proteins in humans are fully mitochondrial.","exampleCN":"人类只有十三种蛋白质完全由线粒体基因编码。","why":"the organelle turned out to hold its own instructions, so 'mitochondrial' came to mark origin of code as well as place.","whyCN":"该细胞器被发现自带指令，于是 mitochondrial 除了地点，也开始标记「编码来源」。"},{"no":"04","title":"Inherited through the mother","titleCN":"母系遗传的：沿卵细胞传递","definition":"passed down through the maternal line because mitochondria travel in the egg, not the sperm","definitionCN":"因线粒体随卵细胞而非精子传递，故沿母系向下遗传","example":"Mitochondrial inheritance explains why affected mothers pass the trait to all children.","exampleCN":"线粒体遗传解释了为何受累母亲会把该性状传给所有子女。","why":"because the genome sits outside the nucleus, its inheritance rule is separate, and the adjective names that route.","whyCN":"因为这份基因组在核外，其遗传规则自成一套，这个形容词命名的正是那条路径。"},{"no":"05","title":"Of disease caused by organelle failure","titleCN":"线粒体病的：由细胞器功能障碍引起","definition":"describing disease that arises from faulty mitochondrial function or genome","definitionCN":"描述由线粒体功能或基因组缺陷引发的疾病","example":"Patients with mitochondrial disease often show muscle weakness first.","exampleCN":"线粒体病患者常先出现肌无力。","why":"when the power plant fails, the whole body suffers, so the adjective attaches to a clinical category.","whyCN":"当发电厂出故障，全身都会受损，于是这个形容词附着在一个临床类别上。"},{"no":"06","title":"Of the membranes and their potential","titleCN":"线粒体膜的：膜与膜电位","definition":"relating to the organelle's membranes, especially the inner membrane and its electrical potential","definitionCN":"与线粒体膜相关，尤其指内膜及其电位","example":"A fall in mitochondrial membrane potential is an early sign of damage.","exampleCN":"线粒体膜电位下降是损伤的早期信号。","why":"the adjective narrows from the whole organelle to its two skins, because that is where the electrical work happens.","whyCN":"这个形容词从整个细胞器收窄到它的两层皮，因为电学工作正发生在那里。"},{"no":"07","title":"Targeted to the organelle","titleCN":"靶向线粒体的：研究与药物用语","definition":"describing a probe, drug or signal that is deliberately directed to mitochondria","definitionCN":"描述被有意导向线粒体的探针、药物或信号","example":"The team designed a mitochondrial antioxidant to reach the matrix.","exampleCN":"团队设计了一种线粒体抗氧化剂以进入基质。","why":"research practice adds a purposive sense: the adjective now marks a destination chosen by a designer.","whyCN":"科研实践加入了一层目的义：这个形容词现在标记一个由设计者选定的目的地。"},{"no":"08","title":"The cell's energetic core, figuratively","titleCN":"引申义：细胞能量核心的","definition":"used figuratively for whatever supplies the driving energy of a system","definitionCN":"引申指任何为系统提供驱动能量的事物","example":"The city's mitochondrial role is played by its port.","exampleCN":"这座城市里扮演「线粒体」角色的是它的港口。","why":"as the organelle stands for energy supply itself, the adjective can be borrowed for any source of power.","whyCN":"当这个细胞器本身就是能量供应的代名词，这个形容词便可借指任何动力来源。"}],"etymology":{"intro":{"en":"Mitochondrial is the English adjective on mitochondrion, with the Latin suffix -alis; the base is a Greek compound coined in 1898.","cn":"mitochondrial 是以 mitochondrion 为词干、加拉丁后缀 -alis 构成的英语形容词；词干是 1898 年创造的希腊合成词。"},"items":[{"era":"GREEK BASE","en":"mitos 'thread' plus chondrion 'small granule' produced mitochondrium; the adjective inherits that compound unchanged.","cn":"mitos「线」加 chondrion「小颗粒」产生 mitochondrium；形容词原样继承这个合成词。"},{"era":"LATIN SUFFIX -ALIS","en":"Latin -alis formed adjectives of relation, as in naturalis from natura. English keeps it as -al, so mitochondrion gives mitochondrial.","cn":"拉丁 -alis 构成表示关系的形容词，如 natura 变 naturalis。英语保留为 -al，于是 mitochondrion 变 mitochondrial。"},{"era":"NEW LATIN","en":"New Latin mitochondrium is a Latinized spelling, not an inherited word; no classical Latin root can be claimed for the base.","cn":"新拉丁语 mitochondrium 是拉丁化拼写，不是传承词；不应为该词干主张古典拉丁词根。"},{"era":"ENGLISH ADJECTIVE","en":"The adjective appears in English cytology in the early twentieth century, soon after the noun; the first citation is approximate.","cn":"该形容词于 20 世纪初随名词进入英语细胞学文献；最早书证年代为约数。"},{"era":"MATERNAL INHERITANCE","en":"Work on mitochondrial genetics in the mid-twentieth century fixed the senses 'encoded by' and 'inherited through the mother'.","cn":"20 世纪中期的线粒体遗传学研究固定了「由……编码」与「经母系遗传」两个义项。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation of the adjective is not recorded, and its derivational order relative to the noun is also unsettled.","cn":"来源不确定（首见年代）：该形容词的最早英语书证无确切记录；其与名词的派生先后亦无定论。"}]},"similar":{"note":{"en":"Group one holds words that share the same stem but differ in part of speech or in the organelle named; group two holds adjectives that answer a similar question about location or cause.","cn":"第一组是共享词干、但词性或所指细胞器不同的词；第二组是回答相同位置或来源问题的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mitochondrion","ipa":"/ˌmaɪtəˈkɒndriən/","tag":"the noun, not the adjective","definition":"The organelle itself, a count noun. Use it where a thing is meant, not a quality.","definitionCN":"指细胞器本身，是可数名词；需要指事物而非性质时用它。"},{"word":"mitosis","ipa":"/maɪˈtəʊsɪs/","tag":"division, same mitos","definition":"Cell division named from thread-like chromosomes; same Greek piece, entirely different process.","definitionCN":"因染色体呈线状而得名的一种细胞分裂；希腊构件相同，所指过程完全不同。"},{"word":"chondrocyte","ipa":"/ˈkɒndrəsaɪt/","tag":"cartilage cell, same chondros","definition":"A cartilage cell. Sharing chondros 'cartilage' does not make it an organelle word.","definitionCN":"软骨细胞；虽共享 chondros「软骨」，仍与细胞器无关。"},{"word":"mitochondrially","ipa":"/ˌmaɪtəˈkɒndriəli/","tag":"the adverb","definition":"Means 'at the level of mitochondria' and modifies a verb or adjective; it cannot modify a noun.","definitionCN":"意为「在线粒体层面」，修饰动词或形容词，不能修饰名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cytoplasmic","ipa":"/ˌsaɪtəʊˈplæsmɪk/","tag":"elsewhere in the cell","definition":"Located in the cytoplasm, that is, outside the organelle; it is the contrasted location, not a synonym.","definitionCN":"位于细胞质，即细胞器之外；它是相对立的位置，而非同义词。"},{"word":"organellar","ipa":"/ɔːˈɡænelə(r)/","tag":"of any organelle","definition":"Relating to organelles in general. Mitochondrial specifies which organelle, so the two differ in precision.","definitionCN":"泛指与细胞器相关；mitochondrial 指明是哪一个细胞器，二者精确度不同。"},{"word":"intracellular","ipa":"/ˌɪntrəˈseljələ(r)/","tag":"inside the cell at large","definition":"Inside a cell but not tied to any one compartment; it is a wider location word.","definitionCN":"在细胞内，但不限于某一区室；是范围更宽的位置词。"},{"word":"aerobic","ipa":"/eəˈrəʊbɪk/","tag":"using oxygen, not locating","definition":"Describes a process that needs oxygen. Mitochondrial respiration is aerobic, but the words answer different questions.","definitionCN":"描述需要氧的过程；线粒体呼吸是有氧的，但两词回答的不是同一个问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mitochondrion + -al: the '-al' is the same relational suffix as in natural and structural.","cn":"mitochondrion + -al：这个 -al 与 natural、structural 中的关系后缀相同。"},{"en":"The family runs mitochondrion, mitochondria, mitochondrial, mitochondrially, mitochondriopathy.","cn":"同族词包括 mitochondrion、mitochondria、mitochondrial、mitochondrially、mitochondriopathy。"},{"en":"Fixed phrases: mitochondrial DNA, membrane potential, dysfunction, biogenesis, inheritance.","cn":"固定搭配：线粒体 DNA、膜电位、功能障碍、生成、遗传。"},{"en":"Clinical use is easy to recall because the organelle's failure weakens muscle first.","cn":"临床用法好记，因为该细胞器出故障时最先受累的是肌肉。"},{"en":"The -al adjective answers 'whose?', 'where?' or 'made by whom?', and the context picks one.","cn":"这个 -al 形容词回答「谁的」「在哪」「由谁制造」，由上下文选定其中之一。"}],"abstract":[{"en":"Picture a dashed box drawn around one organelle, with everything inside tinted the same colour.","cn":"想象给一个细胞器画上虚线框，框内一切染成同一种颜色。"},{"en":"Picture a factory with its own small rulebook, separate from the city's law book.","cn":"想象一座工厂自带一本小规则书，与城市的法典分开。"},{"en":"Picture a power source so central that other buildings are named after the energy they draw from it.","cn":"想象一个动力源如此核心，以至于其他建筑都以它们从中获取的能量来命名。"}]},"examples":[{"en":"Mitochondrial proteins must cross two membranes to reach the matrix.","cn":"线粒体蛋白要穿过两层膜才能到达基质。"},{"en":"Exercise increases mitochondrial biogenesis in trained muscle.","cn":"运动会使受训肌肉的线粒体生成增加。"},{"en":"The drug was designed to spare mitochondrial function.","cn":"该药被设计为不损害线粒体功能。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「线粒体（mitochondrion）加个 -al」——凡贴上线粒体标签的 → 线粒体的、线粒体内的","word":"mitochondrial"},"root":"希腊 mitos「线」+ chondrion「小颗粒」→ 新拉丁 mitochondrium（1898）→ 英语名词 mitochondrion + 拉丁关系后缀 -alis → mitochondrial。","sensesIntro":{"en":"Eight senses fan out from one possessive suffix: a thing belongs to the organelle, then lies inside it, is coded by it, is inherited through it, is diseased through it, is specified to its membranes, is aimed at it, or finally stands for energy itself.","cn":"八个义项从一个表所属的后缀散开：先属于该细胞器，再位于其内、由其编码、经其遗传、因其而病、具体到其膜、被有意指向它，最后甚至代指能量本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dashed boundary drawn around one organelle, tinting everything inside as 'its'.","cn":"核心意象：围绕一个细胞器画出的虚线边界，把其中一切都染成「它的」。"},"chain":["BELONGING","INSIDE THE BOUNDARY","CODED HERE","INHERITED THIS WAY","FAILURE HERE","MEMBRANE WORK"],"branches":[{"senses":"S1","en":"POSSESSION: the plainest reading, a label of belonging attached by -al.","cn":"所属：最朴素的读法，即由 -al 附上的归属标签。"},{"senses":"S2","en":"LOCATION: the boundary also marks where an event takes place.","cn":"位置：边界同时标记事件发生的地点。"},{"senses":"S3 · S4","en":"ORIGIN OF CODE AND ROUTE: the organelle's own genome and the maternal path it travels.","cn":"编码来源与传递路径：细胞器自有基因组，以及它沿母系传递的路径。"},{"senses":"S5","en":"FAILURE: when this boundary malfunctions, the adjective names a clinical category.","cn":"故障：当这条边界失灵，该形容词命名一个临床类别。"},{"senses":"S6 · S7 · S8","en":"NARROWING AND EXTENDING: from the two membranes, to a chosen target, to any source of power.","cn":"收窄与外扩：从两层膜，到被选定的靶点，再到任何动力来源。"}]},"affixes":{"intro":{"en":"The adjective is a Greek scientific stem plus the Latin relational suffix -alis; the suffix does the grammatical work.","cn":"这个形容词由希腊科学词干加拉丁关系后缀 -alis 构成；语法工作由后缀承担。"},"latinIntro":{"en":"No inherited Latin base exists; only the suffix -alis is Latin, and New Latin mitochondrium is a re-spelling of the Greek compound.","cn":"没有传承的拉丁词干；只有后缀 -alis 属拉丁语，新拉丁语 mitochondrium 只是希腊合成词的改写。"},"items":[{"word":"mitochondrial","structure":"mitochondrion + -alis (relational)","meaning":"relating to mitochondria","meaningCN":"线粒体的","example":"Mitochondrial membranes are rich in cardiolipin.","exampleCN":"线粒体膜富含心磷脂。"},{"word":"mitochondrially","structure":"mitochondrial + -ly (adverb)","meaning":"in respect of mitochondria","meaningCN":"在线粒体方面地","example":"The pathway is mitochondrially regulated.","exampleCN":"该通路受线粒体调控。"},{"word":"mitochondrion","structure":"mitos + chondrion","meaning":"the organelle","meaningCN":"线粒体","example":"Each mitochondrion has its own genome.","exampleCN":"每个线粒体都有自己的基因组。"},{"word":"mitochondria","structure":"Greek neuter plural -a","meaning":"plural of the organelle","meaningCN":"线粒体（复数）","example":"Mitochondria divide independently of the cell cycle.","exampleCN":"线粒体可独立于细胞周期分裂。"},{"word":"mitochondriopathy","structure":"mitochondrion + pathos (suffering)","meaning":"mitochondrial disease","meaningCN":"线粒体病","example":"Mitochondriopathy affects tissues that need much energy.","exampleCN":"线粒体病影响高耗能组织。"},{"word":"mitochondriogenesis","structure":"mitochondrion + genesis (origin)","meaning":"formation of new mitochondria","meaningCN":"线粒体生成","example":"Cold exposure stimulates mitochondriogenesis in fat.","exampleCN":"寒冷刺激会促进脂肪中的线粒体生成。"},{"word":"mitochondrial DNA","structure":"mitochondrial + DNA","meaning":"the organelle's own circular genome","meaningCN":"线粒体 DNA","example":"Mitochondrial DNA has few repair enzymes.","exampleCN":"线粒体 DNA 的修复酶很少。"},{"word":"mitochondrial matrix","structure":"mitochondrial + matrix (Latin 'womb, mould')","meaning":"the inner compartment of the organelle","meaningCN":"线粒体基质","example":"The matrix holds the enzymes of the citric acid cycle.","exampleCN":"基质容纳三羧酸循环的酶。"}],"latinEntries":[{"word":"-alis","structure":"adjective suffix, third declension","meaning":"relating to, belonging to","meaningCN":"与……相关的；属于……的"},{"word":"matrix","structure":"matrix, matricis (f., third declension)","meaning":"womb; a mould; the ground substance","meaningCN":"子宫；模子；基质"}]}},{"word":"ribosome","ipa_uk":"/ˈraɪbəsəʊm/","ipa_us":"/ˈraɪbəsoʊm/","definition_zh":"核糖体；由 rRNA 与蛋白质组成、在细胞内合成蛋白质的颗粒状细胞器","definition_en":"a particle made of ribosomal RNA and proteins on which messenger RNA is translated into protein","core_image":"上下两片不规则的大块夹住一条细长的带子，带子从两片之间穿过，旁边不断掉下小珠子串成链","scene":"A ribosome reads the message in mRNA and joins amino acids into a chain.","sceneCN":"这里 ribosome 指「核糖体」这一细胞器整体（第 1 个义项：由 rRNA 与蛋白组成、进行翻译的颗粒）；它读取 mRNA 上的信息并把氨基酸连成链。图中可辨识物件：大亚基、小亚基、穿过的 mRNA 带、串起的氨基酸链。","pos":[{"tag":"n.","zh":"核糖体（可数，复数 ribosomes）"}],"collocations":[{"phrase":"ribosome binding site","zh":"核糖体结合位点"},{"phrase":"ribosome profiling","zh":"核糖体印迹测序"},{"phrase":"ribosome assembly","zh":"核糖体组装"},{"phrase":"ribosome structure","zh":"核糖体结构"},{"phrase":"ribosome biogenesis","zh":"核糖体生成"},{"phrase":"bound ribosome","zh":"附着核糖体"}],"forms":[{"label":"复数","form":"ribosomes"},{"label":"形容词形式","form":"ribosomal（核糖体的）"},{"label":"组合形式","form":"ribo-（核糖核酸相关，如 ribozyme、ribose）"},{"label":"相关名词","form":"rRNA（核糖体 RNA）"}],"derivatives":[{"word":"ribosomal","pos":"adj.","zh":"核糖体的"},{"word":"polysome","pos":"n.","zh":"多聚核糖体"},{"word":"ribozyme","pos":"n.","zh":"核酶（具催化活性的 RNA）"},{"word":"ribosome","pos":"n.","zh":"核糖体"},{"word":"ribosomal RNA","pos":"n.","zh":"核糖体 RNA（rRNA）"}],"senses":[{"no":"01","title":"The particle that makes protein","titleCN":"核糖体：合成蛋白质的颗粒","definition":"the RNA-protein particle in a cell on which proteins are assembled","definitionCN":"细胞内由 RNA 与蛋白质组成、组装蛋白质的颗粒","example":"Every cell needs thousands of ribosomes to keep up with protein demand.","exampleCN":"每个细胞都需要成千上万个核糖体才能满足蛋白质需求。","why":"ribo- points to ribonucleic acid and -some to a body, so the coined word names a body made of RNA.","whyCN":"ribo- 指向核糖核酸，-some 指向「体」，因此这个新造词命名一个由 RNA 构成的「体」。"},{"no":"02","title":"Two kinds of material in one particle","titleCN":"组成：rRNA 加蛋白质","definition":"the composition of the particle, roughly two thirds RNA and one third protein in bacteria","definitionCN":"该颗粒的组成，在细菌中约三分之二为 RNA、三分之一为蛋白质","example":"Ribosomal RNA forms the core that holds the proteins in place.","exampleCN":"核糖体 RNA 构成核心，把蛋白质固定在位。","why":"the particle was first seen as a granule and only later shown to be a mixture, so the name covers its material as well.","whyCN":"该颗粒起初只被当作一种颗粒，后来才被证明是混合物，于是这个名字也覆盖了它的材料。"},{"no":"03","title":"The act of translation","titleCN":"功能：翻译成链","definition":"the particle's function of translating a messenger RNA sequence into an amino acid chain","definitionCN":"把信使 RNA 的序列翻译成氨基酸链的功能","example":"On the ribosome, codons are matched to transfer RNAs one by one.","exampleCN":"在核糖体上，密码子被逐个与转运 RNA 配对。","why":"because the particle reads one code and writes another, its name is used for the act of translation itself.","whyCN":"因为这颗粒读一种编码、写另一种编码，它的名字也被用于翻译这个动作本身。"},{"no":"04","title":"A large and a small subunit","titleCN":"大小两个亚基","definition":"the two-subunit architecture, a small subunit that binds messenger RNA and a large subunit that forms the exit tunnel","definitionCN":"双亚基构造：小亚基结合信使 RNA，大亚基形成出口通道","example":"The small ribosomal subunit selects the start codon.","exampleCN":"核糖体小亚基负责选择起始密码子。","why":"electron microscopy resolved one particle into two unequal halves, so the word also names that division.","whyCN":"电镜把一个颗粒解析为大小不等的两半，于是这个词也指这种分法。"},{"no":"05","title":"Many at once on one message","titleCN":"多聚核糖体：一条信使上串多个颗粒","definition":"a group of ribosomes translating the same message simultaneously, forming a polysome","definitionCN":"多个核糖体同时翻译同一条信使而形成的多聚核糖体","example":"Polysomes let a cell produce many copies of one protein quickly.","exampleCN":"多聚核糖体让细胞迅速产生同一蛋白的许多拷贝。","why":"when several particles were seen spaced along one thread, the singular name was extended to the collective.","whyCN":"当人们看到多个颗粒沿一条细线排开，单数名称便扩展到这个集合。"},{"no":"06","title":"The docking site on a message","titleCN":"结合位点：信使上的停靠处","definition":"the sequence in a messenger RNA where the ribosome attaches and starts translation","definitionCN":"信使 RNA 上核糖体附着并开始翻译的序列","example":"A strong ribosome binding site raises the yield of the encoded protein.","exampleCN":"强核糖体结合位点会提高所编码蛋白的产量。","why":"the particle must stand somewhere before it works, so its name attaches to the landing pad as well.","whyCN":"这颗粒工作之前必须站到某处，于是它的名字也附着在「停机坪」上。"},{"no":"07","title":"A target for antibiotics","titleCN":"药物靶点：抗生素作用的部位","definition":"the particle regarded as a drug target, because bacterial and human ribosomes differ enough to be told apart","definitionCN":"把该颗粒视为药物靶点，因为细菌与人的核糖体差异足以区分","example":"Streptomycin binds the bacterial ribosome and blocks its proofreading.","exampleCN":"链霉素结合细菌核糖体并阻断其校对。","why":"since the particle differs between kingdoms, medicine reads it as a place where one kind can be hit without the other.","whyCN":"由于该颗粒在不同界之间互有差异，医学把它读成「可打击一类而不伤另一类」的位置。"},{"no":"08","title":"The conserved core of translation","titleCN":"进化保守性：翻译机制的共同核心","definition":"the particle as a deeply conserved structure shared by all living cells, with bacterial 70S and eukaryotic 80S versions","definitionCN":"该颗粒作为所有活细胞共有的高度保守结构，细菌为 70S、真核为 80S","example":"The ribosome's catalytic core is RNA, a trace of the RNA world.","exampleCN":"核糖体的催化核心是 RNA，这是 RNA 世界的一条痕迹。","why":"its shape is so similar across species that the particle is read as a fossil of early life, not just a machine.","whyCN":"它在各物种间形状极为相似，因此被读成早期生命的化石，而不只是一台机器。"}],"etymology":{"intro":{"en":"Ribosome is a twentieth-century coinage from ribo-, short for ribonucleic acid, plus -some from Greek soma 'body'. It has no classical Latin ancestry.","cn":"ribosome 是 20 世纪的合成词：ribo- 是 ribonucleic acid 的缩略，-some 来自希腊 soma「身体」。它没有古典拉丁语源。"},"items":[{"era":"GREEK SOMA","en":"Greek soma meant 'body'. The scientific suffix -some had already been used for cell bodies and particles before ribosome appeared.","cn":"希腊 soma 意为「身体」。在 ribosome 出现之前，科学后缀 -some 已用于指细胞体和颗粒。"},{"era":"RIBO- FROM RNA","en":"ribo- is a shortening of ribonucleic acid, named from ribose, the sugar first identified in the 1890s.","cn":"ribo- 是 ribonucleic acid 的缩略，后者由 ribose 得名，这种糖于 1890 年代被鉴定。"},{"era":"COINAGE IN THE 1950s","en":"Source uncertain (first date and coiner): the word is generally credited to Richard B. Roberts around 1958, but the exact date and occasion are not firmly documented.","cn":"来源不确定（首见年代与首创者）：一般认为由 Richard B. Roberts 于 1958 年前后提出，但确切年代与场合并无坚实文献记录。"},{"era":"SEEING THE PARTICLES","en":"Electron microscopy in the mid-1950s showed dense granules on the endoplasmic reticulum, and the name was applied to them.","cn":"20 世纪 50 年代中期的电镜显示内质网上有致密颗粒，该名称被用在这些颗粒上。"},{"era":"MOLECULAR ERA","en":"In the 1960s and 1970s the particle was resolved into subunits and its RNA core was shown to be catalytic, fixing the modern senses.","cn":"20 世纪 60 至 70 年代，该颗粒被解析出亚基，其 RNA 核心被证明具催化性，现代义项由此固定。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): ribose itself is named from arabinose by reversing a letter, and the reason for that reversal is not documented.","cn":"来源不确定（更深词源）：ribose 之名是把 arabinose 颠倒一个字母而来，而这样颠倒的理由并无文献记录。"}]},"similar":{"note":{"en":"Group one holds words that share a piece with ribosome but name different objects; group two holds words for the same machinery seen from another angle.","cn":"第一组是与 ribosome 共享构件、但指不同对象的词；第二组是从另一角度命名同一套机器的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ribosomal","ipa":"/raɪˈbɒsəməl/","tag":"adjective, not the particle","definition":"The adjective 'of the ribosome'. It describes RNA, proteins or sites, never the particle as a countable thing.","definitionCN":"形容词「核糖体的」，描述 RNA、蛋白或位点，不能作可数名词指颗粒本身。"},{"word":"ribozyme","ipa":"/ˈraɪbəzaɪm/","tag":"RNA with catalytic power","definition":"An RNA molecule that catalyses a reaction, including the ribosome's own core. It is a molecule, not a particle.","definitionCN":"具催化作用的 RNA 分子，包括核糖体自身的核心；是分子，不是颗粒。"},{"word":"ribose","ipa":"/ˈraɪbəʊz/","tag":"the sugar, not the body","definition":"The five-carbon sugar in RNA. It shares the ribo- piece but names a chemical, not a structure.","definitionCN":"RNA 中的五碳糖；共享 ribo- 构件，但指一种化学物质，不是结构。"},{"word":"lysosome","ipa":"/ˈlaɪsəsəʊm/","tag":"digestion, same -some","definition":"A digestive organelle built with -some 'body'. Sharing the suffix does not make it part of translation.","definitionCN":"由 -some「体」构成的消化细胞器；后缀相同，但与翻译无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"polysome","ipa":"/ˈpɒlɪsəʊm/","tag":"a group of them","definition":"Several ribosomes on one messenger RNA. It is the collective, while ribosome is one unit.","definitionCN":"一条信使 RNA 上的多个核糖体；它是集合，ribosome 是单个单位。"},{"word":"rRNA","ipa":"/ˌɑːrˈɑːrˈeɪ/","tag":"one component","definition":"Ribosomal RNA, the structural and catalytic core. It is a molecule inside the particle, not the particle.","definitionCN":"核糖体 RNA，是结构与催化核心；它只是颗粒内部的分子。"},{"word":"organelle","ipa":"/ɔːˈɡænel/","tag":"the general class","definition":"Any specialised cell compartment. The ribosome is sometimes called one, though it lacks a membrane.","definitionCN":"指任何特化的细胞区室；核糖体有时也被称为细胞器，尽管它没有膜。"},{"word":"translation","ipa":"/trænsˈleɪʃn/","tag":"the process, not the machine","definition":"The whole process of making protein from messenger RNA, of which the ribosome is the site.","definitionCN":"指由信使 RNA 制造蛋白质的全过程，核糖体是这一过程的场所。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ribo- (RNA) + -some (body): the RNA body that makes protein.","cn":"ribo-（RNA）+ -some（体）：造蛋白质的 RNA 之体。"},{"en":"The family runs ribosome, ribosomal, rRNA, polysome, ribozyme.","cn":"同族词包括 ribosome、ribosomal、rRNA、polysome、ribozyme。"},{"en":"Fixed phrases mark the parts: small subunit, large subunit, binding site, exit tunnel, polysome.","cn":"固定搭配标出部件：小亚基、大亚基、结合位点、出口通道、多聚核糖体。"},{"en":"Two numbers separate the kingdoms: bacterial 70S, eukaryotic 80S.","cn":"两个数字区分生物界：细菌 70S，真核 80S。"},{"en":"The ribosome is a ribozyme at heart: its catalytic core is RNA, not protein.","cn":"核糖体本质上是核酶：催化核心是 RNA，不是蛋白质。"}],"abstract":[{"en":"Picture two uneven fists closing around a paper tape and reading it letter by letter.","cn":"想象两只大小不一的拳头夹住一条纸带，逐字读取。"},{"en":"Picture a workbench where a long instruction is copied into a string of beads.","cn":"想象一张工作台，把一条长指令抄成一串珠子。"},{"en":"Picture a factory so old that every later factory still uses its original jig.","cn":"想象一座工厂古老到后来所有工厂都仍在用它的原始夹具。"}]},"examples":[{"en":"Antibiotics that block the bacterial ribosome spare human cells.","cn":"阻断细菌核糖体的抗生素不会伤害人体细胞。"},{"en":"Ribosome profiling measures which messages are being translated at any moment.","cn":"核糖体印迹测序测定任一时点正在被翻译的信使。"},{"en":"Without functional ribosomes, a cell cannot replace its enzymes.","cn":"没有功能正常的核糖体，细胞就无法更换自己的酶。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「来（ribo）一个身体（some）」——RNA 加蛋白组成的小身体，专门造蛋白 → 核糖体","word":"ribosome"},"root":"ribo-（ribonucleic acid 的缩略，源自核糖 ribose）+ 希腊 soma「身体」（科学后缀 -some）→ 英语 ribosome（1950 年代）。","sensesIntro":{"en":"Eight senses follow one movement: a body made of RNA holds a tape and writes beads, and that writing is read as composition, as translation, as two halves, as a crowd, as a docking pad, as a drug target, and as a fossil.","cn":"八个义项沿同一个动作展开：一个由 RNA 构成的「体」夹住一条带子并写下珠子，而这次书写依次被读成组成、翻译、两半、群体、停靠处、药物靶点与化石。"},"semanticMap":{"core":{"en":"CORE IMAGE: two lumps of RNA and protein gripping a tape and clicking beads into a chain.","cn":"核心意象：两团 RNA 与蛋白夹住一条带子，把珠子扣成链。"},"chain":["RNA BODY","TWO MATERIALS","READ THE TAPE","TWO HALVES","MANY ON ONE TAPE","ANCIENT CORE"],"branches":[{"senses":"S1","en":"THE NAMED PARTICLE: a body built of RNA is the literal coinage.","cn":"被命名的颗粒：由 RNA 构成的「体」正是字面构造。"},{"senses":"S2","en":"MATERIAL: the particle is a mixture, so the name also covers its composition.","cn":"材料：该颗粒是混合物，因此名称也覆盖其组成。"},{"senses":"S3 · S4","en":"THE WORK: reading a tape into a chain, done by two unequal halves.","cn":"工作：把带子读成链，由大小不等的两半完成。"},{"senses":"S5 · S6","en":"MULTIPLICATION AND DOCKING: many particles on one tape, each landing on a site.","cn":"倍增与停靠：一条带子上有多个颗粒，各自落在位点上。"},{"senses":"S7 · S8","en":"TARGET AND FOSSIL: the same particle is a place to intervene and a trace of early life.","cn":"靶点与化石：同一个颗粒既是可介入的位置，也是早期生命的痕迹。"}]},"affixes":{"intro":{"en":"Ribosome is a modern compound of a clipped chemical stem and a Greek noun; the parts are combining forms rather than a Latin root and suffix.","cn":"ribosome 是缩略的化学词干与希腊名词组成的现代合成词；其构件是组合形式，而非拉丁词根加后缀。"},"latinIntro":{"en":"No inherited Latin source exists. The -some in ribosome is Greek soma 'body', and New Latin ribosoma is only a Latinized spelling.","cn":"没有传承的拉丁来源。ribosome 中的 -some 是希腊 soma「身体」，新拉丁语 ribosoma 只是拉丁化拼写。"},"items":[{"word":"ribosome","structure":"ribo- (RNA) + -some (body)","meaning":"the RNA-protein particle of translation","meaningCN":"翻译用的 RNA-蛋白颗粒","example":"Ribosomes cover the rough endoplasmic reticulum.","exampleCN":"核糖体布满粗面内质网。"},{"word":"ribosomal","structure":"ribosome + -al (relating to)","meaning":"of the ribosome","meaningCN":"核糖体的","example":"Ribosomal proteins are assembled in the nucleus.","exampleCN":"核糖体蛋白在核内组装。"},{"word":"rRNA","structure":"ribo- + RNA (abbreviation)","meaning":"ribosomal RNA","meaningCN":"核糖体 RNA","example":"rRNA folds into the catalytic core.","exampleCN":"rRNA 折叠成催化核心。"},{"word":"polysome","structure":"poly- (many) + -some (body)","meaning":"several ribosomes on one message","meaningCN":"一条信使上的多个核糖体","example":"Polysomes cluster near the cell membrane.","exampleCN":"多聚核糖体聚集在细胞膜附近。"},{"word":"ribozyme","structure":"ribo- + -zyme (Greek zyme, leaven)","meaning":"an RNA molecule with catalytic activity","meaningCN":"具催化活性的 RNA 分子","example":"A ribozyme can cleave RNA without protein help.","exampleCN":"核酶无需蛋白帮助即可切割 RNA。"},{"word":"ribonuclease","structure":"ribo- + nuclease (nucleus + -ase)","meaning":"an enzyme that cuts RNA","meaningCN":"切割 RNA 的酶","example":"Ribonuclease cleared the sample of RNA.","exampleCN":"核糖核酸酶清除了样本中的 RNA。"},{"word":"ribosomal binding site","structure":"ribosomal + binding + site","meaning":"the docking sequence on a message","meaningCN":"信使上的停靠序列","example":"A good binding site is needed for high yield.","exampleCN":"高产需要良好的结合位点。"},{"word":"ribosome profiling","structure":"ribosome + profiling (Latin filum, thread)","meaning":"sequencing the fragments protected by ribosomes","meaningCN":"对核糖体保护片段进行测序","example":"Ribosome profiling revealed a hidden short gene.","exampleCN":"核糖体印迹揭示了一个隐藏的短基因。"}],"latinEntries":[{"word":"soma","structure":"Greek soma (neuter noun)","meaning":"body","meaningCN":"身体"},{"word":"-some","structure":"scientific suffix from Greek soma","meaning":"body, particle","meaningCN":"体；颗粒"}]}},{"word":"ribosomal","ipa_uk":"/raɪˈbɒsəməl/","ipa_us":"/raɪˈbɑːsəməl/","definition_zh":"核糖体的；与核糖体有关的；由核糖体 RNA 或核糖体蛋白构成的","definition_en":"relating to a ribosome, or made of the RNA and proteins that form a ribosome","core_image":"一个颗粒被透明罩子罩住，罩内的 RNA 骨架与蛋白颗粒各自贴上同一种颜色的标签","scene":"Ribosomal RNA folds into the core of the particle, while the proteins sit on its surface.","sceneCN":"这里 ribosomal 指「核糖体的、由核糖体组分构成的」（第 2 个义项：指 rRNA 与核糖体蛋白这些组分本身）；RNA 折叠成核心，蛋白贴在外围。图中可辨识物件：透明罩、RNA 骨架、表面蛋白颗粒、标签。","pos":[{"tag":"adj.","zh":"核糖体的；核糖体来源的（多作定语，修饰 RNA、蛋白、亚基、基因等）"}],"collocations":[{"phrase":"ribosomal RNA","zh":"核糖体 RNA"},{"phrase":"ribosomal protein","zh":"核糖体蛋白"},{"phrase":"ribosomal subunit","zh":"核糖体亚基"},{"phrase":"ribosomal binding site","zh":"核糖体结合位点"},{"phrase":"ribosomal gene","zh":"核糖体基因"},{"phrase":"ribosomal DNA","zh":"核糖体 DNA（rDNA）"},{"phrase":"ribosomal translation","zh":"核糖体翻译"}],"forms":[{"label":"比较级（极少用）","form":"more ribosomal"},{"label":"副词形式","form":"ribosomally（在核糖体层面地）"},{"label":"名词原形","form":"ribosome（核糖体）"},{"label":"缩略形式","form":"rRNA / rDNA（核糖体 RNA / DNA）"}],"derivatives":[{"word":"ribosome","pos":"n.","zh":"核糖体"},{"word":"ribosomally","pos":"adv.","zh":"在核糖体层面地"},{"word":"rRNA","pos":"n.","zh":"核糖体 RNA"},{"word":"ribosomal protein","pos":"n.","zh":"核糖体蛋白"},{"word":"polysomal","pos":"adj.","zh":"多聚核糖体的"}],"senses":[{"no":"01","title":"Of the particle as a whole","titleCN":"核糖体的：整体归属","definition":"relating to a ribosome as a whole","definitionCN":"与整个核糖体相关的","example":"Ribosomal structure is strikingly similar across all three domains of life.","exampleCN":"核糖体结构在生命的三个域之间惊人地相似。","why":"the -al suffix turns the particle's name into a label of relation, so the adjective starts as 'of the ribosome'.","whyCN":"后缀 -al 把颗粒的名字变成表示关系的标签，因此这个形容词的起点是「核糖体的」。"},{"no":"02","title":"Of its RNA and protein components","titleCN":"核糖体组分的：rRNA 与核糖体蛋白","definition":"made of or relating to the RNA and proteins that constitute the particle","definitionCN":"由构成该颗粒的 RNA 与蛋白质组成，或与之相关","example":"Ribosomal proteins are imported into the nucleus before assembly.","exampleCN":"核糖体蛋白在组装前被输入细胞核。","why":"the adjective shifts from the whole to its ingredients, naming the parts by the name of the thing they build.","whyCN":"这个形容词从整体转向配料，用其所构成之物的名字来命名这些部件。"},{"no":"03","title":"Of the two subunits","titleCN":"核糖体亚基的","definition":"relating to the small or large subunit of the particle","definitionCN":"与核糖体的小亚基或大亚基相关","example":"A ribosomal subunit must fold correctly before it can join the other.","exampleCN":"核糖体亚基必须正确折叠才能与另一半结合。","why":"because the particle is built of two halves, the adjective also marks either half.","whyCN":"由于该颗粒由两半构成，这个形容词也标记其中任一半。"},{"no":"04","title":"Of the docking sequence","titleCN":"核糖体结合位点的","definition":"relating to the site where a ribosome attaches to a messenger RNA","definitionCN":"与核糖体附着到信使 RNA 的位点相关","example":"The ribosomal binding site lies just upstream of the start codon.","exampleCN":"核糖体结合位点就在起始密码子上游。","why":"the adjective follows the particle to its landing place and names that sequence as ribosomal.","whyCN":"这个形容词随颗粒走到它的落点，并把那段序列称为核糖体的。"},{"no":"05","title":"Of the genes that encode the parts","titleCN":"核糖体基因的：编码组分的基因","definition":"relating to the genes that code for ribosomal RNA or ribosomal proteins","definitionCN":"与编码核糖体 RNA 或核糖体蛋白的基因相关","example":"Ribosomal DNA is repeated hundreds of times in the human genome.","exampleCN":"核糖体 DNA 在人类基因组中重复数百次。","why":"since the parts are made from genes, the adjective extends to the instructions behind them.","whyCN":"既然这些部件由基因制造，这个形容词便延伸到背后的指令。"},{"no":"06","title":"Of the act of translation","titleCN":"核糖体翻译的：与翻译过程相关","definition":"describing protein synthesis carried out on the particle, as opposed to other routes","definitionCN":"描述在该颗粒上完成的蛋白合成，以区别于其他途径","example":"Ribosomal translation accounts for almost all protein made in the cell.","exampleCN":"核糖体翻译承担了细胞内几乎全部蛋白质的制造。","why":"the adjective marks the route as well as the machine, so 'ribosomal translation' names a pathway.","whyCN":"这个形容词既标记机器也标记路径，因此 ribosomal translation 命名一条通路。"},{"no":"07","title":"Of the conserved core","titleCN":"核糖体保守核心的：进化上稳定的部分","definition":"relating to the parts of the particle that are nearly unchanged across species","definitionCN":"与在各物种间几乎不变的部分相关","example":"The ribosomal core is the most conserved sequence in the cell.","exampleCN":"核糖体核心是细胞内最保守的序列。","why":"comparison across species shows a frozen core, so the adjective can point to what evolution refused to alter.","whyCN":"跨物种比较显示出一个被冻结的核心，因此这个形容词可以指向演化拒绝改动的那部分。"},{"no":"08","title":"Of a drug target","titleCN":"核糖体靶点的：药理学用法","definition":"describing the particle as a site where drugs can act selectively","definitionCN":"把该颗粒描述为药物可选择性作用的位置","example":"Many antibiotics are ribosomal inhibitors with narrow spectra.","exampleCN":"许多抗生素是核糖体抑制剂，作用谱窄。","why":"medicine uses the adjective to name a class of targets, turning the particle into a pharmacological address.","whyCN":"医学用这个形容词命名一类靶点，把这个颗粒变成一个药理学地址。"}],"etymology":{"intro":{"en":"Ribosomal is the English adjective on ribosome, with Latin -alis; the base is a twentieth-century blend of a chemical stem and Greek soma.","cn":"ribosomal 是以 ribosome 为词干、加拉丁 -alis 构成的英语形容词；词干是 20 世纪把化学词干与希腊 soma 混合的产物。"},"items":[{"era":"MODERN BASE","en":"ribosome was coined in the 1950s from ribo- (RNA) and -some (Greek soma 'body'); the adjective adds only a suffix.","cn":"ribosome 于 1950 年代由 ribo-（RNA）与 -some（希腊 soma「身体」）合成；形容词只增加一个后缀。"},{"era":"LATIN SUFFIX -ALIS","en":"Latin -alis formed relational adjectives such as naturalis and structurals; English keeps -al, giving ribosomal.","cn":"拉丁 -alis 构成关系形容词，如 naturalis；英语保留为 -al，得 ribosomal。"},{"era":"NEW LATIN","en":"New Latin ribosoma and ribosomalis are Latinized spellings, not inherited words; no classical Latin root can be claimed.","cn":"新拉丁语 ribosoma 与 ribosomalis 是拉丁化拼写，不是传承词；不应主张古典拉丁词根。"},{"era":"ADJECTIVE IN USE","en":"The adjective spread with electron microscopy and biochemistry in the 1950s and 1960s; its first citation is approximate.","cn":"该形容词随电镜与生物化学在 1950 至 60 年代传播；最早书证年代为约数。"},{"era":"rRNA NAMING","en":"Once ribosomal RNA was distinguished from transfer RNA, the adjective became a standard qualifier for RNA, protein, subunit and gene.","cn":"当核糖体 RNA 与转运 RNA 被区分后，这个形容词成为修饰 RNA、蛋白、亚基与基因的标准限定语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and coiner): neither the coiner nor the exact date of ribosome is firmly recorded, so the starting point of the derived adjective can only be given approximately.","cn":"来源不确定（首见年代与首创者）：ribosome 的首创者与确切年代均无坚实记录，因此派生形容词的起点也只能给出约数。"}]},"similar":{"note":{"en":"Group one holds look-alikes with a shared piece but a different referent; group two holds adjectives used in the same laboratory sentences.","cn":"第一组是共享构件但所指不同的形近词；第二组是出现在同一类实验句子里的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ribosome","ipa":"/ˈraɪbəsəʊm/","tag":"the noun","definition":"The particle itself. Ribosomal is only the qualifier; the noun is needed when a countable thing is meant.","definitionCN":"指颗粒本身；ribosomal 只是限定语，指可数事物时须用名词。"},{"word":"ribozyme","ipa":"/ˈraɪbəzaɪm/","tag":"catalytic RNA","definition":"An RNA molecule with enzymatic power. It shares ribo- but names a molecule class, not a ribosomal part.","definitionCN":"具酶活性的 RNA 分子；共享 ribo-，但指一类分子，不是核糖体部件。"},{"word":"ribose","ipa":"/ˈraɪbəʊz/","tag":"the sugar","definition":"A five-carbon sugar found in RNA; the shared stem refers to a chemical, not to the particle.","definitionCN":"RNA 中的五碳糖；共享词干指一种化学物，不指颗粒。"},{"word":"lysosomal","ipa":"/ˌlaɪsəˈsəʊməl/","tag":"of another organelle","definition":"The adjective of lysosome, built with the same -some. It marks a digestive compartment, not translation.","definitionCN":"溶酶体的形容词，用同一个 -some 构成；标记消化区室，与翻译无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"polysomal","ipa":"/ˌpɒlɪˈsəʊməl/","tag":"of the group","definition":"Relating to a polysome, a cluster of particles on one message; the unit is the ribosome, the cluster is the polysome.","definitionCN":"与多聚核糖体相关；单位是核糖体，簇是多聚核糖体。"},{"word":"nucleolar","ipa":"/nuːˈkliːələ(r)/","tag":"of the assembly site","definition":"Relating to the nucleolus, where ribosomal RNA is transcribed and subunits begin assembly.","definitionCN":"与核仁相关，那里转录 rRNA 并开始组装亚基。"},{"word":"translational","ipa":"/trænsˈleɪʃənl/","tag":"of the process","definition":"Relating to translation as a process, including its control; ribosomal names the place, translational the stage.","definitionCN":"与翻译这一过程及其调控相关；ribosomal 指场所，translational 指阶段。"},{"word":"cytoplasmic","ipa":"/ˌsaɪtəʊˈplæsmɪk/","tag":"of the surrounding space","definition":"Located in the cytoplasm, where free ribosomes work; it describes location rather than identity.","definitionCN":"位于细胞质，游离核糖体在此工作；描述位置而非身份。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ribosome + -al: the same relational suffix as in natural and structural.","cn":"ribosome + -al：与 natural、structural 中的关系后缀相同。"},{"en":"The family runs ribosome, ribosomal, rRNA, rDNA, polysome, ribozyme.","cn":"同族词包括 ribosome、ribosomal、rRNA、rDNA、polysome、ribozyme。"},{"en":"Fixed phrases: ribosomal RNA, ribosomal protein, ribosomal subunit, ribosomal binding site.","cn":"固定搭配：核糖体 RNA、核糖体蛋白、核糖体亚基、核糖体结合位点。"},{"en":"Lab shorthand: rRNA is the RNA of the ribosome, tRNA is the carrier, mRNA is the message.","cn":"实验室简称：rRNA 是核糖体的 RNA，tRNA 是搬运者，mRNA 是信使。"},{"en":"The adjective also carries the '-al' words for other organelles: lysosomal, mitochondrial, nuclear.","cn":"这个形容词也与其他细胞器的 -al 形容词并列：lysosomal、mitochondrial、nuclear。"}],"abstract":[{"en":"Picture a machine whose parts are all stamped with the machine's own name.","cn":"想象一台机器，其每个零件都打上这台机器的名字。"},{"en":"Picture two unequal halves that must click together before the work begins.","cn":"想象大小不等的两半必须先扣合才能开工。"},{"en":"Picture a core so old that every descendant still carries the same groove.","cn":"想象一个核心古老到每个后代都仍带着同一道槽。"}]},"examples":[{"en":"Ribosomal RNA is transcribed in the nucleolus and assembled with proteins.","cn":"核糖体 RNA 在核仁中转录，并与蛋白质组装。"},{"en":"A ribosomal mutation can make a bacterium resistant to one antibiotic class.","cn":"核糖体突变可使细菌对某一类抗生素耐药。"},{"en":"Ribosomal profiling showed that translation slowed within minutes of starvation.","cn":"核糖体印迹显示饥饿数分钟内翻译就减慢。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「核糖体（ribosome）的 -al 尾巴」——凡修饰 rRNA、核糖体蛋白、亚基 → 核糖体的","word":"ribosomal"},"root":"ribo-（ribonucleic acid 缩略）+ 希腊 soma「身体」→ 英语 ribosome + 拉丁关系后缀 -alis → ribosomal。","sensesIntro":{"en":"Eight senses fan out from one relational suffix: the particle as a whole, its ingredients, its two halves, its docking site, the genes behind it, the pathway it runs, the core it never changed, and the address drugs aim at.","cn":"八个义项从一个表关系的后缀散开：整个颗粒、其配料、两个亚基、停靠位点、背后的基因、所走的通路、从未改动的核心，以及药物瞄准的地址。"},"semanticMap":{"core":{"en":"CORE IMAGE: a translucent hood over the particle, tagging each RNA and protein part with the particle's own colour.","cn":"核心意象：颗粒外罩一层透明罩，把每个 RNA 与蛋白部件都染上颗粒自身的颜色。"},"chain":["WHOLE PARTICLE","ITS INGREDIENTS","TWO HALVES","LANDING SITE","GENES BEHIND IT","CONSERVED CORE"],"branches":[{"senses":"S1","en":"THE WHOLE: the simplest relational reading, 'of the ribosome'.","cn":"整体：最简单的关系读法，「核糖体的」。"},{"senses":"S2 · S3","en":"PARTS: ingredients and subunits are named after the thing they compose.","cn":"部件：配料与亚基用其所构成之物的名字命名。"},{"senses":"S4 · S5","en":"ADDRESSES: the docking sequence and the genes that encode the parts.","cn":"地址：停靠序列与编码这些部件的基因。"},{"senses":"S6 · S7","en":"PATHWAY AND CORE: what the particle does, and the part evolution kept unchanged.","cn":"通路与核心：颗粒所做的工作，以及演化未改动的部分。"},{"senses":"S8","en":"TARGET: pharmacology reads the same particle as a selective address.","cn":"靶点：药理学把同一颗粒读成一个可选择性作用的地址。"}]},"affixes":{"intro":{"en":"The word is English ribosome plus the Latin relational suffix -alis, kept in English as -al.","cn":"该词是英语 ribosome 加拉丁关系后缀 -alis，在英语中保留为 -al。"},"latinIntro":{"en":"Only the suffix is Latin; the base is a modern blend of a chemical clipping and Greek soma. New Latin ribosomalis is a re-spelling.","cn":"只有后缀是拉丁语；词干是现代把化学缩略与希腊 soma 混合的产物。新拉丁语 ribosomalis 只是改写拼法。"},"items":[{"word":"ribosomal","structure":"ribosome + -alis (relational)","meaning":"relating to the ribosome","meaningCN":"核糖体的","example":"Ribosomal subunits assemble in the nucleolus.","exampleCN":"核糖体亚基在核仁中组装。"},{"word":"ribosomally","structure":"ribosomal + -ly (adverb)","meaning":"in a ribosomal manner","meaningCN":"以核糖体方式地","example":"The peptide is ribosomally synthesized.","exampleCN":"该肽由核糖体合成。"},{"word":"ribosome","structure":"ribo- + -some (Greek soma)","meaning":"the translating particle","meaningCN":"翻译颗粒；核糖体","example":"Ribosomes are numerous in growing cells.","exampleCN":"生长中的细胞核糖体很多。"},{"word":"rRNA","structure":"ribo- + RNA","meaning":"ribosomal RNA","meaningCN":"核糖体 RNA","example":"rRNA forms the scaffold of the subunit.","exampleCN":"rRNA 构成亚基的支架。"},{"word":"rDNA","structure":"ribo- + DNA","meaning":"the genes coding for rRNA","meaningCN":"编码 rRNA 的基因","example":"rDNA repeats cluster on several chromosomes.","exampleCN":"rDNA 重复序列聚集在数条染色体上。"},{"word":"polysomal","structure":"poly- + -som- + -al","meaning":"of a polysome cluster","meaningCN":"多聚核糖体的","example":"Polysomal fractions were collected for sequencing.","exampleCN":"收集多聚核糖体组分用于测序。"},{"word":"ribosomal protein","structure":"ribosomal + protein","meaning":"a protein of the particle","meaningCN":"核糖体蛋白","example":"Ribosomal proteins stabilise the RNA core.","exampleCN":"核糖体蛋白稳定 RNA 核心。"},{"word":"ribosomal binding site","structure":"ribosomal + binding + site","meaning":"the ribosome's docking sequence","meaningCN":"核糖体结合位点","example":"The binding site controls translation start.","exampleCN":"结合位点控制翻译起始。"}],"latinEntries":[{"word":"-alis","structure":"adjective suffix, third declension","meaning":"relating to, belonging to","meaningCN":"与……相关的；属于……的"},{"word":"soma","structure":"Greek soma (neuter noun, borrowed into New Latin)","meaning":"body","meaningCN":"身体"}]}},{"word":"protein","ipa_uk":"/ˈprəʊtiːn/","ipa_us":"/ˈproʊtiːn/","definition_zh":"蛋白质；由氨基酸链折叠成特定形状的生物大分子；膳食中提供氨基酸的营养成分","definition_en":"a large molecule built from a chain of amino acids and folded into a working shape, and by extension the nutrient class that supplies such molecules","core_image":"一串彩色珠子被揉成一团，表面有凹槽与凸起，正好能卡住另一块形状互补的珠子团","scene":"A protein folds into a shape that lets it bind one substrate and one partner, and nothing else.","sceneCN":"这里 protein 指「蛋白质分子」（第 1 个义项：由氨基酸链折叠成的生物大分子）；形状决定了它能结合谁。图中可辨识物件：珠链、折叠成的团块、表面凹槽、互补的结合面。","pos":[{"tag":"n.","zh":"蛋白质（可数，复数 proteins；指该物质整体时也可不可数）"}],"collocations":[{"phrase":"protein structure","zh":"蛋白质结构"},{"phrase":"protein synthesis","zh":"蛋白质合成"},{"phrase":"protein expression","zh":"蛋白质表达"},{"phrase":"high-protein diet","zh":"高蛋白饮食"},{"phrase":"protein folding","zh":"蛋白质折叠"},{"phrase":"protein complex","zh":"蛋白质复合体"},{"phrase":"protein purification","zh":"蛋白质纯化"}],"forms":[{"label":"复数","form":"proteins"},{"label":"不可数用法","form":"protein（指该营养物质整体时通常不加 -s）"},{"label":"形容词形式","form":"proteinaceous（蛋白质的；蛋白状的）"},{"label":"形容词变体","form":"proteinic（蛋白质的，较少用）"}],"derivatives":[{"word":"proteome","pos":"n.","zh":"蛋白质组"},{"word":"proteomics","pos":"n.","zh":"蛋白质组学"},{"word":"proteinase","pos":"n.","zh":"蛋白酶"},{"word":"proteinaceous","pos":"adj.","zh":"蛋白质的；蛋白状的"},{"word":"proteolysis","pos":"n.","zh":"蛋白质水解"}],"senses":[{"no":"01","title":"A chain folded into a working shape","titleCN":"蛋白质：折叠成形的氨基酸链","definition":"a macromolecule made of one or more chains of amino acids folded into a defined three-dimensional shape","definitionCN":"由一条或多条氨基酸链折叠成确定三维形状的生物大分子","example":"Haemoglobin is a protein built from four folded chains.","exampleCN":"血红蛋白是由四条折叠链构成的蛋白质。","why":"Greek prōteios meant 'primary', and the name was given because such substances were thought to be the primary stuff of nutrition; the modern molecule sense grew from that label.","whyCN":"希腊 prōteios 意为「首要的」，命名时认为这类物质是营养的首要成分；现代「分子」义正是在这个标签上发展出来的。"},{"no":"02","title":"Sequence and fold","titleCN":"分子结构：序列与折叠","definition":"the internal plan of a protein: the order of amino acids and the way that order folds","definitionCN":"蛋白质的内部方案：氨基酸的排列顺序，以及这一顺序折叠的方式","example":"A single wrong amino acid can spoil the fold of the whole protein.","exampleCN":"一个氨基酸出错就可能毁掉整个蛋白质的折叠。","why":"once the chain was sequenced, the word covered not only the substance but the architecture that makes it work.","whyCN":"当链被测序后，这个词不仅指物质，也指让它工作的构造。"},{"no":"03","title":"The nutrient on a plate","titleCN":"营养义：膳食中的蛋白质","definition":"the component of food that supplies amino acids, spoken of in amounts and quality","definitionCN":"食物中提供氨基酸的成分，常按数量与质量来谈","example":"Beans and rice together supply a complete set of protein.","exampleCN":"豆类与米饭搭配可提供完整的蛋白质。","why":"because the molecule is what the body rebuilds from food, the same word names the nutrient class on the plate.","whyCN":"因为身体正是用食物重建这种分子，同一个词也指盘中的那类营养素。"},{"no":"04","title":"A job description, not a shape","titleCN":"功能类别：按工作分工的蛋白质","definition":"a class of molecules grouped by what they do, such as enzymes, structural proteins, transporters and signals","definitionCN":"按功能归类的分子，如酶、结构蛋白、运输蛋白与信号蛋白","example":"Collagen is a structural protein; insulin is a signal protein.","exampleCN":"胶原蛋白是结构蛋白；胰岛素是信号蛋白。","why":"since shape serves a task, the word is also used to sort proteins by the task rather than by the fold.","whyCN":"由于形状服务于任务，这个词也被用来按任务而非按折叠方式给蛋白质分类。"},{"no":"05","title":"Measured in a lab","titleCN":"表达与水平：实验中的蛋白量","definition":"the amount of a particular protein made by a cell or sample, as measured in experiments","definitionCN":"细胞或样本中某种特定蛋白质的生成量，以实验方式测定","example":"The tumour showed high protein expression of the receptor.","exampleCN":"该肿瘤中受体的蛋白表达量很高。","why":"laboratory practice turns the substance into a quantity, so 'protein' can mean a measured level rather than a molecule.","whyCN":"实验室实践把这种物质变成一种量，因此 protein 可以指被测定的水平，而非分子本身。"},{"no":"06","title":"Separated and detected","titleCN":"纯化与检测：实验台上的蛋白操作","definition":"the substance as an object of purification, blotting and detection","definitionCN":"作为纯化、印迹与检测对象的该物质","example":"The protein was purified from bacterial cultures and run on a gel.","exampleCN":"该蛋白从细菌培养物中纯化，并在凝胶上电泳。","why":"methods name their object by the material, so a gel band or a blot is simply called protein.","whyCN":"方法学以其材料来命名对象，因此凝胶条带或印迹就被直接称为 protein。"},{"no":"07","title":"The whole set at once","titleCN":"蛋白质组：全谱视角","definition":"the entire complement of proteins in a cell or tissue, studied as a set","definitionCN":"细胞或组织中全部蛋白质的总体，作为一个集合来研究","example":"Proteomic analysis compares thousands of proteins between healthy and sick tissue.","exampleCN":"蛋白质组分析比较健康与患病组织间数千种蛋白质。","why":"high-throughput methods made the collective countable, so the singular word can also stand for the whole set.","whyCN":"高通量方法使这个集合变得可计数，因此单数形式也可指整个集合。"},{"no":"08","title":"Designed and rebuilt","titleCN":"蛋白质工程：改造与设计","definition":"a molecule treated as something that can be redesigned, fused or synthesized","definitionCN":"被当作可以重新设计、融合或合成的分子的蛋白质","example":"Engineers added a tag to the protein so it could be captured.","exampleCN":"工程师给该蛋白加了一个标签，以便把它捕获。","why":"when folding is understood as a code, the substance becomes a design space, and the word follows it there.","whyCN":"当折叠被理解为一种编码，这种物质就成了设计空间，这个词也随之进入该用法。"}],"etymology":{"intro":{"en":"Protein was coined in 1838 from Greek prōteios 'primary', a word built on prōtos 'first'. It reached English through French protéine.","cn":"protein 于 1838 年由希腊 prōteios「首要的」造出，该词基于 prōtos「第一」。它经法语 protéine 进入英语。"},"items":[{"era":"GREEK PROTOS","en":"prōtos meant 'first, foremost', and prōteios 'primary, of the first rank'. The compound behind them is a Greek formation, not a Latin one.","cn":"prōtos 意为「第一、最前」，prōteios 意为「首要的、第一等的」。其背后的构词属希腊语，不是拉丁语。"},{"era":"COINAGE 1838","en":"Jöns Jacob Berzelius proposed the name protéine for the substance Mulder described as a primary constituent of living matter. The date is well recorded; the exact wording of the proposal is not.","cn":"Jöns Jacob Berzelius 为 Mulder 所述「生命物质的首要成分」提议了 protéine 这一名称。年份有明确记录，提议的原话则无存。"},{"era":"WHY 'PRIMARY'","en":"Generally thought: the name reflects the belief that this substance was the primary material of nutrition and of the body; the reasoning is reported second-hand and not fully documented.","cn":"一般认为，这个名字反映了当时认为该物质是营养与身体的首要材料；其推理为二手记载，并未完整留存。"},{"era":"ENGLISH ARRIVAL","en":"English protein appears in the nineteenth century through French; the earliest citation is approximate.","cn":"英语 protein 于 19 世纪经法语传入；最早书证年代为约数。"},{"era":"MACROMOLECULE","en":"Twentieth-century chemistry established the amino acid chain and the folded structure, widening the word from a substance to an architecture.","cn":"20 世纪的化学确立了氨基酸链与折叠结构，把该词从一种物质扩展到一种构造。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the origin of prōtos before Greek is unsettled, and any Indo-European form offered for it is a reconstruction; the earliest English date for protein is also approximate.","cn":"来源不确定（更深词源）：prōtos 在希腊语之前的来源并无定论，凡给出的印欧形式均属重构；protein 的最早英语书证亦为约数。"}]},"similar":{"note":{"en":"Group one holds look-alikes that are often mistaken for relatives; group two holds words that name related molecules or roles.","cn":"第一组是常被误认为同族的形近词；第二组是命名相关分子或角色的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"protean","ipa":"/ˌprəʊˈtiːən/","tag":"not from prōtos at all","definition":"Means 'ever-changing, versatile', from Proteus, the shape-shifting sea god. It shares letters with protein but comes from a different Greek name.","definitionCN":"意为「多变、多才多艺」，来自会变形的海神 Proteus；与 protein 只是拼写相近，来源是另一个希腊专名。"},{"word":"proteinase","ipa":"/ˈprəʊtiːneɪz/","tag":"an enzyme, not the molecule","definition":"A protein-digesting enzyme. It is named with -ase 'enzyme', so it is a tool that acts on proteins.","definitionCN":"指分解蛋白质的酶；由 -ase「酶」构成，是作用于蛋白质的工具。"},{"word":"proteome","ipa":"/ˈprəʊtiəʊm/","tag":"the whole set","definition":"All the proteins of a cell or tissue, named with -ome 'complete set'. It is a collection, not one molecule.","definitionCN":"指一个细胞或组织的全部蛋白质，由 -ome「全集」构成；是集合，不是单个分子。"},{"word":"peptide","ipa":"/ˈpeptɪd/","tag":"short chain, different root","definition":"A short amino acid chain, from Greek peptos 'digested', not from prōtos. Peptides are shorter than proteins.","definitionCN":"指短氨基酸链，来自希腊 peptos「被消化的」，并非 prōtos；肽比蛋白质短。"}]},{"heading":"NEAR MEANING","entries":[{"word":"polypeptide","ipa":"/ˌpɒlɪˈpeptɪd/","tag":"a long chain only","definition":"A long chain of amino acids before folding is considered; a protein is the folded, working object.","definitionCN":"指尚未考虑折叠的长氨基酸链；protein 指折叠后能工作的对象。"},{"word":"enzyme","ipa":"/ˈenzaɪm/","tag":"one job class","definition":"A catalyst made of protein or RNA. Many enzymes are proteins, but not all proteins are enzymes.","definitionCN":"由蛋白质或 RNA 构成的催化剂；许多酶是蛋白质，但并非所有蛋白质都是酶。"},{"word":"amino acid","ipa":"/ˌæmɪnəʊ ˈæsɪd/","tag":"the unit, not the chain","definition":"The single building block; a protein is a chain of them.","definitionCN":"单个构建单元；蛋白质是由它们连成的链。"},{"word":"nutrient","ipa":"/ˈnuːtriənt/","tag":"a food category","definition":"Any substance that nourishes. Protein is one nutrient among several, alongside fat and carbohydrate.","definitionCN":"泛指任何提供营养的物质；蛋白质是与脂肪、碳水化合物并列的一种营养素。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"prōteios 'primary': the substance once thought to be the first stuff of the body.","cn":"prōteios「首要的」：这曾被当作身体的第一种材料。"},{"en":"The family runs protein, proteome, proteomics, proteinase, proteolysis.","cn":"同族词包括 protein、proteome、proteomics、proteinase、proteolysis。"},{"en":"Fixed phrases: protein structure, protein folding, protein expression, protein purification.","cn":"固定搭配：蛋白质结构、折叠、表达、纯化。"},{"en":"A protein is a chain that folds; a peptide is a short chain; an enzyme is one kind of protein.","cn":"蛋白质是折叠的链；肽是短链；酶是蛋白质的一种。"},{"en":"Structure decides function: the fold makes the pocket, and the pocket decides the partner.","cn":"结构决定功能：折叠造出凹槽，凹槽决定结合对象。"}],"abstract":[{"en":"Picture a necklace of coloured beads crushed into a ball with dents and ridges.","cn":"想象一条彩色珠链被揉成一团，表面有凹坑与凸棱。"},{"en":"Picture a key that is also made of beads, so its shape can be rewritten bead by bead.","cn":"想象一把也由珠子构成的钥匙，其形状可以逐颗改写。"},{"en":"Picture a kitchen where the same ingredient is used as fuel, as brick and as signal.","cn":"想象一间厨房，同一种材料既当燃料，又当砖块，还当信号。"}]},"examples":[{"en":"Heating denatures the protein, so the egg white turns solid.","cn":"加热使蛋白质变性，因此蛋白凝固。"},{"en":"Athletes often eat more protein than they strictly need.","cn":"运动员常摄入超过实际所需的蛋白质。"},{"en":"The protein was tagged with a fluorescent label for imaging.","cn":"该蛋白被加上荧光标签以便成像。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「扑（pro）上去的（tein）一团」——氨基酸连成链再揉成一团，构成身体的首要材料 → 蛋白质","word":"protein"},"root":"希腊 prōtos「第一」→ prōteios「首要的」→ 法语 protéine（1838，Berzelius 提议）→ 英语 protein。","sensesIntro":{"en":"Eight senses follow one movement: a chain folds into a shape, and that shape is then read as an architecture, a nutrient, a job class, a measured level, a laboratory object, a whole set, and finally a design space.","cn":"八个义项沿同一个动作展开：一条链折叠成一个形状，而这个形状依次被读成构造、营养素、岗位类别、测定值、实验对象、全集，最后是设计空间。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bead chain crumpled into a lump whose dents fit one partner.","cn":"核心意象：一条珠链被揉成团块，其凹处只与一个对象相合。"},"chain":["AMINO ACID CHAIN","FOLDED LUMP","FITTING SURFACE","WORKING JOB","MEASURED AMOUNT","WHOLE SET"],"branches":[{"senses":"S1","en":"THE MOLECULE: the folded chain is the basic referent of the word.","cn":"分子本身：折叠的链是该词的基本所指。"},{"senses":"S2","en":"ARCHITECTURE: sequence plus fold, the plan behind the shape.","cn":"构造：序列加折叠，即形状背后的方案。"},{"senses":"S3","en":"NUTRIENT: the same substance read as food on a plate.","cn":"营养素：同一种物质被读成盘中的食物。"},{"senses":"S4","en":"JOB CLASS: proteins sorted by task rather than by fold.","cn":"岗位类别：按任务而非按折叠方式分类的蛋白质。"},{"senses":"S5 · S6 · S7 · S8","en":"QUANTITY AND DESIGN: measured levels, bench objects, whole sets, and molecules rewritten by engineers.","cn":"数量与设计：测定水平、实验台对象、全集，以及被工程师改写的分子。"}]},"affixes":{"intro":{"en":"Protein is a Greek-derived noun carrying a Greek suffix -eios; English adds the usual Latin-based endings for its family.","cn":"protein 是带希腊后缀 -eios 的希腊派生名词；英语为其词族加上通常的拉丁式词尾。"},"latinIntro":{"en":"There is no classical Latin source. New Latin proteinum is a Latinized spelling, while -ase, -ome and proteo- are modern scientific combining forms.","cn":"没有古典拉丁来源。新拉丁语 proteinum 是拉丁化拼写，而 -ase、-ome 与 proteo- 是现代科学组合形式。"},"items":[{"word":"protein","structure":"prōteios (Greek 'primary') + French -ine","meaning":"the primary substance of nutrition; a folded amino acid chain","meaningCN":"营养的首要物质；折叠的氨基酸链","example":"The protein binds calcium at its centre.","exampleCN":"该蛋白在中心结合钙。"},{"word":"proteins","structure":"protein + -s (plural)","meaning":"more than one protein molecule","meaningCN":"多个蛋白质分子","example":"Membrane proteins transport ions across the bilayer.","exampleCN":"膜蛋白把离子运过脂双层。"},{"word":"proteinaceous","structure":"protein + -aceous (of the nature of)","meaning":"made of or like protein","meaningCN":"由蛋白质构成的；蛋白状的","example":"A proteinaceous coat surrounds the spore.","exampleCN":"一层蛋白性质的外壳包裹着孢子。"},{"word":"proteinase","structure":"protein + -ase (enzyme)","meaning":"an enzyme that cuts proteins","meaningCN":"切割蛋白质的酶","example":"A serine proteinase digests the collagen.","exampleCN":"一种丝氨酸蛋白酶消化胶原。"},{"word":"proteolysis","structure":"proteo- + Greek lysis (loosening)","meaning":"the breaking down of proteins","meaningCN":"蛋白质的分解","example":"Proteolysis releases the active hormone.","exampleCN":"蛋白质水解会释放出活性激素。"},{"word":"proteome","structure":"proteo- + -ome (complete set)","meaning":"all proteins of a cell or tissue","meaningCN":"细胞或组织的全部蛋白质","example":"The proteome changes with stress.","exampleCN":"蛋白质组会随压力改变。"},{"word":"proteomics","structure":"proteome + -ics (science)","meaning":"large-scale study of proteins","meaningCN":"大规模研究蛋白质的学科","example":"Proteomics needs sensitive mass spectrometers.","exampleCN":"蛋白质组学需要灵敏的质谱仪。"},{"word":"proteogenic","structure":"proteo- + -genic (producing)","meaning":"giving rise to protein","meaningCN":"生成蛋白质的","example":"Only proteogenic amino acids enter the chain.","exampleCN":"只有生蛋白氨基酸能进入链中。"},{"word":"protease","structure":"protein + -ase (enzyme)","meaning":"a protein-splitting enzyme","meaningCN":"分解蛋白质的酶","example":"Protease removes the signal peptide.","exampleCN":"蛋白酶切去信号肽。"}],"latinEntries":[{"word":"proteinum","structure":"New Latin proteinum (n., second declension)","meaning":"protein (a Latinized scientific name)","meaningCN":"蛋白质（拉丁化科学名称）"},{"word":"prōtos","structure":"Greek prōtos (adjective)","meaning":"first, foremost","meaningCN":"第一的；最前的"},{"word":"-ine","structure":"French -ine, from Latin -ina","meaning":"chemical noun suffix","meaningCN":"化学名词后缀"}]}},{"word":"protein synthesis","ipa_uk":"/ˈprəʊtiːn ˈsɪnθəsɪs/","ipa_us":"/ˈproʊtiːn ˈsɪnθəsɪs/","definition_zh":"蛋白质合成；细胞内把氨基酸按信使信息连成蛋白质链的全过程","definition_en":"the process by which a cell joins amino acids into protein chains according to the instructions carried by messenger RNA","core_image":"一条写满密码的纸条被两台机器先后读取，最后在台面上落下一串按密码串好的珠子","scene":"Protein synthesis begins at the ribosome, where messenger RNA is read three letters at a time.","sceneCN":"这里 protein synthesis 指「蛋白质合成」这一过程（第 1 个义项：按信使信息把氨基酸连成链的全过程）；起点在核糖体上，每三个字母读一次。图中可辨识物件：密码纸条、两台机器、三字母分组、串好的珠链。","pos":[{"tag":"n.","zh":"蛋白质合成（不可数；指多次独立过程时可说 protein syntheses）"}],"collocations":[{"phrase":"protein synthesis rate","zh":"蛋白质合成速率"},{"phrase":"inhibit protein synthesis","zh":"抑制蛋白质合成"},{"phrase":"protein synthesis machinery","zh":"蛋白质合成机器"},{"phrase":"protein synthesis inhibitor","zh":"蛋白质合成抑制剂"},{"phrase":"protein synthesis in vitro","zh":"体外蛋白质合成"},{"phrase":"coupled protein synthesis","zh":"偶联蛋白质合成"}],"forms":[{"label":"复数（希腊式）","form":"protein syntheses（多个独立过程）"},{"label":"不可数用法","form":"protein synthesis（指该过程整体时不加 -s）"},{"label":"相关过程名","form":"transcription（转录）；translation（翻译）"},{"label":"相关名词","form":"synthesis（合成）"}],"derivatives":[{"word":"synthesize","pos":"v.","zh":"合成"},{"word":"synthetic","pos":"adj.","zh":"合成的；人造的"},{"word":"biosynthesis","pos":"n.","zh":"生物合成"},{"word":"translation","pos":"n.","zh":"翻译"},{"word":"expression","pos":"n.","zh":"表达"}],"senses":[{"no":"01","title":"Building protein from amino acids","titleCN":"蛋白质合成：把氨基酸连成链的全过程","definition":"the whole cellular process that turns free amino acids into protein chains","definitionCN":"细胞把游离氨基酸变成蛋白质链的整个过程","example":"Protein synthesis consumes more energy than any other single job in a growing cell.","exampleCN":"在生长中的细胞里，蛋白质合成消耗的能量超过任何其他单项工作。","why":"synthesis is Greek for 'a putting together', so the phrase names the assembly of the molecule the first word identifies.","whyCN":"synthesis 在希腊语中意为「放到一起」，因此这个短语命名的就是前一个词所指分子的装配。"},{"no":"02","title":"The ribosome step alone","titleCN":"翻译环节：核糖体上的装配","definition":"the step in which a ribosome reads messenger RNA and links amino acids in order","definitionCN":"核糖体读取信使 RNA 并按顺序连接氨基酸的环节","example":"Protein synthesis on the ribosome can add about twenty amino acids per second.","exampleCN":"核糖体上的蛋白质合成每秒约可加上二十个氨基酸。","why":"because the ribosome is the visible workshop, the phrase is often narrowed to that single step.","whyCN":"因为核糖体是可见的车间，这个短语常被收窄到那一步。"},{"no":"03","title":"The full path from gene to molecule","titleCN":"基因表达到蛋白的全流程","definition":"the complete path from a gene through transcription and RNA processing to the finished protein","definitionCN":"从基因经转录与 RNA 加工直到成品蛋白的完整路径","example":"Protein synthesis in this sense includes transcription, splicing and translation.","exampleCN":"这一义项的蛋白质合成包括转录、剪接与翻译。","why":"when the whole pathway is meant, the phrase covers every step that stands between a gene and its product.","whyCN":"当指整条路径时，这个短语覆盖从基因到产物之间的每一步。"},{"no":"04","title":"Where it happens and what it eats","titleCN":"合成场所与原料","definition":"the sites and supplies of the process: ribosomes, amino acids, ATP and charged transfer RNAs","definitionCN":"该过程的场所与供给：核糖体、氨基酸、ATP 与带电荷的转运 RNA","example":"Protein synthesis stalls within minutes if amino acids run out.","exampleCN":"若氨基酸耗尽，蛋白质合成会在几分钟内停顿。","why":"the phrase also names the logistics of the factory, because the reaction cannot be described without its site and its inputs.","whyCN":"这个短语也指工厂的物流，因为这场反应离不开场所与输入。"},{"no":"05","title":"How fast it runs","titleCN":"合成速率：翻译效率的调节","definition":"the rate at which the process runs, and the controls that speed it up or slow it down","definitionCN":"该过程运行的速率，以及使它加快或减慢的调控","example":"Nutrient signals adjust protein synthesis before they adjust growth.","exampleCN":"营养信号会先调整蛋白质合成，再调整生长。","why":"cells regulate the process as a quantity, so the phrase also denotes a rate rather than a mechanism.","whyCN":"细胞把这个过程当作一个量来调控，因此这个短语也可指速率而非机制。"},{"no":"06","title":"Switched off by drugs and toxins","titleCN":"合成抑制：抗生素与毒素的作用点","definition":"the process as a target that can be blocked by antibiotics or toxins","definitionCN":"该过程作为可被抗生素或毒素阻断的靶点","example":"Ricin shuts down protein synthesis by disabling a ribosomal RNA.","exampleCN":"蓖麻毒素通过破坏核糖体 RNA 来关闭蛋白质合成。","why":"because the machinery differs between bacteria and humans, blocking it became a medical strategy, and the phrase names that target.","whyCN":"由于细菌与人的机器不同，阻断它成为医学策略，这个短语也用来命名那个靶点。"},{"no":"07","title":"The route for secreted protein","titleCN":"分泌蛋白的合成与运输路线","definition":"the version of the process that begins on the rough endoplasmic reticulum and ends with secretion","definitionCN":"起始于粗面内质网、最终分泌到细胞外的合成版本","example":"Protein synthesis for antibodies starts on the rough endoplasmic reticulum.","exampleCN":"抗体的蛋白质合成从粗面内质网开始。","why":"secreted proteins need an extra route, so the phrase also labels a pathway rather than a single reaction.","whyCN":"分泌蛋白需要额外的路线，因此这个短语也标记一条通路，而非单一反应。"},{"no":"08","title":"Rebuilt outside a cell","titleCN":"人工体系：无细胞与工程化合成","definition":"the process reproduced in a test tube or redesigned for biotechnology","definitionCN":"在试管中重现或为生物技术而重新设计的合成过程","example":"Cell-free protein synthesis now makes custom enzymes overnight.","exampleCN":"无细胞蛋白质合成如今可在一夜之间造出定制酶。","why":"once the machinery can be taken out of the cell, the phrase follows it into the laboratory and the factory.","whyCN":"一旦这套机器能被移出细胞，这个短语便随之进入实验室与工厂。"}],"etymology":{"intro":{"en":"Protein is a nineteenth-century coinage from Greek prōteios 'primary'; synthesis is Greek synthesis 'a putting together', from syn- 'together' and thesis 'a placing'. The dates below are approximate.","cn":"protein 是 19 世纪由希腊 prōteios「首要的」所造；synthesis 是希腊 synthesis「放到一起」，由 syn-「一起」与 thesis「放置」构成。以下年代均为约数。"},"items":[{"era":"GREEK SYNTHESIS","en":"synthesis named a putting together or a combination, from syn- 'together' plus thesis, from tithenai 'to place'. It was used for logical and grammatical composition before chemistry borrowed it.","cn":"synthesis 指放到一起或组合，由 syn-「一起」加 thesis（源自 tithenai「放置」）构成。在化学借用它之前，已用于逻辑与语法的组合义。"},{"era":"PROTEIN","en":"protein was coined in 1838 from prōteios 'primary'; it reached English in the nineteenth century.","cn":"protein 于 1838 年由 prōteios「首要的」造出，并于 19 世纪进入英语。"},{"era":"CHEMICAL SENSE","en":"Nineteenth-century chemistry fixed synthesis as the building of a compound from simpler parts, the exact opposite of analysis.","cn":"19 世纪化学把 synthesis 固定为「由较简单部分构建化合物」，恰与分析相对。"},{"era":"THE PHRASE","en":"Source uncertain (first date): the two words were joined once the machinery of translation was understood in the mid-twentieth century, and the exact first use of the fixed phrase is not documented.","cn":"来源不确定（首见年代）：当 20 世纪中期翻译机制被理解后，两词才组合使用；这个固定短语的最早用例并无记录。"},{"era":"CENTRAL DOGMA","en":"The phrase spread with the scheme DNA to RNA to protein, and became the ordinary label for the last step of that scheme.","cn":"该短语随「DNA → RNA → 蛋白质」的图式传播，并成为该图式最后一步的通用标签。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): thesis and tithenai have no agreed pre-Greek origin, so any Indo-European form behind them is a reconstruction.","cn":"来源不确定（更深词源）：thesis 与 tithenai 在希腊语之前的来源并无共识，凡其背后的印欧形式均属重构。"}]},"similar":{"note":{"en":"Group one holds words built from the same pieces but naming a different step or object; group two holds words for neighbouring stages of the same pathway.","cn":"第一组是用相同构件、但指不同步骤或对象的词；第二组是同一通路中相邻阶段的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"protein","ipa":"/ˈprəʊtiːn/","tag":"the product only","definition":"The finished molecule, not the making of it. Protein synthesis is the process; protein is what comes out.","definitionCN":"指成品分子，不是制造过程；protein synthesis 是过程，protein 是产物。"},{"word":"proteome","ipa":"/ˈprəʊtiəʊm/","tag":"the whole output","definition":"The full set of proteins present at a moment, named with -ome. It is a catalogue, not a process.","definitionCN":"指某一时刻全部蛋白质的集合，由 -ome 构成；是清单，不是过程。"},{"word":"proteolysis","ipa":"/ˌprəʊtiˈɒləsɪs/","tag":"the opposite direction","definition":"The breaking down of proteins, built with Greek lysis 'loosening'. It undoes synthesis rather than performing it.","definitionCN":"指蛋白质的分解，由希腊 lysis「松开」构成；它是合成的逆过程，而不是合成本身。"},{"word":"proteinase","ipa":"/ˈprəʊtiːneɪz/","tag":"a tool, not a process","definition":"An enzyme that cuts proteins. It acts on the product and is not the production line.","definitionCN":"指切割蛋白质的酶；作用于产物，不是生产线本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"translation","ipa":"/trænsˈleɪʃn/","tag":"one stage","definition":"The ribosome step of reading messenger RNA into a chain; it is the core of protein synthesis but not the whole pathway.","definitionCN":"指核糖体把信使 RNA 读成链的阶段；是蛋白质合成的核心，但不是整条通路。"},{"word":"transcription","ipa":"/trænˈskrɪpʃn/","tag":"the stage before","definition":"Copying DNA into RNA. It supplies the message that protein synthesis later reads.","definitionCN":"指把 DNA 抄成 RNA；它为蛋白质合成提供随后要读的信息。"},{"word":"gene expression","ipa":"/dʒiːn ɪkˈspreʃn/","tag":"the whole programme","definition":"The complete conversion of a gene into a functional product, including protein synthesis when the product is a protein.","definitionCN":"指基因转变成功能产物的全过程；当产物是蛋白质时包含蛋白质合成。"},{"word":"biosynthesis","ipa":"/ˌbaɪəʊˈsɪnθəsɪs/","tag":"any biological assembly","definition":"The making of any compound by a living cell, from fats to vitamins. Protein synthesis is one instance.","definitionCN":"指活细胞制造任何化合物，从脂肪到维生素；蛋白质合成只是其中一例。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"protein + synthesis 'putting together': the putting together of a protein.","cn":"protein + synthesis「放到一起」：把蛋白质拼起来。"},{"en":"The chain of stages is DNA, RNA, protein; protein synthesis is the last link.","cn":"阶段链是 DNA → RNA → 蛋白质；蛋白质合成是最后一环。"},{"en":"Fixed phrases: synthesis rate, synthesis inhibitor, cell-free synthesis, coupled synthesis.","cn":"固定搭配：合成速率、合成抑制剂、无细胞合成、偶联合成。"},{"en":"The Greek plural swaps -sis for -ses: synthesis, syntheses.","cn":"希腊式复数把 -sis 换成 -ses：synthesis 变 syntheses。"},{"en":"Antibiotics such as streptomycin act here, which is why they hit bacteria and spare human ribosomes.","cn":"链霉素等抗生素作用于此处，因此能打击细菌而不伤人体核糖体。"}],"abstract":[{"en":"Picture a coded paper tape fed through a machine that drops beads in the order it reads.","cn":"想象一条带密码的纸带送入机器，机器按读到的顺序落下珠子。"},{"en":"Picture a kitchen where the recipe is copied first, then cooked.","cn":"想象一间厨房，先把菜谱抄一份，再下锅。"},{"en":"Picture a factory whose assembly line can be stopped by cutting one small part.","cn":"想象一条装配线，剪断一个小零件就能让它停下。"}]},"examples":[{"en":"Protein synthesis slows when the cell lacks charged transfer RNA.","cn":"当细胞缺少带电荷的转运 RNA 时，蛋白质合成会减慢。"},{"en":"Many antibiotics exploit differences in bacterial protein synthesis.","cn":"许多抗生素利用细菌蛋白质合成上的差异。"},{"en":"Cell-free protein synthesis kits are now standard in labs.","cn":"无细胞蛋白质合成试剂盒如今已是实验室常备。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「蛋白（protein）＋合成（synthesis）」——按密码把氨基酸拼成蛋白质 → 蛋白质合成","word":"protein synthesis"},"root":"protein 出自希腊 prōteios「首要的」；synthesis 出自希腊 syn-「一起」+ thesis「放置」（tithenai「放」）→ 英语 protein synthesis。","sensesIntro":{"en":"Eight senses follow one movement: a message is copied and read, and amino acids are dropped into a chain; that movement is then read as a whole process, a single step, a full path, a supply line, a rate, a target, a route out of the cell, and a laboratory method.","cn":"八个义项沿同一个动作展开：信息被抄写并读取，氨基酸被按序落下成链；这一动作依次被读成全过程、单一环节、完整路径、供应链、速率、靶点、出细胞的路线与实验室方法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a coded tape read three letters at a time, with beads dropped into a string.","cn":"核心意象：一条带密码的纸带每三个字母一读，珠子随之落成串。"},"chain":["COPY THE GENE","CARRY THE TAPE","READ IN THREES","LINK AMINO ACIDS","FOLD THE CHAIN","SEND IT OUT"],"branches":[{"senses":"S1","en":"THE WHOLE ASSEMBLY: amino acids become a chain, the plainest reading.","cn":"整体装配：氨基酸变成链，最朴素的读法。"},{"senses":"S2","en":"ONE STAGE: the ribosome step alone, where the tape is read.","cn":"单一阶段：只在核糖体上，纸带被读取。"},{"senses":"S3","en":"FULL PATH: from gene copy to finished molecule, several steps in one label.","cn":"完整路径：从基因拷贝到成品分子，一个标签包含多步。"},{"senses":"S4 · S5","en":"SUPPLY AND SPEED: what the factory consumes and how fast it runs.","cn":"供给与速度：工厂消耗什么，又以多快运行。"},{"senses":"S6 · S7 · S8","en":"BLOCK, ROUTE, REBUILD: a target to stop, a route to the outside, and a method moved into the lab.","cn":"阻断、路线与重建：可被阻断的靶点、通往胞外的路线，以及搬进实验室的方法。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek-derived modern noun to a Greek noun of action; neither part is a Latin root plus suffix.","cn":"这个短语把希腊来源的现代名词与希腊动作名词并置；两部分都不是拉丁词根加后缀。"},"latinIntro":{"en":"Classical Latin borrowed Greek synthesis as a learned word, so synthesis has a Latin existence, but protein is purely modern. New Latin proteinum is only a spelling.","cn":"古典拉丁语以学术借词形式吸收过希腊 synthesis，因此 synthesis 有拉丁语使用记录；而 protein 纯属现代词，新拉丁语 proteinum 只是拼写。"},"items":[{"word":"protein synthesis","structure":"protein + synthesis (Greek 'putting together')","meaning":"the assembly of protein chains","meaningCN":"蛋白质链的装配","example":"Protein synthesis requires energy at every step.","exampleCN":"蛋白质合成每一步都需要能量。"},{"word":"synthesis","structure":"syn- (together) + thesis (a placing)","meaning":"a putting together; a building up","meaningCN":"放到一起；构建","example":"The synthesis of the two molecules was reported in 1904.","exampleCN":"这两种分子的合成于 1904 年被报道。"},{"word":"synthesize","structure":"synthesis + -ize (verb)","meaning":"to build by joining parts","meaningCN":"通过连接部分来构建","example":"Cells synthesize enzymes on demand.","exampleCN":"细胞按需合成酶。"},{"word":"synthetic","structure":"synthesis + -etic (adjective)","meaning":"made by combining; not natural","meaningCN":"由组合制成的；人造的","example":"A synthetic fibre replaced the silk.","exampleCN":"一种合成纤维取代了蚕丝。"},{"word":"biosynthesis","structure":"bio- (life) + synthesis","meaning":"assembly carried out by a living cell","meaningCN":"由活细胞完成的合成","example":"Biosynthesis of vitamin D begins in the skin.","exampleCN":"维生素 D 的生物合成始于皮肤。"},{"word":"translation","structure":"trans- (across) + Latin latio (a carrying)","meaning":"carrying a message across into protein","meaningCN":"把信息搬运成蛋白质","example":"Translation ends when the stop codon is read.","exampleCN":"读到终止密码子时翻译结束。"},{"word":"transcription","structure":"trans- (across) + scriptio (a writing)","meaning":"writing a copy of a gene","meaningCN":"为基因写一份拷贝","example":"Transcription precedes translation in this operon.","exampleCN":"在该操纵子中转录先于翻译。"},{"word":"expression","structure":"ex- (out) + pressare (to press)","meaning":"the pushing out of a gene's product","meaningCN":"基因产物被「压」出来","example":"Expression of the gene rises after heat shock.","exampleCN":"热激后该基因的表达上升。"},{"word":"cell-free","structure":"cell + -free (without)","meaning":"carried out without intact cells","meaningCN":"在无完整细胞的情况下进行","example":"A cell-free system makes the protein in hours.","exampleCN":"无细胞体系在数小时内造出该蛋白。"}],"latinEntries":[{"word":"synthesis","structure":"synthesis, synthesis (f., Greek loanword, third declension)","meaning":"a putting together, a composition","meaningCN":"组合；合成"},{"word":"thesis","structure":"thesis, thesis (f., Greek loanword, third declension)","meaning":"a placing, a position","meaningCN":"放置；位置"},{"word":"proteinum","structure":"New Latin proteinum (n., second declension)","meaning":"protein (a Latinized scientific name)","meaningCN":"蛋白质（拉丁化科学名称）"}]}},{"word":"enzyme","ipa_uk":"/ˈenzaɪm/","ipa_us":"/ˈenzaɪm/","definition_zh":"酶；催化生物化学反应、通常为蛋白质（少数为 RNA）的分子","definition_en":"a molecule, usually a protein and sometimes an RNA, that speeds up a biochemical reaction without being consumed by it","core_image":"一把带凹槽的钥匙插进锁孔，锁一开，原本卡住的部件立刻分开，钥匙本身完好退出","scene":"One enzyme in saliva begins breaking starch into sugars before the food has even been swallowed.","sceneCN":"这里 enzyme 指「酶」这一催化分子（第 1 个义项：催化生化反应而自身不被消耗的分子）；唾液中的酶在食物下咽前就开始把淀粉切成糖。图中可辨识物件：带凹槽的钥匙、锁孔、分开的部件、完好的钥匙。","pos":[{"tag":"n.","zh":"酶（可数，复数 enzymes）"}],"collocations":[{"phrase":"digestive enzyme","zh":"消化酶"},{"phrase":"enzyme activity","zh":"酶活性"},{"phrase":"enzyme inhibitor","zh":"酶抑制剂"},{"phrase":"restriction enzyme","zh":"限制性内切酶"},{"phrase":"enzyme-linked assay","zh":"酶联测定"},{"phrase":"enzyme replacement therapy","zh":"酶替代疗法"},{"phrase":"immobilized enzyme","zh":"固定化酶"}],"forms":[{"label":"复数","form":"enzymes"},{"label":"形容词形式","form":"enzymatic（酶的；酶催化的）"},{"label":"形容词变体","form":"enzymic（酶的）"},{"label":"相关名词","form":"enzymology（酶学）"}],"derivatives":[{"word":"enzymatic","pos":"adj.","zh":"酶的；酶催化的"},{"word":"enzymology","pos":"n.","zh":"酶学"},{"word":"coenzyme","pos":"n.","zh":"辅酶"},{"word":"zymogen","pos":"n.","zh":"酶原"},{"word":"enzyme-linked","pos":"adj.","zh":"酶联的"}],"senses":[{"no":"01","title":"The catalyst itself","titleCN":"酶：催化分子本体","definition":"a molecule that catalyses a biochemical reaction and is not consumed by it","definitionCN":"催化生化反应而自身不被消耗的分子","example":"Each enzyme in the pathway is named for the reaction it runs.","exampleCN":"通路中的每一种酶都按它催化的反应命名。","why":"Greek en- 'in' plus zymē 'leaven' produced a name for something inside yeast that drives change, and that name now labels the catalyst itself.","whyCN":"希腊 en-「在内」加 zymē「酵素」造出一个名称，指酵母中驱动变化的东西，后来这个名称就指催化剂本身。"},{"no":"02","title":"Lowering the barrier","titleCN":"催化作用：降低反应门槛","definition":"the catalytic act of lowering the activation energy so a reaction runs at body temperature","definitionCN":"降低活化能、使反应能在体温下进行的作用","example":"Without the enzyme, the reaction would take hours instead of seconds.","exampleCN":"没有这种酶，反应要数小时而不是数秒。","why":"the name originally marked what happens inside yeast, so the word also names the speeding up rather than the thing.","whyCN":"这个名字最初标记酵母内部发生的事，因此它也能指「加快反应」这一动作，而非物体。"},{"no":"03","title":"One substrate, one reaction","titleCN":"专一性：只认一种底物","definition":"the specificity of an enzyme for a particular substrate or a particular bond","definitionCN":"酶只对特定底物或特定化学键起作用","example":"A protease will not touch a sugar, however similar the shape.","exampleCN":"蛋白酶不会去碰糖，无论形状多相似。","why":"the active site is a shaped pocket, so specificity follows directly from the geometry of the catalyst.","whyCN":"活性位点是一个有形状的口袋，因此专一性直接来自催化剂的几何形状。"},{"no":"04","title":"The shaped pocket","titleCN":"活性位点：口袋与结合面","definition":"the region of the enzyme where the substrate binds and the reaction occurs","definitionCN":"酶上与底物结合并发生反应的区域","example":"The active site holds the substrate in the one orientation that reacts.","exampleCN":"活性位点把底物固定在唯一能反应的方向上。","why":"if the catalyst is a pocket, the pocket is the part that does the work, so the word extends to that region.","whyCN":"如果催化剂是一个口袋，起作用的就是口袋本身，于是这个词也延伸到该区域。"},{"no":"05","title":"Rates and curves","titleCN":"酶促动力学：速率与曲线","definition":"the quantitative study of how fast an enzyme works as substrate concentration rises","definitionCN":"研究底物浓度升高时酶工作速率的定量描述","example":"The enzyme reaches half its maximum rate at a characteristic substrate level.","exampleCN":"该酶在某一特征底物浓度下达到最大速率的一半。","why":"because enzymes are catalysts, measuring them means measuring rates, and the word carries that quantitative sense.","whyCN":"由于酶是催化剂，研究它就是测速率，这个词也带上这种定量含义。"},{"no":"06","title":"Named with -ase","titleCN":"命名与分类：以 -ase 结尾","definition":"an enzyme named by adding -ase to the substrate or the reaction, as in protease or dehydrogenase","definitionCN":"在底物或反应名后加 -ase 构成的酶名，如蛋白酶、脱氢酶","example":"The ending -ase tells you at a glance that the word is an enzyme.","exampleCN":"-ase 结尾一眼就能看出这个词是酶。","why":"once the class had a naming rule, the suffix became part of what the word means.","whyCN":"当这一类有了命名规则，后缀本身就成了词义的一部分。"},{"no":"07","title":"Blocked on purpose","titleCN":"抑制与调控：被有意阻断","definition":"the enzyme as a target of inhibitors and of cellular regulation","definitionCN":"酶作为抑制剂与细胞调控的靶点","example":"Statins inhibit the enzyme that makes cholesterol.","exampleCN":"他汀类药物抑制制造胆固醇的酶。","why":"because a catalyst can be jammed, medicine and physiology read the word as something to switch off.","whyCN":"由于催化剂可以被卡住，医学与生理学把这个词读成「可以关掉的东西」。"},{"no":"08","title":"Working outside a cell","titleCN":"工业与医学应用","definition":"an enzyme used as a tool in industry, food processing or therapy","definitionCN":"在工业、食品加工或治疗中作为工具使用的酶","example":"Laundry detergents contain an enzyme that digests protein stains.","exampleCN":"洗衣剂含有能分解蛋白污渍的酶。","why":"purified catalysts can be put to work outside the body, so the word also names a commercial and clinical tool.","whyCN":"纯化后的催化剂可在体外工作，因此这个词也指一种商品与临床工具。"}],"etymology":{"intro":{"en":"Enzyme was coined in 1877 from Greek en- 'in' and zymē 'leaven, ferment'. It replaced the older word ferment for the agent rather than the process.","cn":"enzyme 于 1877 年由希腊 en-「在内」与 zymē「酵素、发酵剂」造出；它取代了较早的 ferment，用来指作用者而非过程。"},"items":[{"era":"GREEK ZYME","en":"zymē meant leaven or ferment, the stuff that makes dough rise and juice turn. The word is old in Greek and its deeper origin is not settled.","cn":"zymē 指酵素或发酵剂，是让面团发起、果汁变味的东西。该词在希腊语中很古老，更深来源无定论。"},{"era":"COINAGE 1877","en":"Wilhelm Kühne proposed Enzyme in 1877 to name the agent responsible for fermentation, separating it from the process.","cn":"Wilhelm Kühne 于 1877 年提出 Enzyme，用来命名负责发酵的作用者，把它与过程区分开。"},{"era":"WHY 'IN YEAST'","en":"Generally thought: the name means 'in yeast', because the fermenting agent was first studied in yeast extracts; Kühne's fuller argument is not documented in detail.","cn":"一般认为是：「在酵母中」之意，因为发酵作用者最早在酵母提取物中被研究；Kühne 更完整的论证并无详细记录。"},{"era":"ENGLISH ADOPTION","en":"English took enzyme in the late nineteenth century and dropped ferment for the agent; the first citation is approximate.","cn":"英语于 19 世纪后期吸收 enzyme，并用它取代 ferment 指作用者；最早书证年代为约数。"},{"era":"PROTEIN OR RNA","en":"Twentieth-century biochemistry showed most enzymes are proteins and some are catalytic RNA, widening the definition.","cn":"20 世纪的生物化学表明多数酶是蛋白质，少数是催化性 RNA，从而拓宽了定义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): zymē has no agreed pre-Greek origin, so any Indo-European form behind it is a reconstruction rather than a recorded word.","cn":"来源不确定（更深词源）：zymē 在希腊语之前的来源并无共识，其背后的任何印欧形式都是重构，而不是有记录的实际词。"}]},"similar":{"note":{"en":"Group one holds words sharing the Greek zymē stem or the enzyme label but naming different things; group two holds the words of the reaction it runs.","cn":"第一组是共享希腊 zymē 词干或酶标签、但指不同事物的词；第二组是它所催化反应中的相关词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"enzymatic","ipa":"/ˌenzaɪˈmætɪk/","tag":"adjective, not the agent","definition":"The adjective 'of an enzyme'. It describes a reaction or a assay, never the catalyst as a countable object.","definitionCN":"形容词「酶的」，描述反应或测定，不能作可数名词指催化剂本身。"},{"word":"coenzyme","ipa":"/kəʊˈenzaɪm/","tag":"a helper, not the catalyst","definition":"A small molecule that assists an enzyme, such as NAD. It is not itself the protein catalyst.","definitionCN":"指辅助酶的小分子，如 NAD；它本身不是蛋白催化剂。"},{"word":"zymogen","ipa":"/ˈzaɪmədʒen/","tag":"the inactive precursor","definition":"An inactive form of an enzyme, built with -gen 'producing'. It must be cut before it works.","definitionCN":"酶的失活前体，由 -gen「产生」构成；必须被切割后才能工作。"},{"word":"enzymology","ipa":"/ˌenzaɪˈmɒlədʒi/","tag":"the science, not the molecule","definition":"The study of enzymes, with -logy 'study'. It names a field of research.","definitionCN":"研究酶的学科，由 -logy「学科」构成；指研究领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"catalyst","ipa":"/ˈkætəlɪst/","tag":"any accelerator","definition":"Any agent that speeds a reaction without being consumed; an enzyme is one kind of catalyst, and inorganic ones also exist.","definitionCN":"泛指加快反应而自身不被消耗的作用者；酶是其中一类，也存在无机催化剂。"},{"word":"substrate","ipa":"/ˈsʌbstreɪt/","tag":"what is acted on","definition":"The molecule an enzyme works on. The enzyme is the tool; the substrate is the material.","definitionCN":"指酶所作用的分子；酶是工具，底物是材料。"},{"word":"cofactor","ipa":"/kəʊˈfæktə(r)/","tag":"a required helper","definition":"A non-protein substance, ion or small molecule, needed for activity. It assists rather than catalyses alone.","definitionCN":"指活性所必需的非蛋白物质、离子或小分子；它辅助而非单独催化。"},{"word":"protease","ipa":"/ˈprəʊtiːeɪz/","tag":"one enzyme class","definition":"A protein-cutting enzyme, named with -ase. It is a member of the enzyme class, not the class itself.","definitionCN":"指切割蛋白质的酶，由 -ase 构成；是酶类中的一员，而非该类整体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"en- 'in' + zymē 'leaven': the leaven inside the cell.","cn":"en-「在内」+ zymē「酵素」：细胞里的那点「酵」。"},{"en":"The family runs enzyme, enzymatic, enzymic, enzymology, coenzyme, zymogen.","cn":"同族词包括 enzyme、enzymatic、enzymic、enzymology、coenzyme、zymogen。"},{"en":"Fixed phrases: digestive enzyme, enzyme activity, enzyme inhibitor, immobilized enzyme.","cn":"固定搭配：消化酶、酶活性、酶抑制剂、固定化酶。"},{"en":"Class naming rule: substrate or reaction plus -ase, as in protease and dehydrogenase.","cn":"类别命名规则：底物或反应加 -ase，如蛋白酶、脱氢酶。"},{"en":"An enzyme is a key, the substrate is the lock, and the reaction is the door opening.","cn":"酶是钥匙，底物是锁，反应是门被打开。"}],"abstract":[{"en":"Picture a key that leaves the lock exactly as it found it, ready for the next turn.","cn":"想象一把钥匙开完锁后原样退出，等待下一次转动。"},{"en":"Picture a workbench whose dent fits one part and no other.","cn":"想象一张工作台，其凹槽只容得下一种零件。"},{"en":"Picture a factory that can be shut down by jamming a single station.","cn":"想象一座工厂，卡住一个工位就能让它停工。"}]},"examples":[{"en":"The enzyme is reusable, so a small amount handles a large batch.","cn":"这种酶可重复使用，少量即可处理一大批。"},{"en":"Heat denatures the enzyme and the reaction stops.","cn":"高温使酶变性，反应随之中止。"},{"en":"Restriction enzymes cut DNA at specific sequences.","cn":"限制性内切酶在特定序列处切割 DNA。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「按（en）在酵（zyme）里」——细胞里那点让反应跑起来的「酵」 → 酶","word":"enzyme"},"root":"希腊 en-「在内」+ zymē「酵素、发酵剂」→ 德语 Enzyme（1877，Kühne 提议）→ 英语 enzyme。","sensesIntro":{"en":"Eight senses follow one movement: a shaped key enters a lock, turns, leaves unchanged, and the door opens; that movement is then read as the agent, the speeding up, the fit, the pocket, the rate, the naming rule, the jammed lock, and the tool sold outside.","cn":"八个义项沿同一个动作展开：一把有形状的钥匙进锁、转动、原样退出，门随之打开；这一动作依次被读成作用者、加速、契合、口袋、速率、命名规则、被卡住的锁，以及卖到体外的工具。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shaped key entering a lock, turning, and leaving exactly as it came.","cn":"核心意象：一把有形状的钥匙进锁、转动，原样退出。"},"chain":["SHAPED KEY","FITS THE LOCK","TURNS THE REACTION","RELEASES THE PRODUCT","LEAVES UNCHANGED","USED AGAIN"],"branches":[{"senses":"S1","en":"THE AGENT: the key itself, named for what happens inside yeast.","cn":"作用者：钥匙本身，因酵母内部发生的事而得名。"},{"senses":"S2","en":"THE TURN: catalysis, the barrier lowered so the door opens.","cn":"转动：催化，门槛降低使门打开。"},{"senses":"S3 · S4","en":"THE FIT: specificity and the pocket that makes it.","cn":"契合：专一性，以及造成专一性的口袋。"},{"senses":"S5 · S6","en":"MEASURE AND NAME: rates and curves, and the -ase rule that labels the class.","cn":"测量与命名：速率与曲线，以及标记该类的 -ase 规则。"},{"senses":"S7 · S8","en":"JAM AND EXPORT: a target to block, and a purified tool put to work outside the cell.","cn":"卡住与外用：可被阻断的靶点，以及纯化后在胞外工作的工具。"}]},"affixes":{"intro":{"en":"Enzyme is a Greek compound of a preposition and a noun; the English family adds Latin -aticus and Greek -logia as well as the modern -ase.","cn":"enzyme 是希腊介词与名词的合成词；英语词族另加拉丁 -aticus、希腊 -logia 以及现代的 -ase。"},"latinIntro":{"en":"There is no classical Latin source. New Latin enzyma is a Latinized spelling, and -aticus is the Latin suffix that yields English -atic.","cn":"没有古典拉丁来源。新拉丁语 enzyma 是拉丁化拼写；-aticus 是产生英语 -atic 的拉丁后缀。"},"items":[{"word":"enzyme","structure":"en- (in) + zymē (leaven)","meaning":"the fermenting agent inside yeast","meaningCN":"酵母内的发酵作用者","example":"The enzyme remains active at thirty-seven degrees.","exampleCN":"该酶在三十七度下保持活性。"},{"word":"enzymes","structure":"enzyme + -s (plural)","meaning":"more than one catalyst","meaningCN":"多种酶","example":"Salivary enzymes start digesting starch.","exampleCN":"唾液中的酶开始消化淀粉。"},{"word":"enzymatic","structure":"enzyme + -atic (relational)","meaning":"of an enzyme; carried out by one","meaningCN":"酶的；由酶完成的","example":"The reaction is enzymatic, not spontaneous.","exampleCN":"该反应是酶促的，不是自发的。"},{"word":"enzymic","structure":"enzyme + -ic (relational)","meaning":"of an enzyme (older variant)","meaningCN":"酶的（较早的变体）","example":"Enzymic hydrolysis released the sugar.","exampleCN":"酶解作用释放了糖。"},{"word":"enzymology","structure":"enzyme + -logia (study)","meaning":"the study of enzymes","meaningCN":"酶学","example":"Enzymology grew out of fermentation research.","exampleCN":"酶学从发酵研究中成长起来。"},{"word":"coenzyme","structure":"co- (with) + enzyme","meaning":"a small helper molecule","meaningCN":"小分子辅助物","example":"NAD acts as a coenzyme in oxidation.","exampleCN":"NAD 在氧化中作辅酶。"},{"word":"zymogen","structure":"zymē + -gen (producing)","meaning":"an inactive enzyme precursor","meaningCN":"失活的酶前体","example":"Trypsinogen is a zymogen of trypsin.","exampleCN":"胰蛋白酶原是一种酶原。"},{"word":"protease","structure":"protein + -ase (enzyme)","meaning":"a protein-cutting enzyme","meaningCN":"切割蛋白质的酶","example":"A protease removes the signal peptide.","exampleCN":"蛋白酶切去信号肽。"},{"word":"dehydrogenase","structure":"de- (away) + hydrogen + -ase","meaning":"an enzyme that removes hydrogen","meaningCN":"脱氢的酶","example":"Dehydrogenase feeds electrons into the chain.","exampleCN":"脱氢酶把电子送入传递链。"},{"word":"enzyme-linked","structure":"enzyme + linked","meaning":"attached to an enzyme for detection","meaningCN":"与酶偶联以便检测","example":"An enzyme-linked assay measured the hormone.","exampleCN":"一种酶联测定法测量了该激素。"}],"latinEntries":[{"word":"enzyma","structure":"New Latin enzyma (n., first declension)","meaning":"enzyme (a Latinized scientific name)","meaningCN":"酶（拉丁化科学名称）"},{"word":"-aticus","structure":"Latin adjective suffix, first/second declension","meaning":"relating to, of the nature of","meaningCN":"与……相关的；具……性质的"},{"word":"zymē","structure":"Greek zymē (f., first declension)","meaning":"leaven, ferment","meaningCN":"酵素；发酵剂"}]}},{"word":"enzymatic","ipa_uk":"/ˌenzaɪˈmætɪk/","ipa_us":"/ˌenzaɪˈmætɪk/","definition_zh":"酶的；酶催化的；由酶完成的","definition_en":"relating to an enzyme, or carried out with the help of an enzyme rather than by a chemical reagent","core_image":"一只戴着手套的手把两块原料按到一起，手套上印着小小的标签，说明这双手属于某个催化者","scene":"The enzymatic breakdown of starch begins in the mouth and continues in the small intestine.","sceneCN":"这里 enzymatic 指「酶促的、由酶完成的」（第 2 个义项：说明该过程依靠酶而非化学试剂进行）；淀粉的分解从口腔开始，到小肠继续。图中可辨识物件：戴手套的手、两块原料、催化剂标签、分解产物。","pos":[{"tag":"adj.","zh":"酶的；酶催化的；由酶完成的（多作定语，修饰反应、水解、测定等）"}],"collocations":[{"phrase":"enzymatic reaction","zh":"酶促反应"},{"phrase":"enzymatic hydrolysis","zh":"酶解；酶促水解"},{"phrase":"enzymatic activity","zh":"酶活性"},{"phrase":"enzymatic digestion","zh":"酶性消化"},{"phrase":"enzymatic assay","zh":"酶法测定"},{"phrase":"enzymatic browning","zh":"酶促褐变"},{"phrase":"non-enzymatic","zh":"非酶的；非酶促的"}],"forms":[{"label":"比较级（少用）","form":"more enzymatic"},{"label":"副词形式","form":"enzymatically（以酶促方式地）"},{"label":"同义变体","form":"enzymic（酶的，较早写法）"},{"label":"名词原形","form":"enzyme（酶）"}],"derivatives":[{"word":"enzyme","pos":"n.","zh":"酶"},{"word":"enzymatically","pos":"adv.","zh":"以酶促方式地"},{"word":"enzymology","pos":"n.","zh":"酶学"},{"word":"enzymic","pos":"adj.","zh":"酶的（变体）"},{"word":"non-enzymatic","pos":"adj.","zh":"非酶促的"}],"senses":[{"no":"01","title":"Belonging to an enzyme","titleCN":"酶的：归属关系","definition":"relating to an enzyme as an object or a category","definitionCN":"与酶这一对象或类别相关","example":"The enzymatic machinery of the lysosome is encoded by dozens of genes.","exampleCN":"溶酶体的酶系统由数十个基因编码。","why":"the suffix adds a relation to the noun, so the adjective first answers 'whose?' or 'of what kind?'.","whyCN":"后缀给名词加上关系，因此这个形容词首先回答「谁的」或「哪一类」。"},{"no":"02","title":"Carried out by an enzyme","titleCN":"酶促的：由酶而非试剂完成","definition":"describing a reaction that is run by an enzyme instead of by heat or a chemical reagent","definitionCN":"描述由酶而非加热或化学试剂推动的反应","example":"The conversion is enzymatic, so it happens at room temperature.","exampleCN":"这一转化是酶促的，因此在室温下即可发生。","why":"the adjective moves from the owner to the method: a reaction labelled enzymatic owes its speed to the catalyst.","whyCN":"这个形容词从「所有者」转向「方法」：被标为 enzymatic 的反应，其速度归功于催化剂。"},{"no":"03","title":"The reaction as a category","titleCN":"酶促反应的：作为一类过程","definition":"naming a whole class of reactions studied in biochemistry, as opposed to non-enzymatic ones","definitionCN":"命名生物化学中一整类反应，以区别于非酶促反应","example":"Enzymatic reactions outnumber spontaneous ones in a living cell.","exampleCN":"在活细胞中，酶促反应远多于自发反应。","why":"because the class is defined by its cause, the adjective can name the category rather than one event.","whyCN":"由于该类由成因定义，这个形容词可以命名整个类别，而不是单个事件。"},{"no":"04","title":"Activity you can measure","titleCN":"酶活的：可测定的活性","definition":"describing the measurable activity of an enzyme in a sample","definitionCN":"描述样本中可测定的酶活性","example":"Enzymatic activity fell sharply after the sample was heated.","exampleCN":"样本加热后酶活性急剧下降。","why":"once the catalyst is assayed, 'enzymatic' also qualifies the quantity being measured.","whyCN":"当催化剂被测定时，enzymatic 也用来限定被测定的那个量。"},{"no":"05","title":"Breakdown by enzyme","titleCN":"酶解的：由酶切开","definition":"describing the splitting of a molecule into smaller pieces by enzymes","definitionCN":"描述由酶把分子切成更小片段","example":"Enzymatic hydrolysis turns the protein into short peptides.","exampleCN":"酶解把蛋白质变成短肽。","why":"digestion is the oldest use of catalysts, so the adjective attaches naturally to the cutting of bonds, as in enzymatic hydrolysis.","whyCN":"消化是催化剂最古老的用途，因此这个形容词自然附着在断键上，如酶解。"},{"no":"06","title":"Assembly by enzyme","titleCN":"酶法合成的：用酶来搭","definition":"describing the building of a product with enzymes instead of chemical synthesis","definitionCN":"描述用酶而非化学合成来制造产物","example":"Enzymatic synthesis avoids the toxic solvent used in the chemical route.","exampleCN":"酶法合成避免了化学路线所用的有毒溶剂。","why":"the same catalyst that cuts can also join, so the adjective also marks a gentler way of building.","whyCN":"能切的催化剂也能接，因此这个形容词也标记一种更温和的制造方式。"},{"no":"07","title":"Degradation by enzyme","titleCN":"酶促降解的：被酶分解掉","definition":"describing the natural or engineered destruction of a substance by enzymes","definitionCN":"描述某物质被酶自然或工程化地分解","example":"Enzymatic degradation removed the pesticide from the soil.","exampleCN":"酶促降解把农药从土壤中清除。","why":"when the product must disappear, the adjective names the process that removes it rather than the one that makes it.","whyCN":"当产物需要消失时，这个形容词命名的是清除过程，而不是制造过程。"},{"no":"08","title":"The control that has none","titleCN":"对照义：与非酶过程相对","definition":"used contrastively, as in non-enzymatic, to mark what happens without a catalyst","definitionCN":"用于对比，如 non-enzymatic，标记没有催化剂时发生的事","example":"The same sugar browned faster by the enzymatic route than by the non-enzymatic one.","exampleCN":"同样的糖经酶促途径比非酶途径褐变得更快。","why":"science needs a control, so the adjective also lives in its negated form, defining the process by what it lacks.","whyCN":"科学需要对照，因此这个形容词也活在否定形式中，用「缺少什么」来定义过程。"}],"etymology":{"intro":{"en":"Enzymatic is the English adjective on enzyme, with the suffix -atic, ultimately from Latin -aticus, itself from Greek -atikos. The base was coined in 1877.","cn":"enzymatic 是以 enzyme 为词干、加后缀 -atic 的英语形容词，-atic 源自拉丁 -aticus，后者又来自希腊 -atikos；词干造于 1877 年。"},"items":[{"era":"GREEK BASE","en":"enzyme joins en- 'in' to zymē 'leaven'; the adjective inherits that compound without change.","cn":"enzyme 把 en-「在内」与 zymē「酵素」结合；形容词原样继承这个合成词。"},{"era":"SUFFIX -ATICUS","en":"Latin -aticus formed adjectives of relation and manner, as in aquaticus and fanaticus; Greek -atikos is its model.","cn":"拉丁 -aticus 构成表示关系与方式的形容词，如 aquaticus、fanaticus；其原型是希腊 -atikos。"},{"era":"ENGLISH -ATIC","en":"English keeps the suffix as -atic, so enzyme yields enzymatic beside the older enzymic.","cn":"英语把该后缀保留为 -atic，于是 enzyme 产生 enzymatic，与较早的 enzymic 并存。"},{"era":"NINETEENTH CENTURY","en":"The adjective appears soon after the noun in late nineteenth-century biochemistry; the first citation is approximate.","cn":"该形容词在 19 世纪后期的生物化学文献中随名词不久出现；最早书证年代为约数。"},{"era":"TWENTIETH-CENTURY USE","en":"Assays and industrial processes fixed phrases such as enzymatic activity, enzymatic hydrolysis and enzymatic browning.","cn":"测定与工业流程固定了 enzymatic activity、enzymatic hydrolysis、enzymatic browning 等搭配。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date): the earliest English citation of the adjective is not recorded, and the choice between the -atic and -ic spellings has never followed a single rule.","cn":"来源不确定（首见年代）：该形容词的最早英语书证无确切记录；-atic 与 -ic 两种写法并存的取舍亦无统一规则。"}]},"similar":{"note":{"en":"Group one holds words that share the stem but differ in part of speech or in what they name; group two holds adjectives used in the same experimental sentences.","cn":"第一组是共享词干、但词性或所指不同的词；第二组是出现在同一类实验句子中的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"enzyme","ipa":"/ˈenzaɪm/","tag":"the noun","definition":"The catalyst itself. Enzymatic only qualifies; a countable thing needs the noun.","definitionCN":"指催化剂本身；enzymatic 只是限定语，指可数事物须用名词。"},{"word":"enzymic","ipa":"/enˈzaɪmɪk/","tag":"older adjective variant","definition":"An older synonym of enzymatic, built with -ic. Both qualify the same nouns, but enzymatic is now the common form.","definitionCN":"enzymatic 的较早同义词，由 -ic 构成；二者修饰同样的名词，但现在常用 enzymatic。"},{"word":"zymogen","ipa":"/ˈzaɪmədʒen/","tag":"the inactive precursor","definition":"An inactive enzyme form that must be cut to work; it shares zymē but names a precursor, not a property.","definitionCN":"必须被切割才有活性的酶前体；共享 zymē，但指前体而非性质。"},{"word":"coenzyme","ipa":"/kəʊˈenzaɪm/","tag":"a helper molecule","definition":"A small molecule assisting an enzyme; sharing the stem does not make it an adjective of relation.","definitionCN":"辅助酶的小分子；共享词干并不意味着它是关系形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"catalytic","ipa":"/ˌkætəˈlɪtɪk/","tag":"about catalysis in general","definition":"Relating to catalysis of any kind, including inorganic catalysts; enzymatic specifies that the catalyst is an enzyme.","definitionCN":"泛指任何催化，包括无机催化剂；enzymatic 明确催化剂是酶。"},{"word":"hydrolytic","ipa":"/ˌhaɪdrəˈlɪtɪk/","tag":"about water splitting","definition":"Relating to hydrolysis, the splitting of bonds by water, which may or may not involve enzymes.","definitionCN":"与水解相关，即用水断键，可能涉及酶，也可能不涉及。"},{"word":"biochemical","ipa":"/ˌbaɪəˈkemɪkl/","tag":"the whole field","definition":"Relating to chemistry in living things generally; enzymatic names only the agent of the reaction.","definitionCN":"泛指生物体内的化学；enzymatic 只命名反应的推动者。"},{"word":"non-enzymatic","ipa":"/nɒn ˌenzaɪˈmætɪk/","tag":"the control","definition":"The negated form, marking what happens with no enzyme at all; it is a contrast term, not a synonym.","definitionCN":"否定形式，标记完全没有酶时发生的事；是对照词，不是同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"enzyme + -atic: the same relational suffix as in aquatic and dramatic.","cn":"enzyme + -atic：与 aquatic、dramatic 中的关系后缀相同。"},{"en":"The family runs enzyme, enzymatic, enzymic, enzymatically, enzymology.","cn":"同族词包括 enzyme、enzymatic、enzymic、enzymatically、enzymology。"},{"en":"Fixed phrases: enzymatic reaction, enzymatic hydrolysis, enzymatic activity, enzymatic browning.","cn":"固定搭配：酶促反应、酶解、酶活性、酶促褐变。"},{"en":"The pair is easy: enzyme is the actor, enzymatic is the way the action is done.","cn":"这组词很好分：enzyme 是行动者，enzymatic 是行动的方式。"},{"en":"Food science uses enzymatic browning for the darkening of cut apples and potatoes.","cn":"食品科学用 enzymatic browning 指切开苹果与土豆的变褐。"}],"abstract":[{"en":"Picture gloved hands pressing two pieces together, with the glove carrying a small maker's mark.","cn":"想象戴手套的双手把两块料按到一起，手套上带着小小的制造者标记。"},{"en":"Picture a kitchen that uses a living starter instead of a stove.","cn":"想象一间厨房用活的酵头代替炉火。"},{"en":"Picture a demolition crew that takes the building apart piece by piece instead of blowing it up.","cn":"想象一支拆除队把建筑逐块拆下，而不是炸掉。"}]},"examples":[{"en":"Enzymatic hydrolysis is gentler than acid hydrolysis for food proteins.","cn":"对食品蛋白而言，酶解比酸解更温和。"},{"en":"The researchers measured enzymatic activity every ten minutes.","cn":"研究人员每十分钟测定一次酶活性。"},{"en":"Enzymatic browning can be slowed by adding lemon juice.","cn":"加入柠檬汁可减缓酶促褐变。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「酶（enzyme）＋atic」——带酶属性的、靠酶完成的 → 酶促的、酶解的","word":"enzymatic"},"root":"希腊 en-「在内」+ zymē「酵素」→ enzyme（1877）+ 拉丁 -aticus（希腊 -atikos）→ enzymatic。","sensesIntro":{"en":"Eight senses fan out from one relational suffix: the enzyme is the owner, then the method, then the category, then the measured activity, then cutting, then joining, then removing, and finally the control that lacks it.","cn":"八个义项从一个表关系的后缀散开：先是所有者，再是方法、类别、被测的活性、切开、接上、清除，最后是缺少它的对照。"},"semanticMap":{"core":{"en":"CORE IMAGE: gloved hands press two pieces together, and the glove carries the catalyst's mark.","cn":"核心意象：戴手套的双手把两块料按到一起，手套上带着催化剂的标记。"},"chain":["THE CATALYST","ITS RELATION","ITS METHOD","ITS CLASS","ITS RATE","ITS WORK DONE"],"branches":[{"senses":"S1","en":"OWNERSHIP: the plain relational sense, 'of an enzyme'.","cn":"归属：最朴素的关系义，「酶的」。"},{"senses":"S2 · S3","en":"METHOD AND CLASS: a reaction run by the catalyst, and the whole category so defined.","cn":"方法与类别：由催化剂推动的反应，以及由此定义的整类。"},{"senses":"S4","en":"MEASUREMENT: the activity that can be read off an assay.","cn":"测定：可从测定中读出的活性。"},{"senses":"S5 · S6 · S7","en":"CUT, JOIN, REMOVE: hydrolysis, synthesis and degradation all use the same adjective.","cn":"切、接、除：酶解、酶法合成与酶促降解共用同一个形容词。"},{"senses":"S8","en":"CONTROL: the negated form defines the process by what it does without.","cn":"对照：否定形式用「缺少什么」来定义过程。"}]},"affixes":{"intro":{"en":"The adjective is the English noun enzyme plus the relational suffix -atic, from Latin -aticus and Greek -atikos.","cn":"该形容词是英语名词 enzyme 加关系后缀 -atic，后者出自拉丁 -aticus 与希腊 -atikos。"},"latinIntro":{"en":"Only the suffix is Latin; the base is Greek plus modern coinage. New Latin enzyma is a re-spelling, not an inherited word.","cn":"只有后缀是拉丁语；词干是希腊语加现代造词。新拉丁语 enzyma 只是改写拼写，不是传承词。"},"items":[{"word":"enzymatic","structure":"enzyme + -atic (relational)","meaning":"of an enzyme; done by an enzyme","meaningCN":"酶的；由酶完成的","example":"The cleavage is entirely enzymatic.","exampleCN":"这次切割完全由酶完成。"},{"word":"enzymatically","structure":"enzymatic + -ally (adverb)","meaning":"by enzymatic means","meaningCN":"以酶促方式地","example":"The product is enzymatically degraded within hours.","exampleCN":"该产物在数小时内被酶促降解。"},{"word":"enzyme","structure":"en- + zymē","meaning":"the catalyst","meaningCN":"酶","example":"The enzyme is stable below forty degrees.","exampleCN":"该酶在四十度以下稳定。"},{"word":"enzymic","structure":"enzyme + -ic (relational)","meaning":"of an enzyme (variant)","meaningCN":"酶的（变体）","example":"Enzymic activity was measured in the extract.","exampleCN":"提取液中测定了酶活性。"},{"word":"enzymology","structure":"enzyme + -logia (study of)","meaning":"the study of enzymes","meaningCN":"酶学","example":"Modern enzymology began with fermentation.","exampleCN":"现代酶学始于发酵研究。"},{"word":"non-enzymatic","structure":"non- (not) + enzymatic","meaning":"not brought about by enzymes","meaningCN":"非酶促的","example":"Non-enzymatic glycation damages proteins.","exampleCN":"非酶促糖化会损伤蛋白质。"},{"word":"enzymatic browning","structure":"enzymatic + browning","meaning":"darkening of food catalysed by enzymes","meaningCN":"由酶催化的食品变褐","example":"Enzymatic browning spoiled the cut fruit.","exampleCN":"酶促褐变使切开的水果变坏。"},{"word":"enzymatic assay","structure":"enzymatic + assay (Latin exagium, a weighing)","meaning":"a test that measures enzyme activity","meaningCN":"测定酶活性的方法","example":"The enzymatic assay needs a standard curve.","exampleCN":"酶法测定需要标准曲线。"}],"latinEntries":[{"word":"-aticus","structure":"Latin adjective suffix, first/second declension","meaning":"relating to; of the nature of","meaningCN":"与……相关的；具……性质的"},{"word":"enzyma","structure":"New Latin enzyma (n., first declension)","meaning":"enzyme (a Latinized scientific name)","meaningCN":"酶（拉丁化科学名称）"},{"word":"exagium","structure":"exagium, exagii (n., second declension)","meaning":"a weighing, a test","meaningCN":"称量；检验"}]}},{"word":"metabolism","ipa_uk":"/məˈtæbəlɪzəm/","ipa_us":"/məˈtæbəˌlɪzəm/","definition_zh":"新陈代谢；生物体内全部化学变化的总和；物质与能量的转化","definition_en":"the whole set of chemical reactions by which a living organism converts substances and energy, keeping itself running","core_image":"一条环形的流水线在同一个身体里转圈，一端拆开原料，另一端拼出新件，中间不断放热","scene":"A hibernating animal slows its metabolism so that one stored fat reserve lasts the whole winter.","sceneCN":"这里 metabolism 指「代谢整体、代谢速率」（第 1 个义项：体内全部化学变化的总和及其运行强度）；冬眠动物让它放慢，一份脂肪储备就能撑过整个冬天。图中可辨识物件：环形流水线、拆解的原料、拼出的新件、散出的热。","pos":[{"tag":"n.","zh":"新陈代谢；代谢（不可数；指不同生物或不同个体的代谢体系时可用复数 metabolisms）"}],"collocations":[{"phrase":"basal metabolism","zh":"基础代谢"},{"phrase":"energy metabolism","zh":"能量代谢"},{"phrase":"lipid metabolism","zh":"脂质代谢"},{"phrase":"drug metabolism","zh":"药物代谢"},{"phrase":"metabolism rate","zh":"代谢速率"},{"phrase":"carbohydrate metabolism","zh":"碳水化合物代谢"},{"phrase":"cellular metabolism","zh":"细胞代谢"}],"forms":[{"label":"复数（不同体系）","form":"metabolisms"},{"label":"形容词形式","form":"metabolic（代谢的）"},{"label":"动词形式","form":"metabolize（代谢；分解）"},{"label":"施动名词","form":"metabolizer（代谢者；代谢型个体）"}],"derivatives":[{"word":"metabolic","pos":"adj.","zh":"代谢的"},{"word":"metabolize","pos":"v.","zh":"代谢；分解"},{"word":"metabolite","pos":"n.","zh":"代谢产物"},{"word":"metabolomics","pos":"n.","zh":"代谢组学"},{"word":"catabolism","pos":"n.","zh":"分解代谢"},{"word":"anabolism","pos":"n.","zh":"合成代谢"}],"senses":[{"no":"01","title":"The whole chemical turnover","titleCN":"新陈代谢：体内全部化学变化的总和","definition":"the entire set of chemical reactions that keep an organism alive","definitionCN":"维持生物体存活所需的全部化学反应","example":"Metabolism includes both the burning of fuel and the building of new tissue.","exampleCN":"新陈代谢既包括燃烧燃料，也包括构建新组织。","why":"Greek metabolē meant 'a change, a turning over'; physiology took the word for the constant change inside a body, so the name starts as change itself.","whyCN":"希腊 metabolē 意为「变化、翻转」；生理学用它指体内持续发生的更换，因此这个名字的起点就是「变化」。"},{"no":"02","title":"Materials passing through","titleCN":"物质代谢：原料的进出与转化","definition":"the material side of that turnover, the conversion of substances into other substances","definitionCN":"这一周转的物质面：一种物质被转化为另一种物质","example":"Protein metabolism decides how much nitrogen the body keeps.","exampleCN":"蛋白质代谢决定身体保留多少氮。","why":"because the change is chemical, the word also names the material side of the turnover, not only its energy side.","whyCN":"由于变化是化学性的，这个词也命名周转的物质面，而不只是能量面。"},{"no":"03","title":"Energy in and out","titleCN":"能量代谢：放热与耗能","definition":"the energy side of the turnover, the release of energy from fuel and its use for work","definitionCN":"周转的能量面：从燃料释放能量并用于做功","example":"Energy metabolism converts food into heat and movement.","exampleCN":"能量代谢把食物转化为热与运动。","why":"the same loop can be read as a budget of energy, so the word covers calories as well as molecules.","whyCN":"同一条环路也可以读成能量预算，因此这个词同时覆盖分子与卡路里。"},{"no":"04","title":"The idle rate","titleCN":"基础代谢：静息时的最低消耗","definition":"the rate of turnover while at rest, measured as basal metabolism","definitionCN":"静息状态下的周转速率，即基础代谢","example":"Basal metabolism accounts for most of the calories a sedentary adult burns.","exampleCN":"基础代谢占久坐成年人消耗热量的绝大部分。","why":"once measured in the clinic, the word also names a rate, the speed of the loop rather than its contents.","whyCN":"当它在临床被测定后，这个词也命名一个速率，即环路的快慢而非内容。"},{"no":"05","title":"The tearing-down half","titleCN":"分解代谢：拆开与放能","definition":"the breaking-down half of the turnover, catabolism, which releases energy","definitionCN":"周转中拆解并释放能量的那一半，即分解代谢","example":"Catabolism breaks glucose into carbon dioxide and water.","exampleCN":"分解代谢把葡萄糖拆成二氧化碳和水。","why":"the loop has two halves, and the tearing side is one of them; the word as a whole can name that half.","whyCN":"环路有两半，拆解的一侧是其中之一；作为一个整体，这个词也可指那一半。"},{"no":"06","title":"The building half","titleCN":"合成代谢：拼装与耗能","definition":"the building half of the turnover, anabolism, which consumes energy","definitionCN":"周转中拼装并消耗能量的那一半，即合成代谢","example":"Anabolism uses ATP to assemble amino acids into muscle.","exampleCN":"合成代谢用 ATP 把氨基酸组装成肌肉。","why":"because the same loop both breaks and builds, the whole word can stand for the constructing half as well.","whyCN":"由于同一条环路既拆又建，整个词也可指构建的那一半。"},{"no":"07","title":"What the body does to a drug","titleCN":"药物代谢：体内对药物的改造","definition":"the chemical alteration of drugs and other foreign compounds inside the body","definitionCN":"药物及其他外来化合物在体内被化学改造的过程","example":"A fast metabolism clears the drug before the next dose is due.","exampleCN":"代谢快的人在下一次给药前就把药清除掉了。","why":"pharmacology applies the loop to foreign molecules, so the word also names detoxification rather than nourishment.","whyCN":"药理学把这条环路用于外来分子，因此这个词也命名解毒过程，而不是营养过程。"},{"no":"08","title":"The map of all routes","titleCN":"代谢网络：全部通路的集合","definition":"the network of all the pathways taken together, studied as a system","definitionCN":"把全部通路作为一个系统来研究的网络","example":"Systems biology draws the whole metabolism as a map of arrows.","exampleCN":"系统生物学把整个代谢画成一张箭头地图。","why":"when the single loop is scaled up, it becomes a network; the singular word then names the map rather than a reaction.","whyCN":"当单一环路被放大，它就成了网络；单数形式此时命名的是那张地图，而不是某一反应。"}],"etymology":{"intro":{"en":"Metabolism comes from Greek metabolē 'a change, a turning over', built on meta- 'over, beyond' and ballein 'to throw'. English first used it for change in general.","cn":"metabolism 出自希腊 metabolē「变化、翻转」，由 meta-「越过」与 ballein「投掷」构成。英语最初用它泛指变化。"},"items":[{"era":"GREEK METABOLE","en":"metabolē named a change or a turning over, including a change of government. The base is a Greek noun of action, not a Latin one.","cn":"metabolē 指变化或翻转，也包括政权的更替。其词基是希腊动作名词，不是拉丁语。"},{"era":"GREEK BALLEIN","en":"ballein 'to throw' supplies the second element; meta- adds the idea of change of place or state. The deeper origin of ballein is not settled.","cn":"ballein「投掷」提供第二个构件；meta- 加入位置或状态改变的意思。ballein 的更深来源并无定论。"},{"era":"ENGLISH ARRIVAL","en":"English metabolism appears in the seventeenth century for change in general; the first citation is approximate.","cn":"英语 metabolism 于 17 世纪出现，泛指变化；最早书证年代为约数。"},{"era":"PHYSIOLOGY","en":"Nineteenth-century physiology narrowed the word to the chemical turnover of a living body, the sense that now dominates.","cn":"19 世纪生理学把该词收窄为活体内的化学周转，即今天主导的义项。"},{"era":"BIOCHEMISTRY","en":"Twentieth-century biochemistry split the loop into catabolism and anabolism and mapped the pathways as a network.","cn":"20 世纪生物化学把环路分成分解代谢与合成代谢，并把它绘成通路网络。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): ballein has no agreed pre-Greek source, so any Indo-European form behind it is a reconstruction; the earliest English date is also approximate.","cn":"来源不确定（更深词源）：ballein 在希腊语之前的来源并无共识，其背后的印欧形式属重构；英语最早书证年代亦为约数。"}]},"similar":{"note":{"en":"Group one holds look-alikes that share meta- but not always the same root; group two holds the two halves and the neighbouring processes.","cn":"第一组是共享 meta- 但未必同源的形近词；第二组是这一过程的两半以及相邻过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"metabolic","ipa":"/ˌmetəˈbɒlɪk/","tag":"adjective, not the process","definition":"The adjective 'of metabolism'; it qualifies rate, pathway or disease but does not name the whole turnover.","definitionCN":"形容词「代谢的」；修饰速率、通路或疾病，但不命名整个周转过程。"},{"word":"metastasis","ipa":"/məˈtæstəsɪs/","tag":"meta- but stasis, not ballein","definition":"The spread of cancer, from Greek meta- 'beyond' plus stasis 'standing'. It shares the prefix and not the root, so it is not a relative of metabolism.","definitionCN":"指癌症的转移，由希腊 meta-「越过」加 stasis「站立」构成；只共享前缀而词根不同，因此与 metabolism 并非同族。"},{"word":"metabolite","ipa":"/məˈtæbəlaɪt/","tag":"a product, not the process","definition":"A substance produced or consumed during metabolism; it is an item in the loop, not the loop.","definitionCN":"指代谢过程中产生或消耗的物质；是环路中的一项，而不是环路。"},{"word":"metaphor","ipa":"/məˈtæfə(r)/","tag":"meta- + pherein","definition":"A figure of speech, from meta- 'over' plus pherein 'to carry'. Another meta- word with an unrelated root.","definitionCN":"一种修辞，由 meta-「越过」加 pherein「搬运」构成；又一个前缀相同而词根无关的词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"catabolism","ipa":"/kəˈtæbəlɪzəm/","tag":"the tearing half","definition":"The set of reactions that break molecules down and release energy; it is one half of metabolism.","definitionCN":"指拆解分子并释放能量的一组反应；是代谢的一半。"},{"word":"anabolism","ipa":"/əˈnæbəlɪzəm/","tag":"the building half","definition":"The set of reactions that build molecules and consume energy; the other half of metabolism.","definitionCN":"指构建分子并消耗能量的一组反应；是代谢的另一半。"},{"word":"respiration","ipa":"/rɪˈspɪreɪʃn/","tag":"one energy route","definition":"The process by which cells obtain energy from fuel, usually with oxygen; it is a major route inside metabolism.","definitionCN":"指细胞从燃料获取能量、通常需氧的过程；是代谢内部的主干路线。"},{"word":"digestion","ipa":"/daɪˈdʒestʃən/","tag":"the preparation step","definition":"The breakdown of food before it enters the body's chemistry; digestion precedes most metabolism.","definitionCN":"指食物进入体内化学之前的分解；消化先于大部分代谢。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"meta- 'over' + ballein 'to throw': a constant throwing over, change itself.","cn":"meta-「越过」+ ballein「投掷」：不停翻来覆去地更换，也就是「变化」本身。"},{"en":"The family runs metabolism, metabolic, metabolize, metabolite, metabolomics.","cn":"同族词包括 metabolism、metabolic、metabolize、metabolite、metabolomics。"},{"en":"Fixed phrases: basal metabolism, energy metabolism, lipid metabolism, drug metabolism.","cn":"固定搭配：基础代谢、能量代谢、脂质代谢、药物代谢。"},{"en":"The loop has two halves: catabolism tears down, anabolism builds up.","cn":"环路有两半：分解代谢拆，合成代谢建。"},{"en":"A slow metabolism is a rate, not a substance; do not confuse it with a metabolite.","cn":"「代谢慢」说的是速率，不是物质；别与代谢产物混为一谈。"}],"abstract":[{"en":"Picture a loop of conveyor belts that never stop, tearing and joining at once.","cn":"想象一条不停的环形传送带，一边拆一边接。"},{"en":"Picture a stove that both burns wood and builds furniture from the same pile.","cn":"想象一座炉子，同一堆木料既用来烧，也用来做家具。"},{"en":"Picture an accounting book where income and spending are kept in one column.","cn":"想象一本账，收入与支出记在同一栏里。"}]},"examples":[{"en":"Regular exercise raises resting metabolism for several hours.","cn":"规律运动会提高数小时的静息代谢。"},{"en":"The liver handles most drug metabolism in the body.","cn":"体内大部分药物代谢由肝脏承担。"},{"en":"Metabolism in a dormant seed nearly stops until water returns.","cn":"休眠种子在水分回来之前代谢几乎停止。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「每天（meta）都在烧（bal）」——身体里不停拆与建的化学周转 → 新陈代谢","word":"metabolism"},"root":"希腊 metabolē「变化、翻转」（meta-「越过」+ ballein「投掷」）→ 英语 metabolism；19 世纪收窄为体内化学周转。","sensesIntro":{"en":"Eight senses follow one movement: a loop keeps turning inside a body, and that turning is read as the whole turnover, as materials, as energy, as a resting rate, as the tearing half, as the building half, as drug clearing, and as a map of all routes.","cn":"八个义项沿同一个动作展开：身体里的一条环路不停转动，这次转动依次被读成整体周转、物质、能量、静息速率、拆解的一半、构建的一半、药物清除，以及全部路线的地图。"},"semanticMap":{"core":{"en":"CORE IMAGE: a closed loop that tears materials apart at one end and joins new ones at the other, shedding heat.","cn":"核心意象：一条闭环，一端拆开材料，另一端拼出新物，同时散出热。"},"chain":["TURN OVER","BREAK DOWN","RELEASE ENERGY","BUILD UP","STORE OR GROW","CLEAR THE WASTE"],"branches":[{"senses":"S1","en":"THE WHOLE LOOP: the turnover as such, the plainest sense.","cn":"整条环路：周转本身，最朴素的义项。"},{"senses":"S2 · S3","en":"TWO LEDGERS: the same loop read as material flow and as energy flow.","cn":"两本账：同一条环路被读成物质流与能量流。"},{"senses":"S4","en":"SPEED: at rest the loop has a measurable idle rate.","cn":"速度：静息时环路有一个可测的怠速。"},{"senses":"S5 · S6","en":"TWO HALVES: tearing down and building up, each able to stand for the whole.","cn":"两半：拆解与构建，各自都能代指整体。"},{"senses":"S7 · S8","en":"FOREIGN MATTER AND MAP: clearing drugs, and drawing every route as one network.","cn":"外来物与地图：清除药物，并把所有路线绘成一张网络。"}]},"affixes":{"intro":{"en":"Metabolism is a Greek compound behind a Latinized ending -ismus; the English family adds Latin -ic and -ita and Greek -omics.","cn":"metabolism 是拉丁化词尾 -ismus 包裹的希腊合成词；英语词族另加拉丁 -ic、-ita 与希腊 -omics。"},"latinIntro":{"en":"No inherited Latin base exists. New Latin metabolismus is a Latinized spelling; the -ismus ending reached English through Latin and French.","cn":"没有传承的拉丁词基。新拉丁语 metabolismus 是拉丁化拼写；-ismus 词尾经拉丁语与法语进入英语。"},"items":[{"word":"metabolism","structure":"metabolē + -ismus (Greek -ismos, via Latin)","meaning":"the turnover of a living body","meaningCN":"活体的化学周转","example":"Metabolism slows during fasting.","exampleCN":"禁食期间代谢变慢。"},{"word":"metabolic","structure":"metabolism + -ic (relational)","meaning":"of metabolism","meaningCN":"代谢的","example":"Metabolic rate rises with fever.","exampleCN":"发热时代谢率升高。"},{"word":"metabolize","structure":"metabolism + -ize (verb)","meaning":"to subject a substance to metabolism","meaningCN":"对物质进行代谢","example":"The liver metabolizes most drugs.","exampleCN":"肝脏代谢大多数药物。"},{"word":"metabolite","structure":"metabolism + -ite (product)","meaning":"a substance made or used in metabolism","meaningCN":"代谢中生成或消耗的物质","example":"Lactate is a metabolite of glucose.","exampleCN":"乳酸是葡萄糖的一种代谢产物。"},{"word":"metabolomics","structure":"metabolite + -omics (whole set)","meaning":"the large-scale study of metabolites","meaningCN":"对代谢物全集的研究","example":"Metabolomics compares hundreds of small molecules.","exampleCN":"代谢组学比较数百种小分子。"},{"word":"catabolism","structure":"cata- (down) + metabolism","meaning":"the tearing-down half","meaningCN":"拆解的一半","example":"Catabolism releases energy from fat.","exampleCN":"分解代谢从脂肪中释放能量。"},{"word":"anabolism","structure":"ana- (up) + metabolism","meaning":"the building half","meaningCN":"构建的一半","example":"Anabolism requires energy and building blocks.","exampleCN":"合成代谢需要能量与构建单元。"},{"word":"metabolizer","structure":"metabolize + -er (agent)","meaning":"a person or organ that metabolizes","meaningCN":"进行代谢的人或器官","example":"Fast metabolizers clear caffeine quickly.","exampleCN":"快代谢型的人清除咖啡因很快。"},{"word":"basal metabolism","structure":"basal (Latin basis, base) + metabolism","meaning":"the resting rate of turnover","meaningCN":"静息时的周转速率","example":"Basal metabolism is measured after sleep.","exampleCN":"基础代谢在睡眠后测定。"}],"latinEntries":[{"word":"metabolismus","structure":"New Latin metabolismus (m., second declension)","meaning":"metabolism (a Latinized scientific name)","meaningCN":"代谢（拉丁化科学名称）"},{"word":"-ismus","structure":"Latin suffix from Greek -ismos","meaning":"action, state, system","meaningCN":"动作；状态；体系"},{"word":"basis","structure":"basis, basis (f., Greek loanword, third declension)","meaning":"a base, a foundation","meaningCN":"基底；基础"}]}},{"word":"metabolic","ipa_uk":"/ˌmetəˈbɒlɪk/","ipa_us":"/ˌmetəˈbɑːlɪk/","definition_zh":"代谢的；新陈代谢的；与代谢速率、通路或代谢疾病相关的","definition_en":"relating to metabolism, or to the rate, pathways and disorders of the body's chemical turnover","core_image":"一条环形流水线被画上刻度盘，盘上指针上下移动，旁边贴着「这条线的状态」的标签","scene":"Metabolic rate falls at night, so the body burns less fuel while asleep.","sceneCN":"这里 metabolic 指「代谢速率的」（第 2 个义项：修饰速率，说明周转的快慢）；夜间速率下降，睡眠时消耗的燃料更少。图中可辨识物件：环形流水线、刻度盘、上下摆动的指针、状态标签。","pos":[{"tag":"adj.","zh":"代谢的；新陈代谢的（多作定语，修饰 rate、pathway、disease 等）"}],"collocations":[{"phrase":"metabolic rate","zh":"代谢率"},{"phrase":"metabolic pathway","zh":"代谢通路"},{"phrase":"metabolic disease","zh":"代谢性疾病"},{"phrase":"metabolic syndrome","zh":"代谢综合征"},{"phrase":"metabolic activity","zh":"代谢活动"},{"phrase":"metabolic waste","zh":"代谢废物"},{"phrase":"metabolic enzyme","zh":"代谢酶"}],"forms":[{"label":"比较级（少用）","form":"more metabolic"},{"label":"副词形式","form":"metabolically（在代谢方面地）"},{"label":"名词原形","form":"metabolism（新陈代谢）"},{"label":"相关形容词","form":"metabolizable（可代谢的）"}],"derivatives":[{"word":"metabolism","pos":"n.","zh":"新陈代谢"},{"word":"metabolically","pos":"adv.","zh":"在代谢方面地"},{"word":"metabolize","pos":"v.","zh":"代谢；分解"},{"word":"metabolite","pos":"n.","zh":"代谢产物"},{"word":"antimetabolic","pos":"adj.","zh":"抗代谢的（较少用）"}],"senses":[{"no":"01","title":"Of metabolism as a whole","titleCN":"代谢的：整体归属","definition":"relating to metabolism in general","definitionCN":"与新陈代谢整体相关","example":"Metabolic processes keep the cell's chemistry in balance.","exampleCN":"代谢过程使细胞的化学保持平衡。","why":"the -ic suffix turns the process into a relational adjective, so the word first means 'of metabolism'.","whyCN":"后缀 -ic 把过程变成关系形容词，因此这个词首先意为「代谢的」。"},{"no":"02","title":"The speed of the loop","titleCN":"代谢率的：周转的快慢","definition":"describing the rate at which the body's turnover runs","definitionCN":"描述身体周转运行的速率","example":"A higher metabolic rate lets a small mammal stay warm in winter.","exampleCN":"较高的代谢率让小型哺乳动物在冬天保持体温。","why":"once physiologists measured the loop, the adjective attached to its speed, not only to its existence.","whyCN":"当生理学家开始测定这条环路，这个形容词便附着在它的速度上，而不只是它的存在。"},{"no":"03","title":"A route inside the map","titleCN":"代谢通路的：路线层面","definition":"describing one route or step within the network of reactions","definitionCN":"描述反应网络中的某条路线或某个步骤","example":"Glycolysis is a metabolic pathway shared by almost all cells.","exampleCN":"糖酵解是几乎所有细胞共有的代谢通路。","why":"the loop is drawn as many routes, so the adjective also marks a single path through the map.","whyCN":"这条环路被画成许多路线，因此这个形容词也标记地图中的单条路径。"},{"no":"04","title":"Disorder of the turnover","titleCN":"代谢疾病的：周转出错","definition":"describing disease caused by a fault in metabolism","definitionCN":"描述由代谢缺陷引起的疾病","example":"Phenylketonuria is a metabolic disease found at birth screening.","exampleCN":"苯丙酮尿症是一种在新生儿筛查中发现的代谢病。","why":"when one route fails, the whole body feels it, so the adjective names a clinical class.","whyCN":"当某条路线失灵，全身都会受影响，因此这个形容词命名一个临床类别。"},{"no":"05","title":"What the loop leaves behind","titleCN":"代谢废物的：周转的残余","definition":"describing substances produced as by-products of metabolism","definitionCN":"描述作为代谢副产物产生的物质","example":"The kidneys clear metabolic waste such as urea.","exampleCN":"肾脏清除尿素等代谢废物。","why":"every route has leftovers, so the adjective also qualifies what must be removed rather than what is used.","whyCN":"每条路线都有残余，因此这个形容词也限定必须被清走的东西，而不是被使用的东西。"},{"no":"06","title":"Of the enzymes that run it","titleCN":"代谢酶的：驱动周转的催化者","definition":"describing the enzymes and controls that keep the routes running","definitionCN":"描述维持路线运行的酶与调控","example":"Metabolic enzymes are often the target of drugs.","exampleCN":"代谢酶常是药物的靶点。","why":"since the loop is run by catalysts, the adjective extends to the machinery that drives it.","whyCN":"由于环路由催化剂驱动，这个形容词便延伸到驱动它的机器。"},{"no":"07","title":"Busy tissue","titleCN":"代谢活跃的：组织状态","definition":"describing tissue or an organ with a high turnover, such as liver or muscle in exercise","definitionCN":"描述周转旺盛的组织或器官，如肝脏或运动中的肌肉","example":"The liver is the most metabolically active organ per gram.","exampleCN":"按每克计，肝脏是代谢最活跃的器官。","why":"high turnover is a visible property of a tissue, so the adjective can describe a state rather than a process.","whyCN":"高周转是组织可见的属性，因此这个形容词可以描述一种状态，而非一个过程。"},{"no":"08","title":"The clustered clinical picture","titleCN":"代谢综合征的：成组出现的临床征象","definition":"describing the cluster of obesity, high blood sugar, high lipids and hypertension","definitionCN":"描述肥胖、高血糖、高血脂与高血压成组出现的情形","example":"Metabolic syndrome raises the risk of diabetes and heart disease.","exampleCN":"代谢综合征提高糖尿病与心脏病的风险。","why":"modern medicine grouped several signs under one name, so the adjective came to label that cluster.","whyCN":"现代医学把若干征象归在一个名下，这个形容词便用来标记那一组。"}],"etymology":{"intro":{"en":"Metabolic is metabolism plus the relational suffix -ic, from Latin -icus and Greek -ikos. The base came from Greek metabolē 'a change'.","cn":"metabolic 是 metabolism 加关系后缀 -ic，后者出自拉丁 -icus 与希腊 -ikos；词基来自希腊 metabolē「变化」。"},"items":[{"era":"GREEK BASE","en":"metabolē 'a change, a turning over' comes from meta- 'over' plus ballein 'to throw'; English metabolism was first a general word for change.","cn":"metabolē「变化、翻转」由 meta-「越过」加 ballein「投掷」构成；英语 metabolism 最初泛指变化。"},{"era":"SUFFIX -IKOS","en":"Greek -ikos formed adjectives of relation, and Latin took it as -icus; English keeps both as -ic.","cn":"希腊 -ikos 构成关系形容词，拉丁语吸收为 -icus；英语保留为 -ic。"},{"era":"ENGLISH -IC","en":"The adjective appears in nineteenth-century physiology once metabolism was fixed as the body's chemical turnover; the first citation is approximate.","cn":"当 metabolism 被固定为体内化学周转后，该形容词于 19 世纪生理学文献中出现；最早书证年代为约数。"},{"era":"CLINICAL USE","en":"Twentieth-century medicine produced metabolic disease, metabolic syndrome and metabolic rate as standard labels.","cn":"20 世纪医学产生了 metabolic disease、metabolic syndrome、metabolic rate 等标准标签。"},{"era":"PATHWAY MAPS","en":"Biochemistry in the same century mapped the routes and fixed metabolic pathway as a term.","cn":"同一世纪的生物化学绘出路线图，并固定了 metabolic pathway 这一术语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin and first date): ballein has no agreed pre-Greek origin and the Indo-European forms behind it are reconstructions; the earliest citation of the adjective is also not recorded.","cn":"来源不确定（更深词源与首见年代）：ballein 在希腊语之前的来源无共识，其印欧形式属重构；该形容词的最早书证亦无确切记录。"}]},"similar":{"note":{"en":"Group one holds words of the same family or of a look-alike prefix; group two holds adjectives used in the same physiological sentences.","cn":"第一组是同族词或前缀形近词；第二组是出现在同一类生理学句子中的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"metabolism","ipa":"/məˈtæbəlɪzəm/","tag":"the noun, not the adjective","definition":"The process itself. Metabolic qualifies a rate, route or disease, and cannot replace the noun.","definitionCN":"指过程本身；metabolic 只限定速率、路线或疾病，不能替代名词。"},{"word":"metabolize","ipa":"/məˈtæbəlaɪz/","tag":"the verb","definition":"To act on a substance, as in 'the liver metabolizes the drug'. It names an action, not a quality.","definitionCN":"指对物质起作用，如「肝脏代谢该药」；命名动作，不是性质。"},{"word":"metastasis","ipa":"/məˈtæstəsɪs/","tag":"same prefix, different root","definition":"Cancer spread, from meta- plus stasis 'standing'. It shares meta- but not ballein, so it is not a metabolic relative.","definitionCN":"指癌症转移，由 meta- 加 stasis「站立」构成；共享 meta-，但词根不是 ballein，故与 metabolic 不同族。"},{"word":"metabolite","ipa":"/məˈtæbəlaɪt/","tag":"a substance, not a property","definition":"A product or input of metabolism. It is a countable molecule and never an adjective.","definitionCN":"指代谢的产物或输入物；是可数分子，从不用作形容词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"catabolic","ipa":"/ˌkætəˈbɒlɪk/","tag":"the tearing half","definition":"Relating to catabolism, the breaking-down reactions. It is a narrower label than metabolic.","definitionCN":"与分解代谢的拆解反应相关；比 metabolic 范围更窄。"},{"word":"anabolic","ipa":"/ˌænəˈbɒlɪk/","tag":"the building half","definition":"Relating to anabolism, the building reactions that consume energy.","definitionCN":"与消耗能量的合成反应相关。"},{"word":"biochemical","ipa":"/ˌbaɪəʊˈkemɪkl/","tag":"the whole field","definition":"Relating to the chemistry of living things generally; metabolic points specifically at the turnover.","definitionCN":"泛指生物体内的化学；metabolic 特指周转过程。"},{"word":"energetic","ipa":"/ˌenəˈdʒetɪk/","tag":"about energy, not turnover","definition":"Describing energy or liveliness; it does not name the body's chemical loop.","definitionCN":"描述能量或活力；不命名体内的化学环路。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"metabolism + -ic: the relational ending of metabolic, catabolic and anabolic.","cn":"metabolism + -ic：与 metabolic、catabolic、anabolic 相同的关系词尾。"},{"en":"The family runs metabolism, metabolic, metabolize, metabolite, metabolically.","cn":"同族词包括 metabolism、metabolic、metabolize、metabolite、metabolically。"},{"en":"Fixed phrases: metabolic rate, metabolic pathway, metabolic disease, metabolic syndrome.","cn":"固定搭配：代谢率、代谢通路、代谢病、代谢综合征。"},{"en":"The pair is easy: metabolism is the loop, metabolic is the adjective of the loop.","cn":"这组很好分：metabolism 是环路，metabolic 是环路的形容词。"},{"en":"Exercise raises metabolic rate, and the liver is the most metabolically active organ by weight.","cn":"运动会提高代谢率，而按重量计肝脏是代谢最活跃的器官。"}],"abstract":[{"en":"Picture a dial on a conveyor loop, with a needle showing how fast it turns.","cn":"想象环形传送带上装一个表盘，指针显示它转得多快。"},{"en":"Picture a map where each route is one coloured line in a single network.","cn":"想象一张地图，每条路线都是同一网络中的一条彩线。"},{"en":"Picture a ledger that records both what is spent and what is thrown away.","cn":"想象一本账，既记录花费，也记录丢弃。"}]},"examples":[{"en":"Metabolic activity in the brain stays high even during sleep.","cn":"睡眠中大脑的代谢活动依然很高。"},{"en":"A metabolic disorder was found in the newborn screening.","cn":"新生儿筛查中发现了一种代谢障碍。"},{"en":"The drug blocks a metabolic pathway used by the parasite.","cn":"该药阻断寄生虫使用的一条代谢通路。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「代谢（metabolism）＋ic」——带代谢属性的 → 代谢的、代谢速率的","word":"metabolic"},"root":"希腊 metabolē「变化」（meta- + ballein「投掷」）→ metabolism + 拉丁 -icus / 希腊 -ikos → metabolic。","sensesIntro":{"en":"Eight senses fan out from one relational suffix: the whole loop, its speed, one route, its failures, its leftovers, its enzymes, a busy tissue, and a cluster of clinical signs.","cn":"八个义项从一个表关系的后缀散开：整条环路、它的速度、单条路线、它的故障、它的残余、它的酶、活跃的组织，以及一组临床征象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dial mounted on a turning loop, measuring how fast the loop runs.","cn":"核心意象：环形传送带上装着表盘，测量环路转得多快。"},"chain":["THE LOOP","ITS SPEED","ONE ROUTE","A BROKEN ROUTE","LEFTOVERS","THE WHOLE PICTURE"],"branches":[{"senses":"S1","en":"OWNERSHIP: the plainest reading, 'of metabolism'.","cn":"归属：最朴素的义项，「代谢的」。"},{"senses":"S2","en":"SPEED: the dial reading, the rate of turnover.","cn":"速度：表盘读数，即周转速率。"},{"senses":"S3 · S6","en":"ROUTES AND MACHINERY: a single pathway and the enzymes that run it.","cn":"路线与机器：单条通路，以及驱动它的酶。"},{"senses":"S4 · S5","en":"FAILURE AND RESIDUE: disease when a route breaks, and waste that must be cleared.","cn":"故障与残余：路线断裂时的疾病，以及必须清除的废物。"},{"senses":"S7 · S8","en":"STATE AND SYNDROME: a busy tissue, and several signs grouped under one label.","cn":"状态与综合征：活跃的组织，以及归在一个标签下的若干征象。"}]},"affixes":{"intro":{"en":"Metabolic is the Greek-derived noun metabolism plus the relational suffix -ic, from Latin -icus and Greek -ikos.","cn":"metabolic 是希腊来源名词 metabolism 加关系后缀 -ic，后者出自拉丁 -icus 与希腊 -ikos。"},"latinIntro":{"en":"Only the suffix series is Latin-based; the base is the Greek metabolē, and New Latin metabolismus is a Latinized spelling.","cn":"只有后缀系列基于拉丁语；词基是希腊 metabolē，新拉丁语 metabolismus 只是拉丁化拼写。"},"items":[{"word":"metabolic","structure":"metabolism + -ic (relational)","meaning":"of metabolism","meaningCN":"代谢的","example":"Metabolic rate is measured at rest.","exampleCN":"代谢率在静息状态下测定。"},{"word":"metabolically","structure":"metabolic + -ally (adverb)","meaning":"in metabolic terms","meaningCN":"在代谢方面地","example":"The tissue is metabolically quiet.","exampleCN":"该组织代谢上很安静。"},{"word":"metabolism","structure":"metabolē + -ismus","meaning":"the body's chemical turnover","meaningCN":"体内的化学周转","example":"Metabolism slows with age.","exampleCN":"代谢随年龄减慢。"},{"word":"metabolite","structure":"metabolism + -ite (product)","meaning":"a substance made or used in metabolism","meaningCN":"代谢产物","example":"The metabolite was excreted in urine.","exampleCN":"该代谢产物经尿排出。"},{"word":"metabolize","structure":"metabolism + -ize (verb)","meaning":"to subject to metabolism","meaningCN":"进行代谢","example":"Cells metabolize glucose for energy.","exampleCN":"细胞代谢葡萄糖以获得能量。"},{"word":"catabolic","structure":"catabolism + -ic","meaning":"of the tearing-down reactions","meaningCN":"分解代谢的","example":"Catabolic hormones raise blood sugar.","exampleCN":"分解代谢类激素升高血糖。"},{"word":"anabolic","structure":"anabolism + -ic","meaning":"of the building reactions","meaningCN":"合成代谢的","example":"Anabolic pathways need ATP.","exampleCN":"合成代谢通路需要 ATP。"},{"word":"metabolic pathway","structure":"metabolic + pathway","meaning":"one route in the network","meaningCN":"代谢通路","example":"The pathway is conserved in bacteria.","exampleCN":"该通路在细菌中保守。"},{"word":"metabolic syndrome","structure":"metabolic + Greek syndromē (a running together)","meaning":"a cluster of metabolic signs","meaningCN":"一组代谢征象","example":"Metabolic syndrome is diagnosed clinically.","exampleCN":"代谢综合征以临床方式诊断。"}],"latinEntries":[{"word":"-icus","structure":"Latin adjective suffix, first/second declension","meaning":"relating to, of the nature of","meaningCN":"与……相关的；具……性质的"},{"word":"metabolismus","structure":"New Latin metabolismus (m., second declension)","meaning":"metabolism (a Latinized scientific name)","meaningCN":"代谢（拉丁化科学名称）"}]}},{"word":"metabolize","ipa_uk":"/məˈtæbəlaɪz/","ipa_us":"/ˈmetəbəlaɪz/","definition_zh":"代谢；分解；把物质在体内转化（为能量或别的物质）","definition_en":"to subject a substance to the chemical changes of metabolism, breaking it down or converting it into something else","core_image":"一台机器把一块原料吞进去，从另一头送出小零件与热量，机器本身毫发无损","scene":"The liver can metabolize only a limited amount of alcohol per hour.","sceneCN":"这里 metabolize 指「分解、转化某物」（第 1 个义项：对物质施加代谢性化学改造）；肝脏每小时只能处理有限量的酒精。图中可辨识物件：吞料的机器、原料块、送出的零件、散出的热。","pos":[{"tag":"v.","zh":"代谢；分解（及物动词，常用被动 be metabolized）"}],"collocations":[{"phrase":"metabolize glucose","zh":"代谢葡萄糖"},{"phrase":"metabolize a drug","zh":"代谢药物"},{"phrase":"rapidly metabolized","zh":"被迅速代谢"},{"phrase":"metabolize fat","zh":"代谢脂肪"},{"phrase":"poorly metabolized","zh":"代谢不良"},{"phrase":"metabolize into","zh":"代谢转化为"}],"forms":[{"label":"第三人称单数","form":"metabolizes"},{"label":"过去式","form":"metabolized"},{"label":"过去分词","form":"metabolized"},{"label":"现在分词","form":"metabolizing"},{"label":"名词形式","form":"metabolization（代谢过程）"}],"derivatives":[{"word":"metabolism","pos":"n.","zh":"新陈代谢"},{"word":"metabolic","pos":"adj.","zh":"代谢的"},{"word":"metabolite","pos":"n.","zh":"代谢产物"},{"word":"metabolizer","pos":"n.","zh":"代谢者；代谢型个体"},{"word":"metabolizable","pos":"adj.","zh":"可代谢的"}],"senses":[{"no":"01","title":"To act on a substance chemically","titleCN":"代谢：对物质施以化学改造","definition":"to subject a substance to the chemical changes of metabolism","definitionCN":"使某物质经历代谢性的化学变化","example":"Bacteria metabolize the oil that spills into the sea.","exampleCN":"细菌会代谢泄漏到海里的石油。","why":"the verb turns the noun of change into an action: whatever is acted on is put through that change.","whyCN":"这个动词把表示变化的名词转为动作：被作用的东西就被送进那场变化。"},{"no":"02","title":"To break food down","titleCN":"分解营养：把食物拆成小件","definition":"to break a nutrient down into smaller molecules the body can use","definitionCN":"把营养素拆成身体可用的小分子","example":"Cells metabolize starch into glucose within minutes.","exampleCN":"细胞在几分钟内把淀粉分解成葡萄糖。","why":"digestion is the most familiar case, so the verb is first heard as breaking food apart.","whyCN":"消化是最熟悉的情形，因此这个动词最初听上去就是把食物拆开。"},{"no":"03","title":"To alter a drug or poison","titleCN":"转化药物：把外来分子改造","definition":"to convert a drug or toxin into other compounds, usually in the liver","definitionCN":"把药物或毒物转化为其他化合物，通常在肝脏中进行","example":"The enzyme metabolizes the drug into an inactive form.","exampleCN":"这种酶把该药代谢成失活形式。","why":"the same action applied to foreign molecules is detoxification, and the verb carries that clinical sense.","whyCN":"同样的作用施加于外来分子就是解毒，这个动词也带上了这层临床含义。"},{"no":"04","title":"To release energy from fuel","titleCN":"转化为能量：从燃料取出可用能","definition":"to convert fuel into usable energy, as in cellular respiration","definitionCN":"把燃料转化为可用能量，如细胞呼吸","example":"Muscle metabolizes fat during long, slow exercise.","exampleCN":"长时间慢速运动时肌肉代谢脂肪。","why":"because the change yields energy, the verb also names the extraction of power, not only the breakdown.","whyCN":"由于变化会产出能量，这个动词也命名动力的提取，而不只是拆解。"},{"no":"05","title":"To be cleared away","titleCN":"被代谢掉：从体内清除","definition":"to be removed from the body by metabolism, said of a substance in the passive","definitionCN":"指某物质经代谢被从体内清除，多用被动语态","example":"Caffeine is metabolized within a few hours in most adults.","exampleCN":"多数成年人几小时内就把咖啡因代谢掉。","why":"in the passive, the focus moves from the agent to the substance that disappears, so the verb means 'cleared'.","whyCN":"在被动语态中，焦点从作用者移到消失的物质，因此这个动词意为「被清除」。"},{"no":"06","title":"How fast the body handles it","titleCN":"代谢速率：处理快慢","definition":"to handle a substance at a certain rate, as in 'metabolized quickly'","definitionCN":"以一定速率处理某物，如「被迅速代谢」","example":"Some people metabolize caffeine much faster than others.","exampleCN":"有些人代谢咖啡因比其他人快得多。","why":"rate adverbs attach naturally to the verb, so it also reports speed of handling.","whyCN":"速率副词自然附着在这个动词上，因此它也报告处理的快慢。"},{"no":"07","title":"To digest an idea, figuratively","titleCN":"比喻：消化吸收信息或想法","definition":"used figuratively for taking in and absorbing information or an experience","definitionCN":"引申指把信息或经历吸纳、消化","example":"Give the team time to metabolize the new findings.","exampleCN":"给团队一些时间去消化这些新发现。","why":"the body's handling of matter is borrowed for the mind's handling of ideas, a common figurative extension.","whyCN":"身体处理物质的方式被借用于心智处理想法，这是常见的比喻延伸。"},{"no":"08","title":"To convert along a pathway","titleCN":"生化义：沿途径转化","definition":"to convert one compound into another along a defined biochemical pathway","definitionCN":"沿确定的生化途径把一种化合物转化为另一种","example":"The fungus metabolizes the sugar into an acid.","exampleCN":"这种真菌把糖代谢成一种酸。","why":"in biochemistry the verb marks the direction of a conversion, from substrate to product.","whyCN":"在生物化学中，这个动词标记转化的方向，从底物到产物。"}],"etymology":{"intro":{"en":"Metabolize is metabolism plus the verb suffix -ize, from Greek -izein through Latin and French. The base is Greek metabolē 'a change'.","cn":"metabolize 是 metabolism 加动词后缀 -ize，后者由希腊 -izein 经拉丁语与法语传入；词基是希腊 metabolē「变化」。"},"items":[{"era":"GREEK -IZEIN","en":"Greek -izein formed verbs meaning 'to make, to act in the manner of'. It passed into Latin as -izare and into French as -iser.","cn":"希腊 -izein 构成动词，意为「使……、以……方式行事」。它进入拉丁语为 -izare、法语为 -iser。"},{"era":"BASE METABOLE","en":"metabolē 'a change, a turning over' comes from meta- 'over' plus ballein 'to throw'; English metabolism first meant change in general.","cn":"metabolē「变化、翻转」由 meta-「越过」加 ballein「投掷」构成；英语 metabolism 最初泛指变化。"},{"era":"NINETEENTH-CENTURY VERB","en":"Source uncertain (first date): the verb appears in nineteenth-century physiology after metabolism had been narrowed to the body's chemistry, and the exact first citation is not recorded.","cn":"来源不确定（首见年代）：该动词在 metabolism 被收窄为体内化学之后出现于 19 世纪生理学；确切最早书证并无记录。"},{"era":"DRUG USE","en":"Twentieth-century pharmacology made 'metabolize a drug' a standard phrase, adding the sense of clearing foreign compounds.","cn":"20 世纪药理学使「代谢某药」成为标准说法，加入了清除外来化合物的义项。"},{"era":"FIGURATIVE USE","en":"Late twentieth-century writing extended the verb to ideas and experiences, as in 'metabolize new information'.","cn":"20 世纪后期的写作把该动词延伸到想法与经历，如「消化新信息」。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): ballein has no agreed pre-Greek origin, so any Indo-European form behind it is a reconstruction rather than a recorded word.","cn":"来源不确定（更深词源）：ballein 在希腊语之前的来源并无共识，其背后的印欧形式属重构，而非有记录的实际词。"}]},"similar":{"note":{"en":"Group one holds the same-family words that differ in part of speech; group two holds ordinary verbs for the same handling seen without the technical frame.","cn":"第一组是同族但词性不同的词；第二组是不带技术框架、表达同样处理的普通动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"metabolism","ipa":"/məˈtæbəlɪzəm/","tag":"the noun","definition":"The process itself, not an action on a substance. It cannot take an object.","definitionCN":"指过程本身，不是对物质的作用；不能带宾语。"},{"word":"metabolite","ipa":"/məˈtæbəlaɪt/","tag":"the product","definition":"A substance made or used during metabolism. It is the result, while metabolize is the act.","definitionCN":"指代谢中生成或消耗的物质；是结果，而 metabolize 是动作。"},{"word":"metabolizer","ipa":"/məˈtæbəlaɪzə(r)/","tag":"the agent","definition":"A person or organ that metabolizes, often classified as fast or slow; it names the doer, not the deed.","definitionCN":"指进行代谢的人或器官，常分为快慢型；命名行动者，不是行为。"},{"word":"metastasize","ipa":"/məˈtæstəsaɪz/","tag":"same suffix, different root","definition":"To spread, as a tumour does, from meta- plus stasis 'standing'. It looks like metabolize but shares no ballein.","definitionCN":"指像肿瘤那样转移，由 meta- 加 stasis「站立」构成；形似 metabolize，却并不共享 ballein。"}]},{"heading":"NEAR MEANING","entries":[{"word":"digest","ipa":"/daɪˈdʒest/","tag":"food only","definition":"To break food down in the gut; metabolism also happens inside cells and to drugs.","definitionCN":"指在肠道中分解食物；代谢也发生在细胞内，也作用于药物。"},{"word":"break down","ipa":"/breɪk daʊn/","tag":"plain and general","definition":"A neutral phrase for splitting a substance apart; it lacks the biochemical frame of metabolize.","definitionCN":"拆分物质的普通说法；没有 metabolize 的生物化学框架。"},{"word":"convert","ipa":"/kənˈvɜːt/","tag":"direction, not process","definition":"To change one thing into another; metabolize adds that the change is part of metabolism.","definitionCN":"指把一物变为另一物；metabolize 补充说明该变化属于代谢。"},{"word":"process","ipa":"/ˈprəʊses/","tag":"very wide","definition":"To handle something by a procedure; it can mean almost anything and is far broader than metabolize.","definitionCN":"指按程序处理某物；含义极宽，远大于 metabolize。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"metabolism + -ize: to put a substance through metabolism.","cn":"metabolism + -ize：把某物送进代谢。"},{"en":"The verb forms run metabolize, metabolizes, metabolized, metabolizing.","cn":"动词形式为 metabolize、metabolizes、metabolized、metabolizing。"},{"en":"Fixed phrases: metabolize glucose, metabolize a drug, rapidly metabolized, poorly metabolized.","cn":"固定搭配：代谢葡萄糖、代谢药物、被迅速代谢、代谢不良。"},{"en":"The passive is common in pharmacology: the drug is metabolized in the liver.","cn":"药理学中常用被动：药物在肝脏被代谢。"},{"en":"Metabolize takes an object; metabolism does not. That one fact keeps them apart.","cn":"metabolize 带宾语，metabolism 不带；这一条就能区分二者。"}],"abstract":[{"en":"Picture a machine that swallows a block and sends out small parts and heat.","cn":"想象一台机器吞进一块料，送出小零件与热。"},{"en":"Picture a kitchen that turns one ingredient into three dishes.","cn":"想象一间厨房把一种原料做成三道菜。"},{"en":"Picture a reader who turns a dense page into something the mind can keep.","cn":"想象一位读者把密密的文字变成心里留得住的东西。"}]},"examples":[{"en":"Some gut bacteria metabolize fibre into short fatty acids.","cn":"一些肠道细菌把纤维代谢成短链脂肪酸。"},{"en":"The patient metabolizes the anaesthetic slowly and needs a lower dose.","cn":"该患者代谢麻醉药较慢，需要更低剂量。"},{"en":"Yeast metabolizes sugar into alcohol when oxygen is scarce.","cn":"缺氧时酵母把糖代谢成酒精。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「代谢（metabolism）＋ize」——让某物走一遍代谢流程 → 代谢、分解","word":"metabolize"},"root":"希腊 metabolē「变化」（meta- + ballein「投掷」）→ metabolism + 希腊 -izein（经拉丁 -izare、法语 -iser）→ metabolize。","sensesIntro":{"en":"Eight senses follow one action: a machine swallows a substance and sends out parts and heat; that action is read as chemical handling, as breaking food, as altering drugs, as releasing energy, as being cleared, as a rate, as digesting ideas, and as a direction along a pathway.","cn":"八个义项沿同一个动作展开：一台机器吞下物质，送出零件与热；这一动作依次被读成化学处理、拆解食物、改造药物、释放能量、被清除、处理速率、消化想法，以及沿通路的方向。"},"semanticMap":{"core":{"en":"CORE IMAGE: a machine that swallows a block and sends out small parts and heat.","cn":"核心意象：一台吞进料块、送出小零件与热的机器。"},"chain":["TAKE IT IN","BREAK IT APART","ALTER IT","EXTRACT ENERGY","CLEAR THE REST","SEND IT ON"],"branches":[{"senses":"S1","en":"THE ACTION: putting a substance through the chemical change.","cn":"动作本身：使某物经历化学变化。"},{"senses":"S2","en":"FOOD: the familiar case of breaking a nutrient into usable pieces.","cn":"食物：把营养素拆成可用小件的熟悉情形。"},{"senses":"S3 · S5","en":"FOREIGN MATTER: altering drugs and toxins, and being cleared from the body.","cn":"外来物：改造药物与毒物，以及被从体内清除。"},{"senses":"S4 · S6","en":"POWER AND PACE: energy taken from fuel, and the rate at which it is handled.","cn":"动力与节奏：从燃料取出能量，以及处理的快慢。"},{"senses":"S7 · S8","en":"MIND AND PATHWAY: ideas absorbed, and a conversion with a direction.","cn":"心智与通路：想法被吸收，以及有方向的转化。"}]},"affixes":{"intro":{"en":"Metabolize is a Greek-derived noun plus the Greek verb suffix -izein, which reached English through Latin -izare and French -iser.","cn":"metabolize 是希腊来源名词加希腊动词后缀 -izein，后者经拉丁 -izare 与法语 -iser 进入英语。"},"latinIntro":{"en":"Latin supplies -izare, the borrowed form of Greek -izein, and New Latin metabolismus is a spelling rather than an inherited word.","cn":"拉丁语提供 -izare，即希腊 -izein 的借入形式；新拉丁语 metabolismus 只是拼写，不是传承词。"},"items":[{"word":"metabolize","structure":"metabolē + -izein (verb)","meaning":"to put a substance through metabolism","meaningCN":"使物质经历代谢","example":"The liver metabolizes the compound slowly.","exampleCN":"肝脏缓慢地代谢该化合物。"},{"word":"metabolizes","structure":"metabolize + -s (third person)","meaning":"he, she or it metabolizes","meaningCN":"第三人称单数形式","example":"The enzyme metabolizes both forms.","exampleCN":"该酶代谢两种形式。"},{"word":"metabolized","structure":"metabolize + -ed (past participle)","meaning":"having been put through metabolism","meaningCN":"已被代谢","example":"The drug is metabolized within hours.","exampleCN":"该药在数小时内被代谢。"},{"word":"metabolizing","structure":"metabolize + -ing (present participle)","meaning":"in the act of metabolizing","meaningCN":"正在代谢","example":"The tissue is actively metabolizing fat.","exampleCN":"该组织正在活跃地代谢脂肪。"},{"word":"metabolization","structure":"metabolize + -ation (noun of action)","meaning":"the act of metabolizing","meaningCN":"代谢这一动作","example":"Metabolization requires oxygen here.","exampleCN":"此处代谢需要氧。"},{"word":"metabolizable","structure":"metabolize + -able (able to be)","meaning":"able to be metabolized","meaningCN":"可被代谢的","example":"Only part of the sugar is metabolizable.","exampleCN":"只有部分糖可被代谢。"},{"word":"metabolizer","structure":"metabolize + -er (agent)","meaning":"one that metabolizes","meaningCN":"代谢者","example":"Fast metabolizers need higher doses.","exampleCN":"快代谢者需要更高剂量。"},{"word":"metabolism","structure":"metabolē + -ismus","meaning":"the whole turnover","meaningCN":"整个周转","example":"Metabolism rises in fever.","exampleCN":"发热时代谢升高。"},{"word":"metabolite","structure":"metabolism + -ite (product)","meaning":"a product of metabolism","meaningCN":"代谢产物","example":"The metabolite is inactive.","exampleCN":"该代谢产物无活性。"}],"latinEntries":[{"word":"-izare","structure":"Latin verb suffix from Greek -izein","meaning":"to make, to act in the manner of","meaningCN":"使……；以……方式行事"},{"word":"metabolismus","structure":"New Latin metabolismus (m., second declension)","meaning":"metabolism (a Latinized scientific name)","meaningCN":"代谢（拉丁化科学名称）"}]}},{"word":"atom","ipa_uk":"/ˈætəm/","ipa_us":"/ˈætəm/","definition_zh":"原子；元素能保持化学性质的最小单位；微量、一点点","definition_en":"the smallest unit of an element that keeps its chemical identity, and by extension a very small amount of anything","core_image":"一颗小小的实心球，中心一点更亮，外围画着几条细轨道，球本身再也切不开","scene":"Each carbon atom in diamond is bonded to four neighbours in a rigid lattice.","sceneCN":"这里 atom 指「原子」这一粒子（第 1 个义项：元素能保持化学性质的最小单位）；金刚石中每个碳原子与四个邻居成键，构成刚性晶格。图中可辨识物件：实心小球、中心亮点、细轨道、四条键。","pos":[{"tag":"n.","zh":"原子；微量（可数，复数 atoms；作「微量」时多用于否定句）"}],"collocations":[{"phrase":"carbon atom","zh":"碳原子"},{"phrase":"atom bomb","zh":"原子弹"},{"phrase":"hydrogen atom","zh":"氢原子"},{"phrase":"atom economy","zh":"原子经济性"},{"phrase":"not an atom of","zh":"一点也没有"},{"phrase":"atom probe","zh":"原子探针"}],"forms":[{"label":"复数","form":"atoms"},{"label":"形容词形式","form":"atomic（原子的）"},{"label":"动词形式","form":"atomize（使雾化；把……分成原子）"},{"label":"名词形式","form":"atomization（雾化；原子化）"}],"derivatives":[{"word":"atomic","pos":"adj.","zh":"原子的"},{"word":"atomize","pos":"v.","zh":"雾化；原子化"},{"word":"atomizer","pos":"n.","zh":"雾化器"},{"word":"atomism","pos":"n.","zh":"原子论"},{"word":"subatomic","pos":"adj.","zh":"亚原子的"}],"senses":[{"no":"01","title":"The smallest unit of an element","titleCN":"原子：元素的最小单位","definition":"the smallest unit of an element that retains its chemical properties","definitionCN":"保持该元素化学性质的最小单位","example":"A gold atom has seventy-nine protons in its nucleus.","exampleCN":"一个金原子的核内有七十九个质子。","why":"Greek atomos meant 'uncut', because such units were proposed as the point beyond which division stops; the name is literally 'the uncuttable'.","whyCN":"希腊 atomos 意为「不可切的」，因为这类单位被设想为分割的终点；这个名字字面上就是「切不开的东西」。"},{"no":"02","title":"A nucleus with electrons","titleCN":"原子结构：核与电子","definition":"the internal structure of an atom: a dense nucleus surrounded by electrons","definitionCN":"原子的内部构造：致密的核与围绕它的电子","example":"The atom is mostly empty space between nucleus and electrons.","exampleCN":"原子内部大部分是核与电子之间的空处。","why":"once atoms were found to have parts, the name covered not only the unit but its architecture.","whyCN":"当原子被发现还有组成部分，这个名字便不仅指单位，也指其构造。"},{"no":"03","title":"The unit that defines an element","titleCN":"元素的最小单位：定义元素身份","definition":"the unit whose proton number fixes which element a sample is","definitionCN":"其质子数决定样本属于哪种元素的单位","example":"Every atom of chlorine has seventeen protons.","exampleCN":"每个氯原子都有十七个质子。","why":"because the proton count is fixed per element, the atom becomes the carrier of elemental identity.","whyCN":"由于每种元素的质子数固定，原子成了元素身份的承载者。"},{"no":"04","title":"A very small amount","titleCN":"微量：一点点","definition":"a tiny amount of something, used mostly in negative or emphatic phrases","definitionCN":"极少量，多用于否定或强调短语","example":"There is not an atom of truth in the rumour.","exampleCN":"这个传言里没有一点真实性。","why":"if an atom is the smallest thing, then 'not an atom' means the smallest possible amount is absent, which is a natural idiom.","whyCN":"如果原子是最小之物，那么「连一个原子都没有」就是说连最小量也不存在，这是很自然的习语。"},{"no":"05","title":"The atom as a power source","titleCN":"核能义：作为能源与武器的原子","definition":"the atom used for atomic energy or atomic weapons","definitionCN":"原子被用于原子能或原子武器","example":"The country debated the peaceful uses of the atom.","exampleCN":"该国就原子的和平利用展开辩论。","why":"mid-twentieth-century politics used 'the atom' to mean nuclear power, so the word also names an energy source.","whyCN":"20 世纪中叶的政治话语用 the atom 指核能，因此这个词也命名一种能源。"},{"no":"06","title":"A counted unit in a formula","titleCN":"化学计量：式中的计数单位","definition":"the atom as a countable unit in formulas and stoichiometry","definitionCN":"式中与化学计量里可计数的单位","example":"The reaction transfers one oxygen atom per molecule.","exampleCN":"该反应每分子转移一个氧原子。","why":"chemistry counts atoms to balance equations, so the word is also a unit in arithmetic.","whyCN":"化学通过数原子来配平方程式，因此这个词也是一个算术单位。"},{"no":"07","title":"The ancient uncuttable piece","titleCN":"哲学义：古代不可分的单元","definition":"the indivisible unit of ancient atomism, proposed before atoms were observed","definitionCN":"古代原子论中不可再分的单元，在被观测之前就被提出","example":"Democritus argued that motion requires atoms and void.","exampleCN":"德谟克利特主张运动需要原子与虚空。","why":"the word was coined for a philosophical claim, not a measurement, so its oldest sense is theoretical.","whyCN":"这个词是为一个哲学主张而造，不是为测量而造，因此最古老的义项是理论性的。"},{"no":"08","title":"The smallest grain of anything","titleCN":"比喻义：任何事物的最小成分","definition":"used figuratively for the minimal component of a system or idea","definitionCN":"引申指系统或观念中最小的成分","example":"Trust is the atom of any long partnership.","exampleCN":"信任是任何长期伙伴关系的最小单元。","why":"because the atom is the model of 'smallest part', it can be borrowed for the smallest part of anything.","whyCN":"由于原子是「最小部分」的模型，它可以被借用于任何事物的最小部分。"}],"etymology":{"intro":{"en":"Atom comes from Greek atomos 'uncut, indivisible', from a- 'not' plus temnein 'to cut'. Latin borrowed it as atomus before English took it.","cn":"atom 出自希腊 atomos「不可切的、不可分的」，由 a-「不」加 temnein「切」构成。拉丁语先以 atomus 借用，之后进入英语。"},"items":[{"era":"GREEK ATOMOS","en":"atomos meant 'uncut' and was used for the indivisible units of Democritus and Epicurus; the word is a philosophical term before it is a physical one.","cn":"atomos 意为「不可切的」，用于德谟克利特与伊壁鸠鲁的不可分单元；在成为物理术语之前，它是哲学术语。"},{"era":"GREEK TEMNEIN","en":"temnein 'to cut' is the root; the same verb stands behind tome and anatomy. Its pre-Greek origin is not established, and any Indo-European form is a reconstruction.","cn":"temnein「切」是词根；同一动词也构成 tome 与 anatomy。其在希腊语之前的来源并无定论，任何印欧形式均属重构。"},{"era":"LATIN ATOMUS","en":"Latin borrowed the Greek word as atomus, keeping both the philosophical sense and the grammatical gender of the original.","cn":"拉丁语以 atomus 借入这个希腊词，既保留哲学义，也保留原词的语法性别。"},{"era":"ENGLISH ARRIVAL","en":"English atom appears in the sixteenth century through Latin; the earliest citation is approximate.","cn":"英语 atom 于 16 世纪经拉丁语传入；最早书证年代为约数。"},{"era":"CHEMICAL ATOM","en":"Dalton's work around 1808 fixed the modern sense: the smallest unit of an element with a characteristic weight.","cn":"道尔顿约 1808 年的工作固定了现代义：具有特征重量的元素最小单位。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): the pre-Greek origin of temnein has no agreed account, so any Indo-European root cited for it is a reconstruction rather than a recorded form.","cn":"来源不确定（更深词源）：temnein 在希腊语之前的来源没有公认解释，所引的任何印欧词根都是重构，而不是有记录的形式。"}]},"similar":{"note":{"en":"Group one holds look-alikes that share the Greek root or the '-ism' ending but name something else; group two holds words on the scale from atom to grain.","cn":"第一组是共享希腊词根或 -ism 词尾、但指别的事物的形近词；第二组是从原子到颗粒这一尺度上的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"atomic","ipa":"/əˈtɒmɪk/","tag":"adjective, not the particle","definition":"The adjective 'of atoms'. It qualifies energy, number or clock, and cannot stand for the particle.","definitionCN":"形容词「原子的」；修饰能量、序数或钟，不能指粒子本身。"},{"word":"atomism","ipa":"/ˈætəmɪzəm/","tag":"the theory, not the unit","definition":"The doctrine that matter consists of indivisible units; it names a theory, not one atom.","definitionCN":"主张物质由不可分单元构成的学说；命名理论，不是单个原子。"},{"word":"anatomy","ipa":"/əˈnætəmi/","tag":"ana- + temnein, a different word","definition":"The study of body structure, from ana- 'up' plus temnein 'to cut'. It shares the cutting root but has no atomos prefix.","definitionCN":"研究身体结构的学科，由 ana-「向上」加 temnein「切」构成；共享「切」的词根，却没有 atomos 的否定前缀。"},{"word":"atomize","ipa":"/ˈætəmaɪz/","tag":"the verb","definition":"To reduce a liquid to fine droplets or to break something into tiny parts; it names an action.","definitionCN":"指把液体雾化或把物体打碎成极小部分；命名动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"molecule","ipa":"/ˈmɒlɪkjuːl/","tag":"atoms joined","definition":"A group of atoms bonded together; it is larger than an atom and made of them.","definitionCN":"指成键结合的一群原子；比原子大，且由原子构成。"},{"word":"element","ipa":"/ˈelɪmənt/","tag":"the kind, not the unit","definition":"A substance made of one kind of atom; the element is the class, the atom is one member.","definitionCN":"指由同种原子构成的物质；元素是类，原子是个体。"},{"word":"particle","ipa":"/ˈpɑːtɪkl/","tag":"any small piece","definition":"Any very small piece of matter, including subatomic ones; atom is one specific level.","definitionCN":"泛指任何极小的物质碎片，包括亚原子粒子；atom 是其中特定的一级。"},{"word":"speck","ipa":"/spek/","tag":"a visible crumb","definition":"A tiny visible mark or crumb, much larger than an atom and used in ordinary speech.","definitionCN":"指肉眼可见的微小颗粒或斑点，比原子大得多，用于日常语言。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"a- 'not' + temnein 'to cut': the uncuttable, the point where division stops.","cn":"a-「不」+ temnein「切」：切不开者，分割到此为止。"},{"en":"The family runs atom, atoms, atomic, atomize, atomizer, atomism.","cn":"同族词包括 atom、atoms、atomic、atomize、atomizer、atomism。"},{"en":"Fixed phrases: carbon atom, hydrogen atom, atom bomb, not an atom of.","cn":"固定搭配：碳原子、氢原子、原子弹、一点也没有。"},{"en":"Proton number fixes the element: seventeen means chlorine, seventy-nine means gold.","cn":"质子数决定元素：十七是氯，七十九是金。"},{"en":"The idiom is negative: not an atom of truth means no truth at all.","cn":"这个习语用于否定：not an atom of truth 意为毫无真实性。"}],"abstract":[{"en":"Picture a ball so hard that every knife breaks before it does.","cn":"想象一个硬到所有刀先断的球。"},{"en":"Picture a tiny solar system with a bright centre and thin orbits.","cn":"想象一个微小的太阳系，中心明亮，轨道纤细。"},{"en":"Picture a brick that no building can be divided beyond.","cn":"想象一块砖，任何建筑拆到它为止。"}]},"examples":[{"en":"A water molecule holds two hydrogen atoms and one oxygen atom.","cn":"一个水分子含两个氢原子和一个氧原子。"},{"en":"The isotope has one extra neutron in each atom.","cn":"该同位素每个原子多一个中子。"},{"en":"He did not offer an atom of evidence for the claim.","cn":"他对该主张没有提供一点证据。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「啊（a）—切（tom）」——切不开的最小块 → 原子；一点点","word":"atom"},"root":"希腊 a-「不」+ temnein「切」→ atomos「不可切的」→ 拉丁 atomus → 英语 atom；1808 年前后由道尔顿固定为化学义。","sensesIntro":{"en":"Eight senses follow one image: a ball that cannot be cut; that image is read as the unit of an element, as a nucleus with orbits, as the carrier of identity, as the smallest amount, as a power source, as a counted unit, as an ancient doctrine, and as the smallest part of anything.","cn":"八个义项沿同一个意象展开：一颗切不开的球；这一意象依次被读成元素单位、带轨道的核、身份的承载者、最小量、能源、计数单位、古代学说，以及任何事物的最小成分。"},"semanticMap":{"core":{"en":"CORE IMAGE: a solid ball that no knife can divide.","cn":"核心意象：一颗任何刀都切不开的实心球。"},"chain":["UNCUTTABLE","SMALLEST UNIT","NUCLEUS AND ORBITS","IDENTITY OF ELEMENT","SMALLEST AMOUNT","POWER SOURCE"],"branches":[{"senses":"S1 · S3","en":"THE UNIT: the smallest piece that still is the element.","cn":"单位：仍然是该元素的最小块。"},{"senses":"S2","en":"INNER STRUCTURE: a dense centre with electrons around it.","cn":"内部构造：致密中心与外围电子。"},{"senses":"S4 · S8","en":"SMALLEST AMOUNT: the idiom of 'not an atom', and the smallest part of anything.","cn":"最小量：「连一个原子都没有」的习语，以及任何事物的最小成分。"},{"senses":"S5","en":"POWER: the atom read as a source of energy and a weapon.","cn":"动力：原子被读成能源与武器。"},{"senses":"S6 · S7","en":"COUNT AND DOCTRINE: a unit in an equation, and an ancient claim about the void.","cn":"计数与学说：方程式中的单位，以及关于虚空的古代主张。"}]},"affixes":{"intro":{"en":"Atom is a Greek adjective-turned-noun with a negative prefix; English builds its family with Latin -ic and Greek -izein.","cn":"atom 是带否定前缀、由希腊形容词转成的名词；英语用拉丁 -ic 与希腊 -izein 构建其词族。"},"latinIntro":{"en":"Classical Latin borrowed atomus from Greek, so atomus is a real Latin word, though borrowed rather than inherited. New Latin atomicus supplies the adjective.","cn":"古典拉丁语从希腊语借入 atomus，因此 atomus 是真实的拉丁词，但属借词而非传承词。新拉丁语 atomicus 提供形容词。"},"items":[{"word":"atom","structure":"a- (not) + tomos (cut)","meaning":"the uncuttable unit","meaningCN":"不可分的单位","example":"One atom of hydrogen has a single proton.","exampleCN":"一个氢原子只有一个质子。"},{"word":"atoms","structure":"atom + -s (plural)","meaning":"more than one atom","meaningCN":"多个原子","example":"The crystal repeats the same atoms in order.","exampleCN":"晶体把同样的原子按序重复。"},{"word":"atomic","structure":"atom + -ic (relational)","meaning":"of atoms","meaningCN":"原子的","example":"Atomic radius grows down a group.","exampleCN":"原子半径沿族向下增大。"},{"word":"atomize","structure":"atom + -ize (verb)","meaning":"to reduce to tiny parts or droplets","meaningCN":"使分成极小部分；雾化","example":"The nozzle atomizes the fuel.","exampleCN":"喷嘴把燃料雾化。"},{"word":"atomizer","structure":"atomize + -er (agent)","meaning":"a device that makes fine droplets","meaningCN":"雾化器","example":"The atomizer clogged with salt.","exampleCN":"雾化器被盐堵塞。"},{"word":"atomism","structure":"atom + -ism (doctrine)","meaning":"the theory of indivisible units","meaningCN":"原子论","example":"Ancient atomism predicted void between atoms.","exampleCN":"古代原子论预设原子之间有虚空。"},{"word":"subatomic","structure":"sub- (below) + atomic","meaning":"smaller than an atom","meaningCN":"亚原子的","example":"Subatomic particles were found inside the atom.","exampleCN":"亚原子粒子在原子内部被发现。"},{"word":"diatomic","structure":"di- (two) + atomic","meaning":"made of two atoms","meaningCN":"双原子的","example":"Oxygen gas is diatomic.","exampleCN":"氧气是双原子分子。"},{"word":"atom probe","structure":"atom + probe (Latin proba, a test)","meaning":"an instrument that maps atoms one by one","meaningCN":"逐个成像原子的仪器","example":"The atom probe resolved single layers.","exampleCN":"原子探针分辨出单原子层。"}],"latinEntries":[{"word":"atomus","structure":"atomus, atomi (f., second declension; Greek loanword)","meaning":"an indivisible particle","meaningCN":"不可分的微粒"},{"word":"atomicus","structure":"New Latin atomicus (adj., first/second declension)","meaning":"relating to atoms","meaningCN":"与原子相关的"},{"word":"proba","structure":"proba, probae (f., first declension)","meaning":"a test, a proof","meaningCN":"检验；证明"}]}},{"word":"atomic","ipa_uk":"/əˈtɒmɪk/","ipa_us":"/əˈtɑːmɪk/","definition_zh":"原子的；原子层面的；与核能或原子武器相关的；极微小的","definition_en":"relating to atoms or to the scale of atoms, and by extension to nuclear energy or weapons","core_image":"一颗小球被放大镜框住，镜框边标注着「尺度：原子」，旁边的小字全是关于这颗球的参数","scene":"Atomic clocks lose less than a second in millions of years because they count the vibrations of atoms.","sceneCN":"这里 atomic 指「原子的、利用原子跃迁的」（第 2 个义项：在原子尺度上、由原子内部过程决定）；原子钟以原子振动计数，故极准确。图中可辨识物件：放大镜框、小球、尺度标注、参数小字。","pos":[{"tag":"adj.","zh":"原子的；原子层面的；核能的（多作定语）"}],"collocations":[{"phrase":"atomic number","zh":"原子序数"},{"phrase":"atomic mass","zh":"原子质量"},{"phrase":"atomic energy","zh":"原子能"},{"phrase":"atomic bomb","zh":"原子弹"},{"phrase":"atomic clock","zh":"原子钟"},{"phrase":"atomic layer deposition","zh":"原子层沉积"},{"phrase":"atomic structure","zh":"原子结构"}],"forms":[{"label":"比较级（少用）","form":"more atomic"},{"label":"副词形式","form":"atomically（在原子层面地）"},{"label":"名词原形","form":"atom（原子）"},{"label":"相关名词","form":"atomicity（原子价；原子性）"}],"derivatives":[{"word":"atom","pos":"n.","zh":"原子"},{"word":"atomically","pos":"adv.","zh":"在原子层面地"},{"word":"atomize","pos":"v.","zh":"雾化；原子化"},{"word":"subatomic","pos":"adj.","zh":"亚原子的"},{"word":"atomicity","pos":"n.","zh":"原子价；原子性"}],"senses":[{"no":"01","title":"Of atoms","titleCN":"原子的：归属","definition":"relating to atoms as objects","definitionCN":"与原子这一对象相关","example":"Atomic radii shrink across a period of the table.","exampleCN":"在元素周期表中，原子半径沿周期缩短。","why":"the -ic suffix makes a relational adjective, so the word begins as 'of atoms'.","whyCN":"后缀 -ic 造出关系形容词，因此这个词的起点是「原子的」。"},{"no":"02","title":"At the scale of atoms","titleCN":"原子尺度的：在原子层面","definition":"occurring or measured at the scale of single atoms","definitionCN":"在单个原子的尺度上发生或测量","example":"Atomic resolution now shows individual vacancies in a crystal.","exampleCN":"原子级分辨率如今能显示晶体中的单个空位。","why":"instruments reached a finer scale, and the adjective came to name that scale rather than the object.","whyCN":"仪器达到了更细的尺度，这个形容词便命名那个尺度，而非对象。"},{"no":"03","title":"Nuclear energy and weapons","titleCN":"核能的：原子能义","definition":"describing energy released from atomic nuclei, and the weapons that use it","definitionCN":"描述由原子核释放的能量，以及使用它的武器","example":"The first atomic test lit the desert before dawn.","exampleCN":"第一次原子试验在黎明前照亮了沙漠。","why":"mid-twentieth-century usage shifted 'atomic' from the atom as a whole to its nucleus, because that is where the energy is stored.","whyCN":"20 世纪中叶的用法把 atomic 从整个原子转向原子核，因为能量储存在那里。"},{"no":"04","title":"Of number and mass","titleCN":"原子序数与原子量的：化学计量","definition":"relating to the counted properties of atoms, such as atomic number and atomic mass","definitionCN":"与原子的可计数属性相关，如原子序数与原子质量","example":"The atomic number decides the element's place in the table.","exampleCN":"原子序数决定元素在周期表中的位置。","why":"chemistry needed fixed numbers for each element, so the adjective attached to those quantities.","whyCN":"化学需要每种元素的固定数值，这个形容词便附着在这些量上。"},{"no":"05","title":"Extremely small","titleCN":"极微小的：程度义","definition":"used in fixed phrases to mean extremely small, as in atomic amounts","definitionCN":"在固定搭配中表示极其微小，如「原子级的量」","example":"The difference was atomic and could not be seen by eye.","exampleCN":"差别极其微小，肉眼无法看见。","why":"if the atom is the smallest unit, 'atomic' naturally means 'as small as it gets' in ordinary speech.","whyCN":"如果原子是最小单位，那么 atomic 在日常语言中自然意为「小到极点」。"},{"no":"06","title":"Of precision from atoms","titleCN":"原子计量的：由原子内部过程给出精度","definition":"describing devices that use transitions inside atoms as a standard, such as atomic clocks","definitionCN":"描述以原子内部跃迁为标准的装置，如原子钟","example":"An atomic clock defines the second more precisely than any astronomical observation.","exampleCN":"原子钟定义秒的精度超过任何天文观测。","why":"because atoms vibrate at fixed frequencies, the adjective marks measurement that trusts the atom as a ruler.","whyCN":"由于原子以固定频率振动，这个形容词标记「以原子为尺」的测量。"},{"no":"07","title":"Building one layer at a time","titleCN":"原子层沉积的：技术义","definition":"describing a process that builds material one atomic layer at a time","definitionCN":"描述每次只构建一个原子层的过程","example":"Atomic layer deposition coats the chip in films a few atoms thick.","exampleCN":"原子层沉积在芯片上镀上几原子厚的薄膜。","why":"industry needed control at the smallest step, so the adjective marks processes measured in single layers.","whyCN":"工业需要对最小步骤进行控制，因此这个形容词标记以单层计量的工艺。"},{"no":"08","title":"Indivisible, in the old sense","titleCN":"不可分的：哲学旧义","definition":"carrying the older philosophical sense of 'indivisible'","definitionCN":"保留较早的「不可分割」这一哲学义","example":"The ancient claim was that matter is atomic, not continuous.","exampleCN":"古代主张物质是原子的、而非连续的。","why":"the word was born meaning 'uncuttable', so this oldest sense survives in historical and philosophical writing.","whyCN":"这个词诞生时意为「切不开的」，因此最古老的义项在历史与哲学写作中留存。"}],"etymology":{"intro":{"en":"Atomic is atom plus the relational suffix -ic. Atom comes from Greek atomos 'uncut', built on a- 'not' and temnein 'to cut'.","cn":"atomic 是 atom 加关系后缀 -ic。atom 出自希腊 atomos「不可切的」，由 a-「不」与 temnein「切」构成。"},"items":[{"era":"GREEK ATOMOS","en":"atomos meant 'uncut' and named the indivisible units of ancient atomism.","cn":"atomos 意为「不可切的」，指古代原子论中的不可分单元。"},{"era":"LATIN BORROWING","en":"Latin took the word as atomus; New Latin formed atomicus on the same stem.","cn":"拉丁语以 atomus 借入该词；新拉丁语在同一词干上造出 atomicus。"},{"era":"ENGLISH ARRIVAL","en":"The English adjective appears in the seventeenth century, at first for the philosophical sense; the first citation is approximate.","cn":"英语形容词于 17 世纪出现，最初用于哲学义；最早书证年代为约数。"},{"era":"DALTON AND CHEMISTRY","en":"Around 1808 the atomic theory gave the word its chemical footing, with atomic weight as a working quantity.","cn":"约 1808 年，原子论为该词奠定化学基础，原子量成为可用的量。"},{"era":"THE NUCLEAR ERA","en":"After 1945 atomic energy and atomic bomb shifted common usage from the atom to its nucleus.","cn":"1945 年之后，atomic energy 与 atomic bomb 把日常用法从原子转向原子核。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): temnein has no agreed pre-Greek origin, so any Indo-European root cited behind it is a reconstruction; the earliest English adjective is also approximate.","cn":"来源不确定（更深词源）：temnein 在希腊语之前的来源并无共识，所引的任何印欧词根均属重构；该英语形容词的最早书证亦为约数。"}]},"similar":{"note":{"en":"Group one holds words from the same stem that differ in part of speech or meaning; group two holds words about nuclear energy and about scale.","cn":"第一组是同词干、但词性或含义不同的词；第二组是关于核能与尺度的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"atom","ipa":"/ˈætəm/","tag":"the noun","definition":"The particle itself. Atomic only qualifies; a countable object needs the noun.","definitionCN":"指粒子本身；atomic 只是限定语，指可数对象须用名词。"},{"word":"atomize","ipa":"/ˈætəmaɪz/","tag":"the verb","definition":"To break a liquid into droplets or a solid into tiny parts; it names an action, not a property.","definitionCN":"指把液体雾化或把固体打碎；命名动作，不是性质。"},{"word":"anatomical","ipa":"/ˌænəˈtɒmɪkəl/","tag":"ana- + temnein, not atomos","definition":"Relating to anatomy, from ana- 'up' plus temnein 'to cut'. It shares the cutting root but not the negative prefix, so it is not an atomic relative.","definitionCN":"与解剖学相关，由 ana-「向上」加 temnein「切」构成；共享「切」的词根，却没有否定前缀，故与 atomic 不同族。"},{"word":"atomism","ipa":"/ˈætəmɪzəm/","tag":"the doctrine","definition":"The theory that matter consists of indivisible units; it names a belief, not a property.","definitionCN":"主张物质由不可分单元构成的学说；命名信念，不是性质。"}]},{"heading":"NEAR MEANING","entries":[{"word":"nuclear","ipa":"/ˈnjuːkliə(r)/","tag":"about the nucleus","definition":"Relating to the nucleus of an atom; atomic in its energy sense overlaps, but nuclear is the precise term.","definitionCN":"与原子的核相关；atomic 在能量义上与之重叠，但 nuclear 更精确。"},{"word":"subatomic","ipa":"/ˌsʌbəˈtɒmɪk/","tag":"smaller than atoms","definition":"Describing particles inside the atom, such as protons and electrons; it is one level below atomic.","definitionCN":"描述原子内部的粒子，如质子与电子；比 atomic 低一级。"},{"word":"molecular","ipa":"/məˈlekjələ(r)/","tag":"about molecules","definition":"Relating to molecules, which are groups of atoms; the scale is larger than atomic.","definitionCN":"与分子相关；分子是原子的集团，尺度大于原子。"},{"word":"minute","ipa":"/maɪˈnjuːt/","tag":"merely small","definition":"Extremely small in a general sense, with no reference to atoms; atomic in its figurative sense is narrower.","definitionCN":"泛指极小，与原子无关；atomic 的比喻义范围更窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"atom + -ic: the relational ending also seen in molecular and nuclear.","cn":"atom + -ic：与 molecular、nuclear 相同的关系词尾。"},{"en":"The family runs atom, atomic, atomically, atomize, subatomic, diatomic.","cn":"同族词包括 atom、atomic、atomically、atomize、subatomic、diatomic。"},{"en":"Fixed phrases: atomic number, atomic mass, atomic energy, atomic clock, atomic layer deposition.","cn":"固定搭配：原子序数、原子质量、原子能、原子钟、原子层沉积。"},{"en":"Two eras share the word: atomic theory for chemistry, atomic bomb for the nucleus.","cn":"两个时代共用这个词：化学用原子论，核时代用原子弹。"},{"en":"The oldest sense is 'uncuttable', which is why atomic can also mean indivisible in philosophy.","cn":"最古老的义项是「切不开」，所以 atomic 在哲学中也可指不可分。"}],"abstract":[{"en":"Picture a magnifying frame around a tiny ball, with all its measurements written at the rim.","cn":"想象一个放大镜框住一颗小球，框边写满它的测量值。"},{"en":"Picture a clock that keeps time by counting the shivering of a single atom.","cn":"想象一只钟靠数单个原子的颤动来走时。"},{"en":"Picture a bricklayer who lays one brick at a time and never two.","cn":"想象一位砌砖匠每次只放一块砖，绝不放两块。"}]},"examples":[{"en":"Atomic number fourteen means silicon.","cn":"原子序数十四意味着硅。"},{"en":"Atomic force microscopy can feel single atoms on a surface.","cn":"原子力显微镜能感知表面上的单个原子。"},{"en":"The treaty separates atomic energy from atomic weapons.","cn":"该条约把原子能与原子武器区分开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「原子（atom）＋ic」——与原子有关的、在原子尺度上的 → 原子的、原子能的","word":"atomic"},"root":"希腊 a-「不」+ temnein「切」→ atomos → 拉丁 atomus → 英语 atom + 拉丁 -icus → atomic。","sensesIntro":{"en":"Eight senses fan out from one relational suffix: atoms as objects, the atomic scale, nuclear power, counted numbers, extreme smallness, atomic precision, layer-by-layer building, and the old sense of indivisible.","cn":"八个义项从一个表关系的后缀散开：原子对象、原子尺度、核能、计数量、极小、原子精度、逐层构建，以及古老的「不可分」义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a magnifying frame around a tiny ball, its measurements written at the rim.","cn":"核心意象：放大镜框住一颗小球，框边写着它的各项测量值。"},"chain":["OF ATOMS","ATOMIC SCALE","INNER VIBRATION","COUNTED NUMBERS","RELEASED POWER","EXTREME SMALLNESS"],"branches":[{"senses":"S1","en":"OWNERSHIP: the plain relational sense, 'of atoms'.","cn":"归属：最朴素的关系义，「原子的」。"},{"senses":"S2 · S6 · S7","en":"SCALE AND PRECISION: atomic resolution, atomic clocks, and layers built one atom at a time.","cn":"尺度与精度：原子级分辨、原子钟，以及逐原子构建的层。"},{"senses":"S3","en":"POWER: the nucleus read as energy and as a weapon.","cn":"动力：原子核被读成能量与武器。"},{"senses":"S4","en":"COUNTING: number and mass, the quantities of chemistry.","cn":"计数：序数与质量，化学所用的量。"},{"senses":"S5 · S8","en":"SMALLNESS AND INDIVISIBILITY: from 'extremely small' back to the philosophical 'uncuttable'.","cn":"微小与不可分：从「极小」回到哲学的「切不开」。"}]},"affixes":{"intro":{"en":"Atomic is the Greek-derived noun atom plus the relational suffix -ic, from Latin -icus and Greek -ikos.","cn":"atomic 是希腊来源名词 atom 加关系后缀 -ic，后者出自拉丁 -icus 与希腊 -ikos。"},"latinIntro":{"en":"Latin borrowed atomus from Greek, and New Latin formed atomicus; the Latin words are real but borrowed rather than inherited.","cn":"拉丁语从希腊语借入 atomus，新拉丁语造出 atomicus；这些拉丁词真实存在，但属借词而非传承词。"},"items":[{"word":"atomic","structure":"atom + -ic (relational)","meaning":"of atoms","meaningCN":"原子的","example":"Atomic structure explains the periodic table.","exampleCN":"原子结构解释了周期表。"},{"word":"atomically","structure":"atomic + -ally (adverb)","meaning":"at the atomic level","meaningCN":"在原子层面地","example":"The surface is atomically flat.","exampleCN":"该表面在原子层面是平的。"},{"word":"atom","structure":"a- + tomos (cut)","meaning":"the uncuttable unit","meaningCN":"不可分的单位","example":"An atom of iron has twenty-six protons.","exampleCN":"一个铁原子有二十六个质子。"},{"word":"atomize","structure":"atom + -ize (verb)","meaning":"to reduce to fine parts","meaningCN":"使成极细部分","example":"The spray atomizes the sample.","exampleCN":"喷雾器把样品雾化。"},{"word":"subatomic","structure":"sub- (below) + atomic","meaning":"smaller than an atom","meaningCN":"亚原子的","example":"Subatomic forces hold the nucleus together.","exampleCN":"亚原子之力把核维系在一起。"},{"word":"diatomic","structure":"di- (two) + atomic","meaning":"consisting of two atoms","meaningCN":"双原子的","example":"Nitrogen gas is diatomic.","exampleCN":"氮气是双原子分子。"},{"word":"atomicity","structure":"atomic + -ity (state)","meaning":"the state of being atomic; valence","meaningCN":"原子性；原子价","example":"Atomicity fixes how many bonds form.","exampleCN":"原子价决定形成几个键。"},{"word":"atomic number","structure":"atomic + number (Latin numerus)","meaning":"the proton count of an element","meaningCN":"元素的质子数","example":"Atomic number defines the element.","exampleCN":"原子序数定义元素。"},{"word":"atomic clock","structure":"atomic + clock (Latin clocca, bell)","meaning":"a clock regulated by atomic transitions","meaningCN":"以原子跃迁校准的钟","example":"The atomic clock is the time standard.","exampleCN":"原子钟是时间标准。"}],"latinEntries":[{"word":"atomus","structure":"atomus, atomi (f., second declension; Greek loanword)","meaning":"an indivisible particle","meaningCN":"不可分的微粒"},{"word":"atomicus","structure":"New Latin atomicus (adj., first/second declension)","meaning":"relating to atoms","meaningCN":"与原子相关的"},{"word":"numerus","structure":"numerus, numeri (m., second declension)","meaning":"number","meaningCN":"数目"}]}},{"word":"organic","ipa_uk":"/ɔːˈɡænɪk/","ipa_us":"/ɔːrˈɡænɪk/","definition_zh":"有机的；与生物体有关的；含碳骨架的（化学）；不用化肥农药的（农业）；自然生长而成的","definition_en":"relating to living things or to carbon-based compounds, and by extension grown without synthetic chemicals or developed naturally as a whole","core_image":"一棵植物从土壤里长出来，根、茎、叶彼此相连，整株像一件长成的器官而不是拼装的零件","scene":"Organic vegetables are grown without synthetic pesticides or soluble fertilizers.","sceneCN":"这里 organic 指「有机的（不用化肥农药的）」（第 3 个义项：农业上指以有机方式种植）；蔬菜不用合成农药与可溶化肥。图中可辨识物件：植物、土壤、根茎叶的连通、无化学瓶罐。","pos":[{"tag":"n.","zh":"有机食品；有机作物（作名词时多用于复数 organics，或 the organic 指有机农业）"},{"tag":"adj.","zh":"有机的；生物体的；含碳的；有机耕作的；自然演成的"}],"collocations":[{"phrase":"organic matter","zh":"有机物"},{"phrase":"organic compound","zh":"有机化合物"},{"phrase":"organic farming","zh":"有机农业"},{"phrase":"organic food","zh":"有机食品"},{"phrase":"organic growth","zh":"有机增长；自然增长"},{"phrase":"organic chemistry","zh":"有机化学"},{"phrase":"organic disease","zh":"器质性疾病"}],"forms":[{"label":"复数（作名词）","form":"organics（有机产品）"},{"label":"比较级","form":"more organic"},{"label":"最高级","form":"most organic"},{"label":"副词形式","form":"organically（有机地；自然地）"},{"label":"名词形式","form":"organicity（有机性，少用）"}],"derivatives":[{"word":"organ","pos":"n.","zh":"器官；机构"},{"word":"organism","pos":"n.","zh":"生物体"},{"word":"organization","pos":"n.","zh":"组织；机构"},{"word":"organically","pos":"adv.","zh":"有机地；自然地"},{"word":"inorganic","pos":"adj.","zh":"无机的"}],"senses":[{"no":"01","title":"Of living things","titleCN":"有机的：与生物体有关","definition":"relating to living organisms or to the structures they build","definitionCN":"与活生物或其构成的构造相关","example":"Soil organic matter feeds the whole food web.","exampleCN":"土壤有机物养活了整个食物网。","why":"Greek organon named a tool, and a body's tools are its organs; 'organic' therefore starts as 'having organs', that is, belonging to a living body.","whyCN":"希腊 organon 指工具，而身体的工具就是器官；因此 organic 起初意为「有器官的」，即属于活体。"},{"no":"02","title":"Carbon-based chemistry","titleCN":"有机化学义：含碳骨架的化合物","definition":"describing compounds built on carbon skeletons, the chemistry once thought to require life","definitionCN":"描述以碳骨架为基础的化合物，这一化学领域曾被以为只能由生命产生","example":"Methane is the simplest organic compound.","exampleCN":"甲烷是最简单的有机化合物。","why":"because such compounds were first obtained only from living things, the word was carried over to the whole class even after they were synthesized in the lab.","whyCN":"由于这类化合物最初只能从生物得到，即使后来能在实验室合成，这个词仍被沿用到整类物质上。"},{"no":"03","title":"Grown without synthetics","titleCN":"农业义：不用化肥农药的","definition":"describing food grown without synthetic pesticides or soluble mineral fertilizers","definitionCN":"描述不用合成农药或可溶矿物肥料的种植方式","example":"Organic apples cost more because the orchard yields less.","exampleCN":"有机苹果更贵，因为果园产量更低。","why":"the farming sense borrows the idea of a whole living system, treating the soil as something to be fed rather than dosed.","whyCN":"农业义借用「活着的整体系统」这一观念，把土壤当作需要喂养的东西，而不是投药的对象。"},{"no":"04","title":"Grown as a whole, not assembled","titleCN":"演化义：自然生长、整体关联的","definition":"describing something that develops naturally as an interconnected whole rather than being assembled from parts","definitionCN":"描述作为相互关联的整体自然发展，而非由零件拼装","example":"The firm's growth was organic, not the result of acquisitions.","exampleCN":"该公司的增长是自然生长，而非并购的结果。","why":"since the body grows from within, 'organic' also means growth by inner development rather than by outside assembly, and business borrowed that.","whyCN":"由于身体是从内部长成的，organic 也指由内在发展而非外部拼装的成长，商业领域借用了这一层。"},{"no":"05","title":"Of the organs in medicine","titleCN":"医学义：器质性的","definition":"describing disease that has a structural change in an organ rather than a purely functional one","definitionCN":"描述器官有结构改变、而非纯功能性的疾病","example":"The scan ruled out organic disease of the stomach.","exampleCN":"扫描排除了胃的器质性病变。","why":"medicine must separate damage to an organ from symptoms without a lesion, so 'organic' marks the structural case.","whyCN":"医学必须把器官的结构损伤与无病灶的症状分开，因此 organic 标记结构性的那一类。"},{"no":"06","title":"Parts that belong together","titleCN":"结构义：组织上相互关联的","definition":"describing a structure whose parts are interdependent, like the organs of a body","definitionCN":"描述各部分相互依赖的结构，如同身体的器官","example":"The report describes an organic link between the two agencies.","exampleCN":"报告把两个机构之间的关系描述为有机联系。","why":"if organs serve one body, then any set of parts serving one end can be called organic.","whyCN":"如果各器官服务于同一个身体，那么任何共赴一目的的一组部件都可以叫 organic。"},{"no":"07","title":"Foundational law and acts","titleCN":"根本性义：作为根本法规的","definition":"describing a basic constitutional document or act, as in organic law","definitionCN":"描述根本性的宪制文件或法令，如「组织法」","example":"The status of the territory is set by an organic act.","exampleCN":"该领地的地位由一部组织法规定。","why":"a body needs a skeleton, so a state's founding instrument is called organic: it is what the rest is built onto.","whyCN":"身体需要骨骼，因此国家的立国文件被称为「有机的」：其余一切都建在它之上。"},{"no":"08","title":"Whole food, whole system","titleCN":"食品义：作为整体未被拆解的","definition":"describing food or a system treated as an intact whole rather than as isolated components","definitionCN":"描述被当作完整整体、而非孤立成分处理的食品或系统","example":"The shop sells organics alongside conventional produce.","exampleCN":"这家店把有机产品与常规农产品并排出售。","why":"the market turned the adjective into a noun, so 'organics' now names the goods themselves.","whyCN":"市场把这个形容词变成名词，因此 organics 现在指商品本身。"}],"etymology":{"intro":{"en":"Organic comes from Greek organon 'tool, instrument', through Latin organum and the medieval adjective organicus. The dates below are approximate.","cn":"organic 出自希腊 organon「工具、器具」，经拉丁 organum 与中世纪形容词 organicus 而来。以下年代均为约数。"},"items":[{"era":"GREEK ORGANON","en":"organon named a tool or instrument, and in philosophy a means of doing something. From it comes the sense of a body part that does work.","cn":"organon 指工具或器具，也指哲学上达成某目的的手段。由它引申出「做工作的身体部件」这一义。"},{"era":"LATIN ORGANUM","en":"Latin borrowed organum for an instrument and, in later use, a musical instrument; the body-part sense developed in anatomy.","cn":"拉丁语借入 organum 指器具，后亦指乐器；身体部件的义项在解剖学中发展起来。"},{"era":"MEDIEVAL ORGANICUS","en":"Medieval Latin organicus meant 'of an organ' or 'having organs'; English took the adjective in this anatomical sense first.","cn":"中世纪拉丁 organicus 意为「器官的」或「有器官的」；英语先在这个解剖学意义上使用该形容词。"},{"era":"CHEMISTRY 1800s","en":"Around 1800 chemists divided compounds into organic, from living things, and inorganic; urea's laboratory synthesis in 1828 weakened the boundary but the name stayed.","cn":"约 1800 年，化学家把化合物分为来自生物的 organic 与 inorganic；1828 年尿素在实验室被合成，动摇了这条界线，但名称保留。"},{"era":"FARMING 1900s","en":"The twentieth century applied the word to farming that avoids synthetic inputs, treating soil as a living system.","cn":"20 世纪把这个词用于避免合成投入物的耕作方式，把土壤当作活系统。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (deeper origin): organon's pre-Greek origin is not established, so any Indo-European form behind it is a reconstruction rather than a recorded word.","cn":"来源不确定（更深词源）：organon 在希腊语之前的来源并无定论，其背后的任何印欧形式都是重构，而非有记录的实际词。"}]},"similar":{"note":{"en":"Group one holds words from the same Greek stem that name different things; group two holds words often used where organic could be chosen.","cn":"第一组是同出希腊词干、但指不同事物的词；第二组是常与 organic 互换使用的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"organ","ipa":"/ˈɔːɡən/","tag":"the body part or institution","definition":"A part of a body or an organisation, not a quality; organic is the adjective describing such a whole.","definitionCN":"指身体或机构的部件，不是性质；organic 是描述这类整体的形容词。"},{"word":"organism","ipa":"/ˈɔːɡənɪzəm/","tag":"the living thing","definition":"A complete living being; it shares organon but names an entity, not a property.","definitionCN":"指完整的生物体；共享 organon，但命名实体而非性质。"},{"word":"organization","ipa":"/ˌɔːɡənaɪˈzeɪʃn/","tag":"the arranged group","definition":"A structured group of people, from the same stem via 'organize'. It names an institution, not a growing whole.","definitionCN":"指有结构的人群，由同一词干经 organize 而来；命名机构，不是生长的整体。"},{"word":"inorganic","ipa":"/ˌɪnɔːˈɡænɪk/","tag":"the negated counterpart","definition":"Not built on carbon and not from life; it is the direct opposite in chemistry and farming.","definitionCN":"不以碳为基础、非来自生命；在化学与农业中与 organic 直接相对。"}]},{"heading":"NEAR MEANING","entries":[{"word":"natural","ipa":"/ˈnætʃrəl/","tag":"untouched by people","definition":"Not made or altered by humans; organic in farming also implies natural methods, but natural says nothing about certification.","definitionCN":"非人力制造或改动的；农业中的 organic 也含自然方式，但 natural 不涉及认证。"},{"word":"biological","ipa":"/ˌbaɪəˈlɒdʒɪkəl/","tag":"of life as a science","definition":"Relating to biology or to living processes; it names the science, while organic names a property of matter.","definitionCN":"与生物学或生命过程相关；命名学科，而 organic 命名物质属性。"},{"word":"wholesome","ipa":"/ˈhəʊlsəm/","tag":"good for health","definition":"Good for health or morally sound; organic food is often called wholesome, but the words answer different questions.","definitionCN":"有益健康或品德端正；有机食品常被称 wholesome，但两词回答不同问题。"},{"word":"structured","ipa":"/ˈstrʌktʃəd/","tag":"deliberately arranged","definition":"Arranged by an outside plan; organic growth is the opposite of planned assembly.","definitionCN":"按外部方案安排；organic growth 恰与计划拼装相反。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek organon 'tool': a body's tools are its organs, so organic first means 'having organs'.","cn":"希腊 organon「工具」：身体的工具就是器官，所以 organic 起初意为「有器官的」。"},{"en":"The family runs organ, organism, organization, organic, organically, inorganic.","cn":"同族词包括 organ、organism、organization、organic、organically、inorganic。"},{"en":"Fixed phrases: organic matter, organic compound, organic farming, organic growth, organic chemistry.","cn":"固定搭配：有机物、有机化合物、有机农业、自然增长、有机化学。"},{"en":"Chemistry pairs it with inorganic; farming pairs it with conventional.","cn":"化学中与 inorganic 相对；农业中与常规耕作相对。"},{"en":"The business sense is 'grown from within', the opposite of bought through acquisitions.","cn":"商业义是「从内部长成」，与靠并购得来相反。"}],"abstract":[{"en":"Picture a plant whose root, stem and leaf all serve one life.","cn":"想象一株植物，根、茎、叶都服务于同一条生命。"},{"en":"Picture a city that grew along its roads instead of being stamped out at once.","cn":"想象一座城市沿道路长出来，而不是一次压印成形。"},{"en":"Picture a table whose legs are not attached but grown from the same wood.","cn":"想象一张桌子，桌腿不是装上去的，而是与桌面同一块木料长出来的。"}]},"examples":[{"en":"Organic matter in the soil holds water between grains.","cn":"土壤中的有机物在颗粒之间持水。"},{"en":"Organic chemistry began with compounds isolated from plants and animals.","cn":"有机化学始于从动植物中分离出的化合物。"},{"en":"The company preferred organic growth to borrowing for acquisitions.","cn":"公司更愿自然增长，而不是借钱并购。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「有器官（organ）的」——凡活物长成的、含碳的、不用化肥的 → 有机的","word":"organic"},"root":"希腊 organon「工具、器具」→ 拉丁 organum → 中世纪拉丁 organicus「有器官的」→ 英语 organic；19 世纪扩展为化学义。","sensesIntro":{"en":"Eight senses follow one image: a body's parts all serve one life; that image is read as living matter, as carbon chemistry, as chemical-free farming, as growth from within, as structural disease, as interdependence, as a founding law, and as goods sold under that label.","cn":"八个义项沿同一个意象展开：身体的各部分都服务于同一条生命；这一意象依次被读成生命物质、碳化学、无合成投入的耕作、由内生长、器质性疾病、相互依赖、立国根本法，以及以此标签出售的商品。"},"semanticMap":{"core":{"en":"CORE IMAGE: root, stem and leaf all serving one living whole, with nothing bolted on.","cn":"核心意象：根、茎、叶都服务于同一个活的整体，没有一件是外装的。"},"chain":["BODY WITH ORGANS","LIFE MATERIAL","CARBON SKELETON","GROWN WITHOUT INPUTS","GROWN FROM WITHIN","ONE INTERLOCKED WHOLE"],"branches":[{"senses":"S1","en":"LIVING MATTER: the oldest sense, matter that belongs to a body.","cn":"生命物质：最古老的义项，属于身体的物质。"},{"senses":"S2","en":"CHEMISTRY: the carbon class, named when such compounds came only from life.","cn":"化学：碳化合物这一类，命名时它们只来自生命。"},{"senses":"S3 · S8","en":"FARMING AND GOODS: soil fed as a living system, and produce sold as organics.","cn":"农业与商品：把土壤当活系统来养，以及作为 organic 产品出售。"},{"senses":"S4","en":"GROWTH: development from within, borrowed by business for unplanned expansion.","cn":"生长：由内发展，商业借指非计划性扩张。"},{"senses":"S5 · S6 · S7","en":"STRUCTURE: organ damage in medicine, interdependent parts, and a state's founding law.","cn":"结构：医学上的器官损伤、相互依赖的部件，以及国家的立国根本法。"}]},"affixes":{"intro":{"en":"Organic is Greek organon plus the Latin adjectival ending -icus, kept in English as -ic; the family also uses -ism and -ize.","cn":"organic 是希腊 organon 加拉丁形容词词尾 -icus，在英语中保留为 -ic；词族还用 -ism 与 -ize。"},"latinIntro":{"en":"Latin organum is a borrowed Greek word, and medieval organicus is a Latin formation on it; both are real Latin, though the root is Greek.","cn":"拉丁 organum 是借自希腊语的词，中世纪 organicus 是在其上形成的拉丁词；二者都是真实的拉丁语，但词根属希腊语。"},"items":[{"word":"organic","structure":"organum + -icus (relational)","meaning":"of organs, of living things; carbon-based","meaningCN":"器官的、生物的；含碳的","example":"Organic waste can be composted.","exampleCN":"有机废物可以堆肥。"},{"word":"organically","structure":"organic + -ally (adverb)","meaning":"in an organic way","meaningCN":"以有机方式；自然地","example":"The farm is organically certified.","exampleCN":"该农场获得有机认证。"},{"word":"organ","structure":"organon (Greek tool) → organum","meaning":"a body part that does work","meaningCN":"承担工作的身体部件","example":"The liver is the largest internal organ.","exampleCN":"肝脏是最大的内部器官。"},{"word":"organism","structure":"organ + -ism (entity)","meaning":"a complete living being","meaningCN":"完整的生物体","example":"A single organism can be a whole forest patch.","exampleCN":"单个生物体可以是一整片林地。"},{"word":"organization","structure":"organ + -ize + -ation","meaning":"an arranged body of people","meaningCN":"有安排的人群体系","example":"The organization rewrote its charter.","exampleCN":"该组织重写了章程。"},{"word":"inorganic","structure":"in- (not) + organic","meaning":"not carbon-based, not from life","meaningCN":"非碳基的、非来自生命的","example":"Inorganic salts dissolve in the water.","exampleCN":"无机盐溶于水。"},{"word":"organic matter","structure":"organic + matter (Latin materia)","meaning":"dead or living material from organisms","meaningCN":"来自生物的活或死的物质","example":"Organic matter improves soil texture.","exampleCN":"有机物改善土壤质地。"},{"word":"organic chemistry","structure":"organic + chemistry (Greek khemeia)","meaning":"the chemistry of carbon compounds","meaningCN":"研究碳化合物的化学","example":"Organic chemistry began with natural products.","exampleCN":"有机化学始于天然产物。"},{"word":"organelle","structure":"organ + -elle (small)","meaning":"a small organ of a cell","meaningCN":"细胞内的小器官","example":"The chloroplast is an organelle.","exampleCN":"叶绿体是一种细胞器。"}],"latinEntries":[{"word":"organum","structure":"organum, organi (n., second declension; Greek loanword)","meaning":"tool, instrument; organ","meaningCN":"工具；器具；器官"},{"word":"organicus","structure":"Medieval Latin organicus (adj., first/second declension)","meaning":"of an organ; having organs","meaningCN":"器官的；有器官的"},{"word":"materia","structure":"materia, materiae (f., first declension)","meaning":"matter, material","meaningCN":"物质；材料"}]}}]);
